class Httplib2PerRequestTimeoutFilter(
    logging.Filter
):
    """
    httplib2.Http側にtimeoutを設定済みの場合でも
    google_auth_httplib2が出力する既知の警告だけを除外する。
    その他のgoogle_auth_httplib2ログは保持する。
    """

    def filter(
        self,
        record,
    ):
        message = (
            record.getMessage()
        )

        return (
            "httplib2 transport does not support "
            "per-request timeout."
            not in message
        )


logging.getLogger(
    "google_auth_httplib2"
).addFilter(
    Httplib2PerRequestTimeoutFilter()
)


