@app.after_request
def add_sensitive_page_headers(response):
    path = request.path or ""

    if (
        path.startswith("/admin")
        or path.startswith("/vendor")
        or path.startswith("/partner/consent")
        or path.startswith("/solar/result/")
        or path.startswith("/solar/vendor/")
    ):
        response.headers[
            "Cache-Control"
        ] = (
            "private, no-store, "
            "no-cache, max-age=0"
        )

        response.headers[
            "Pragma"
        ] = "no-cache"

        response.headers[
            "Expires"
        ] = "0"

    response.headers[
        "X-Frame-Options"
    ] = "DENY"

    response.headers[
        "X-Content-Type-Options"
    ] = "nosniff"

    response.headers[
        "Referrer-Policy"
    ] = "no-referrer"

    response.headers[
        "Strict-Transport-Security"
    ] = (
        "max-age=31536000; "
        "includeSubDomains"
    )

    response.headers[
        "Permissions-Policy"
    ] = (
        "camera=(), "
        "microphone=(), "
        "geolocation=()"
    )

    return response


