PARTNER_TERMS_VERSION = "1.0"


def make_partner_consent_token(
    vendor_id,
    terms_version,
    meeting_date,
):
    payload = (
        f"{vendor_id}|"
        f"{terms_version}|"
        f"{meeting_date}"
    )

    return hmac.new(
        ADMIN_API_KEY.encode("utf-8"),
        payload.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()


def verify_partner_consent_token(
    vendor_id,
    terms_version,
    meeting_date,
    token,
):
    if (
        not ADMIN_API_KEY
        or not token
    ):
        return False

    expected = (
        make_partner_consent_token(
            vendor_id,
            terms_version,
            meeting_date,
        )
    )

    return hmac.compare_digest(
        expected,
        token,
    )


def build_partner_consent_url(
    vendor,
):
    vendor_id = str(
        vendor.get(
            "vendor_id",
            "",
        )
    ).strip()

    terms_version = str(
        vendor.get(
            "terms_version",
            "",
        )
    ).strip()

    meeting_date = str(
        vendor.get(
            "meeting_date",
            "",
        )
    ).strip()


    if (
        not vendor_id
        or not terms_version
        or not meeting_date
        or not ADMIN_API_KEY
    ):
        return ""


    token = (
        make_partner_consent_token(
            vendor_id,
            terms_version,
            meeting_date,
        )
    )


    return (
        f"{SERVICE_BASE_URL}"
        f"/partner/consent/"
        f"{quote(vendor_id)}"
        f"?token={quote(token)}"
    )

