# LINE API
# =========================================================

def line_api_request(endpoint, payload):
    data = json.dumps(
        payload,
        ensure_ascii=False,
    ).encode("utf-8")

    req = urllib.request.Request(
        endpoint,
        data=data,
        method="POST",
        headers={
            "Authorization":
                f"Bearer {CHANNEL_ACCESS_TOKEN}",
            "Content-Type":
                "application/json",
        },
    )

    with urllib.request.urlopen(
        req,
        timeout=15,
    ) as response:
        return response.status


def reply_messages(reply_token, messages):
    return line_api_request(
        "https://api.line.me/v2/bot/message/reply",
        {
            "replyToken": reply_token,
            "messages": messages,
        },
    )


def reply_text(reply_token, text):
    return reply_messages(
        reply_token,
        [
            {
                "type": "text",
                "text": text,
            }
        ],
    )


def reply_quick(reply_token, text, options):
    items = []

    for label, data in options:
        items.append({
            "type": "action",
            "action": {
                "type": "postback",
                "label": label,
                "data": data,
                "displayText": label,
            },
        })

    return reply_messages(
        reply_token,
        [
            {
                "type": "text",
                "text": text,
                "quickReply": {
                    "items": items,
                },
            }
        ],
    )


def push_message(user_id, messages):
    return line_api_request(
        "https://api.line.me/v2/bot/message/push",
        {
            "to": user_id,
            "messages": messages,
        },
    )


