# =========================================================
# Google Sheets
# =========================================================

def get_sheets_service():

    # 同一HTTPリクエスト中は
    # Sheets serviceも再利用する
    if has_request_context():

        service = getattr(
            g,
            "_sheets_service",
            None,
        )

        if service is not None:
            return service


    service_build_started = (
        time.perf_counter()
    )

    credentials, _ = google.auth.default(
        scopes=[
            "https://www.googleapis.com/auth/spreadsheets"
        ]
    )

    http = httplib2.Http(
        timeout=30,
    )

    authorized_http = (
        google_auth_httplib2.AuthorizedHttp(
            credentials,
            http=http,
        )
    )

    service = build(
        "sheets",
        "v4",
        http=authorized_http,
        cache_discovery=False,
    )

    SHEETS_PERF_SERVICE_BUILD_EVENTS.append(
        {
            "seconds":
                time.perf_counter()
                - service_build_started,
        }
    )


    if has_request_context():
        g._sheets_service = service


    return service



def begin_solar_header_batch():
    """
    同一HTTPリクエスト内でsolar ensureの
    ヘッダー更新を一時的にまとめる。
    """
    if not has_request_context():
        return

    g._solar_header_batch_active = True
    g._solar_header_batch_pending = []


def update_solar_header_range(
    range_name,
    values,
):
    """
    batch中は更新を保留し、
    batch外では従来どおり即時更新する。
    """
    if (
        has_request_context()
        and getattr(
            g,
            "_solar_header_batch_active",
            False,
        )
    ):
        pending = getattr(
            g,
            "_solar_header_batch_pending",
            None,
        )

        if pending is None:
            pending = []
            g._solar_header_batch_pending = pending

        pending.append(
            {
                "range": range_name,
                "values": values,
            }
        )
        return

    update_sheet_range(
        range_name,
        values,
    )


def flush_solar_header_batch():
    """
    保留中のsolarヘッダー更新を
    values.batchUpdate 1回で送信する。
    """
    if not has_request_context():
        return

    pending = list(
        getattr(
            g,
            "_solar_header_batch_pending",
            [],
        )
    )

    g._solar_header_batch_active = False
    g._solar_header_batch_pending = []

    if not pending:
        return

    service = get_sheets_service()

    (
        service.spreadsheets()
        .values()
        .batchUpdate(
            spreadsheetId=
                SPREADSHEET_ID,
            body={
                "valueInputOption": "RAW",
                "data": [
                    {
                        "range":
                            item["range"],
                        "values":
                            item["values"],
                    }
                    for item in pending
                ],
            },
        )
        .execute()
    )

    clear_sheet_request_cache()


def get_sheet_titles_cached():
    """
    同一HTTPリクエスト中の
    spreadsheet metadata取得を1回に共有する。
    """

    if has_request_context():

        cached = getattr(
            g,
            "_sheet_titles_cache",
            None,
        )

        if cached is not None:
            return set(cached)

    service = get_sheets_service()

    metadata = (
        service.spreadsheets()
        .get(
            spreadsheetId=
                SPREADSHEET_ID,
            fields=
                "sheets.properties.title",
        )
        .execute()
    )

    titles = {
        str(
            sheet.get(
                "properties",
                {},
            ).get(
                "title",
                "",
            )
            or ""
        )
        for sheet in metadata.get(
            "sheets",
            [],
        )
    }

    if has_request_context():
        g._sheet_titles_cache = set(
            titles
        )

    return titles


def clear_sheet_titles_request_cache():

    if not has_request_context():
        return

    if hasattr(
        g,
        "_sheet_titles_cache",
    ):
        delattr(
            g,
            "_sheet_titles_cache",
        )


def clear_sheet_request_cache():

    if not has_request_context():
        return


    if hasattr(
        g,
        "_sheet_values_cache",
    ):
        g._sheet_values_cache = {}



SHEETS_PERF_GET_RANGES = []
SHEETS_PERF_ENSURE_CALLS = {}

# 実Sheets通信計測
SHEETS_PERF_CACHE_STATS = {
    "hits": 0,
    "misses": 0,
}
SHEETS_PERF_API_EVENTS = []
SHEETS_PERF_SERVICE_BUILD_EVENTS = []


def reset_sheets_perf_stats():
    SHEETS_PERF_GET_RANGES.clear()
    SHEETS_PERF_ENSURE_CALLS.clear()

    SHEETS_PERF_CACHE_STATS[
        "hits"
    ] = 0
    SHEETS_PERF_CACHE_STATS[
        "misses"
    ] = 0

    SHEETS_PERF_API_EVENTS.clear()
    SHEETS_PERF_SERVICE_BUILD_EVENTS.clear()


def get_sheets_perf_stats():
    return {
        "get_ranges":
            list(
                SHEETS_PERF_GET_RANGES
            ),
        "ensure_calls":
            dict(
                SHEETS_PERF_ENSURE_CALLS
            ),
        "cache_hits":
            SHEETS_PERF_CACHE_STATS[
                "hits"
            ],
        "cache_misses":
            SHEETS_PERF_CACHE_STATS[
                "misses"
            ],
        "api_events":
            [
                dict(event)
                for event in
                SHEETS_PERF_API_EVENTS
            ],
        "service_build_events":
            [
                dict(event)
                for event in
                SHEETS_PERF_SERVICE_BUILD_EVENTS
            ],
    }


def prefetch_sheet_values(
    range_names,
):
    """
    複数rangeをSheets batchGetで一括取得し、
    同一HTTPリクエスト内のget_sheet_valuesキャッシュへ投入する。

    GET画面高速化専用。
    """
    range_names = [
        str(name)
        for name in range_names
        if name
    ]

    if not range_names:
        return {}

    # request context外ではキャッシュ共有の意味がないため
    # 通常getへフォールバック
    if not has_request_context():
        return {
            name: get_sheet_values(name)
            for name in range_names
        }

    cache = getattr(
        g,
        "_sheet_values_cache",
        None,
    )

    if cache is None:
        cache = {}
        g._sheet_values_cache = cache

    missing = [
        name
        for name in range_names
        if name not in cache
    ]

    if missing:
        service = get_sheets_service()

        last_error = None
        result = None

        for attempt in range(3):

            try:
                api_started = (
                    time.perf_counter()
                )

                try:
                    result = (
                        service.spreadsheets()
                        .values()
                        .batchGet(
                            spreadsheetId=
                                SPREADSHEET_ID,
                            ranges=
                                missing,
                        )
                        .execute()
                    )

                except Exception:
                    SHEETS_PERF_API_EVENTS.append(
                        {
                            "range":
                                "BATCHGET: "
                                + " | ".join(
                                    missing
                                ),
                            "attempt":
                                attempt + 1,
                            "seconds":
                                time.perf_counter()
                                - api_started,
                            "success":
                                False,
                        }
                    )
                    raise

                SHEETS_PERF_API_EVENTS.append(
                    {
                        "range":
                            "BATCHGET: "
                            + " | ".join(
                                missing
                            ),
                        "attempt":
                            attempt + 1,
                        "seconds":
                            time.perf_counter()
                            - api_started,
                        "success":
                            True,
                    }
                )

                break

            except HttpError as e:

                last_error = e

                status = getattr(
                    e.resp,
                    "status",
                    None,
                )

                retryable_statuses = {
                    429,
                    500,
                    502,
                    503,
                    504,
                }

                if (
                    status
                    in retryable_statuses
                    and attempt < 2
                ):

                    # 2秒 → 4秒
                    wait_seconds = (
                        2 ** (
                            attempt + 1
                        )
                    )

                    print(
                        "SHEETS BATCH READ RETRY:",
                        " | ".join(
                            missing
                        ),
                        f"wait={wait_seconds}s",
                        flush=True,
                    )

                    time.sleep(
                        wait_seconds
                    )

                    continue

                raise

        if result is None:
            if last_error:
                raise last_error

            raise RuntimeError(
                "Sheets batchGetの"
                "取得結果がありません。"
            )

        value_ranges = result.get(
            "valueRanges",
            [],
        )

        if len(value_ranges) != len(missing):
            raise RuntimeError(
                "Sheets batchGetの"
                "valueRanges数が一致しません。"
            )

        for name, item in zip(
            missing,
            value_ranges,
        ):
            rows = item.get(
                "values",
                [],
            )

            cache[name] = [
                list(row)
                for row in rows
            ]

    return {
        name: [
            list(row)
            for row in cache.get(
                name,
                [],
            )
        ]
        for name in range_names
    }


def get_sheet_values(range_name):

    SHEETS_PERF_GET_RANGES.append(
        range_name
    )

    # ---------------------------------------------
    # 同一HTTPリクエスト内キャッシュ
    # ---------------------------------------------

    cache = None

    if has_request_context():

        cache = getattr(
            g,
            "_sheet_values_cache",
            None,
        )

        if cache is None:

            cache = {}

            g._sheet_values_cache = cache


        if range_name in cache:

            SHEETS_PERF_CACHE_STATS[
                "hits"
            ] += 1

            # 呼び出し側による変更の影響を
            # キャッシュ本体へ与えない
            return [
                list(row)
                for row in cache[
                    range_name
                ]
            ]


    SHEETS_PERF_CACHE_STATS[
        "misses"
    ] += 1

    service = get_sheets_service()


    # ---------------------------------------------
    # 429対策
    # 最大3回再試行
    # ---------------------------------------------

    last_error = None

    for attempt in range(3):

        try:

            api_started = (
                time.perf_counter()
            )

            try:
                result = (
                    service.spreadsheets()
                    .values()
                    .get(
                        spreadsheetId=
                            SPREADSHEET_ID,

                        range=
                            range_name,
                    )
                    .execute()
                )
            except Exception:
                SHEETS_PERF_API_EVENTS.append(
                    {
                        "range":
                            range_name,
                        "attempt":
                            attempt + 1,
                        "seconds":
                            time.perf_counter()
                            - api_started,
                        "success":
                            False,
                    }
                )
                raise

            SHEETS_PERF_API_EVENTS.append(
                {
                    "range":
                        range_name,
                    "attempt":
                        attempt + 1,
                    "seconds":
                        time.perf_counter()
                        - api_started,
                    "success":
                        True,
                }
            )

            rows = result.get(
                "values",
                [],
            )


            if cache is not None:

                cache[
                    range_name
                ] = [
                    list(row)
                    for row in rows
                ]


            return [
                list(row)
                for row in rows
            ]


        except HttpError as e:

            last_error = e

            status = getattr(
                e.resp,
                "status",
                None,
            )


            retryable_statuses = {
                429,
                500,
                502,
                503,
                504,
            }

            if (
                status in retryable_statuses
                and attempt < 2
            ):

                # 2秒 → 4秒
                wait_seconds = (
                    2 ** (
                        attempt + 1
                    )
                )

                print(
                    "SHEETS READ RETRY:",
                    range_name,
                    f"wait={wait_seconds}s",
                    flush=True,
                )

                time.sleep(
                    wait_seconds
                )

                continue


            raise


    if last_error:
        raise last_error

    return []



def append_sheet_row(
    range_name,
    row,
):

    service = get_sheets_service()

    (
        service.spreadsheets()
        .values()
        .append(
            spreadsheetId=
                SPREADSHEET_ID,

            range=
                range_name,

            valueInputOption=
                "RAW",

            insertDataOption=
                "INSERT_ROWS",

            body={
                "values": [
                    row
                ]
            },
        )
        .execute()
    )


    # 同じリクエスト内で
    # 書込後に再読込する場合に備える
    clear_sheet_request_cache()



def update_sheet_range(
    range_name,
    values,
):

    service = get_sheets_service()

    (
        service.spreadsheets()
        .values()
        .update(
            spreadsheetId=
                SPREADSHEET_ID,

            range=
                range_name,

            valueInputOption=
                "RAW",

            body={
                "values":
                    values
            },
        )
        .execute()
    )


    # 同じリクエスト内で
    # 書込後に再読込する場合に備える
    clear_sheet_request_cache()



