# =========================================================

def find_line_state(user_id):
    rows = get_sheet_values(
        "LINE状態!A2:D"
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if row and row[0] == user_id:
            return {
                "row_number": index,
                "user_id": row[0],
                "case_id":
                    row[1]
                    if len(row) > 1
                    else "",
                "step":
                    row[2]
                    if len(row) > 2
                    else "",
                "updated_at":
                    row[3]
                    if len(row) > 3
                    else "",
            }

    return None


def upsert_line_state(
    user_id,
    case_id,
    step,
):
    current_time = now_text()

    state = find_line_state(
        user_id
    )

    if state:
        row_num = state["row_number"]

        update_sheet_range(
            f"LINE状態!A{row_num}:D{row_num}",
            [[
                user_id,
                case_id,
                step,
                current_time,
            ]],
        )

    else:
        append_sheet_row(
            "LINE状態!A:D",
            [
                user_id,
                case_id,
                step,
                current_time,
            ],
        )



