def is_contact_mode(user_id):
    state = find_contact_state(
        user_id
    )

    return bool(
        state
        and state.get("state")
        == "WAIT_CONTACT_MESSAGE"
    )


def clear_contact_mode(user_id):
    state = find_contact_state(
        user_id
    )

    if not state:
        return

    row_num = state["row_number"]

    update_sheet_range(
        f"お問い合わせ状態!A{row_num}:C{row_num}",
        [[
            user_id,
            "",
            now_text(),
        ]],
    )


def save_contact_message(
    user_id,
    message,
    case_id="",
):
    message = str(
        message or ""
    ).strip()

    if not message:
        raise ValueError(
            "Contact message is empty"
        )

    if len(message) > 2000:
        raise ValueError(
            "Contact message is too long"
        )

    append_sheet_row(
        "お問い合わせ!A:E",
        [
            now_text(),
            user_id,
            message,
            str(case_id or "").strip(),
            "未対応",
        ],
    )



def notify_admin_contact(
    message,
    case_id="",
):
    """
    新規お問い合わせを管理者LINEへ通知する。

    通知失敗によって顧客側の
    お問い合わせ受付を失敗させない。
    """
    admin_user_id = str(
        ADMIN_LINE_USER_ID or ""
    ).strip()

    if not admin_user_id:
        print(
            "ADMIN CONTACT NOTIFY SKIPPED: "
            "ADMIN_LINE_USER_ID is empty",
            flush=True,
        )
        return False

    message = str(
        message or ""
    ).strip()

    case_id = str(
        case_id or ""
    ).strip()

    received_at = now_text()

    case_text = (
        case_id
        if case_id
        else "なし"
    )

    admin_url = (
        f"{SERVICE_BASE_URL}"
        "/admin/contacts"
    )

    notify_text = (
        "【新規お問い合わせ】\n\n"
        f"受付日時：{received_at}\n"
        f"案件ID：{case_text}\n\n"
        "内容：\n"
        f"{message}\n\n"
        "管理画面：\n"
        f"{admin_url}"
    )

    try:
        status = push_message(
            admin_user_id,
            [
                {
                    "type": "text",
                    "text": notify_text,
                }
            ],
        )

        print(
            "ADMIN CONTACT NOTIFY OK:",
            status,
            flush=True,
        )

        return True

    except Exception as e:
        print(
            "ADMIN CONTACT NOTIFY ERROR:",
            type(e).__name__,
            flush=True,
        )

        return False


def get_contact_records():
    rows = get_sheet_values(
        "お問い合わせ!A2:E"
    )

    records = []

    for index, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * (
            5 - len(row)
        )

        received_at = str(
            row[0] or ""
        ).strip()

        user_id = str(
            row[1] or ""
        ).strip()

        message = str(
            row[2] or ""
        ).strip()

        case_id = str(
            row[3] or ""
        ).strip()

        status = str(
            row[4] or ""
        ).strip()

        if not (
            received_at
            or user_id
            or message
            or case_id
            or status
        ):
            continue

        if not status:
            status = "未対応"

        records.append({
            "row_number": index,
            "received_at":
                received_at,
            "user_id":
                user_id,
            "message":
                message,
            "case_id":
                case_id,
            "status":
                status,
        })

    records.sort(
        key=lambda item:
            item["row_number"],
        reverse=True,
    )

    return records


def update_contact_status(
    row_number,
    status,
):
    allowed_statuses = {
        "未対応",
        "対応中",
        "対応済み",
    }

    if status not in allowed_statuses:
        raise ValueError(
            "お問い合わせステータスが不正です。"
        )

    try:
        row_number = int(
            row_number
        )

    except (
        TypeError,
        ValueError,
    ):
        raise ValueError(
            "お問い合わせ行番号が不正です。"
        )

    if row_number < 2:
        raise ValueError(
            "お問い合わせ行番号が不正です。"
        )

    rows = get_sheet_values(
        "お問い合わせ!A2:E"
    )

    max_row = len(rows) + 1

    if row_number > max_row:
        raise ValueError(
            "お問い合わせが見つかりません。"
        )

    target = rows[
        row_number - 2
    ]

    if not target:
        raise ValueError(
            "お問い合わせが見つかりません。"
        )

    update_sheet_range(
        f"お問い合わせ!E{row_number}",
        [[status]],
    )


