# 案件
# =========================================================

def find_case_row(
    case_id,
    case_rows=None,
):
    rows = (
        case_rows
        if case_rows is not None
        else get_sheet_values(
            "案件!A2:AJ"
        )
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if row and row[0] == case_id:
            return index, row

    return None, None


def update_case_column(
    case_id,
    column_letter,
    value,
):
    row_num, _ = find_case_row(
        case_id
    )

    if not row_num:
        raise ValueError(
            f"Case not found: {case_id}"
        )

    update_sheet_range(
        f"案件!{column_letter}{row_num}",
        [[value]],
    )

    update_sheet_range(
        f"案件!N{row_num}",
        [[now_text()]],
    )


def generate_case_id():
    date_str = now_jst().strftime(
        "%Y%m%d"
    )

    prefix = f"SK-{date_str}-"

    rows = get_sheet_values(
        "案件!A2:A"
    )

    max_number = 0

    for row in rows:
        if not row:
            continue

        case_id = str(
            row[0] or ""
        ).strip()

        if not case_id.startswith(
            prefix
        ):
            continue

        suffix = case_id[
            len(prefix):
        ]

        if not suffix.isdigit():
            continue

        number = int(
            suffix
        )

        if number > max_number:
            max_number = number

    # GCS世代条件で案件IDを原子的に確保する。
    # 同時受付時に同一IDが発行されることを防ぐ。
    for offset in range(
        1,
        1001,
    ):
        candidate = (
            f"{prefix}"
            f"{max_number + offset:03d}"
        )

        if reserve_case_id(
            candidate
        ):
            return candidate

    raise RuntimeError(
        "案件IDを確保できませんでした。"
    )


SERVICE_TYPE_TOSOU = "tosou"
SERVICE_TYPE_KURASHI = "kurashi"
SERVICE_TYPE_SOLAR = "solar"

ALLOWED_SERVICE_TYPES = {
    SERVICE_TYPE_TOSOU,
    SERVICE_TYPE_KURASHI,
    SERVICE_TYPE_SOLAR,
}

SERVICE_TYPE_LABELS = {
    SERVICE_TYPE_TOSOU: "塗装",
    SERVICE_TYPE_KURASHI: "くらし",
    SERVICE_TYPE_SOLAR: "太陽光・蓄電池",
}


def normalize_service_type(
    service_type,
):
    service_type = str(
        service_type or ""
    ).strip().lower()

    # 既存案件との後方互換。
    # サービス種別が未設定なら塗装として扱う。
    if not service_type:
        return SERVICE_TYPE_TOSOU

    if service_type not in ALLOWED_SERVICE_TYPES:
        raise ValueError(
            "サービス種別が不正です。"
        )

    return service_type


def get_service_type_label(
    service_type,
):
    service_type = normalize_service_type(
        service_type
    )

    return SERVICE_TYPE_LABELS.get(
        service_type,
        service_type,
    )


def get_case_service_type(
    case_id,
    row_num=None,
):
    if row_num is None:
        row_num, _ = find_case_row(
            case_id
        )

    if not row_num:
        raise ValueError(
            f"Case not found: {case_id}"
        )

    values = get_sheet_values(
        f"案件!AK{row_num}:AK{row_num}"
    )

    service_type = ""

    if (
        values
        and values[0]
    ):
        service_type = str(
            values[0][0] or ""
        ).strip()

    return normalize_service_type(
        service_type
    )


def create_case(
    user_id,
    area_name,
    service_type=SERVICE_TYPE_TOSOU,
    use_line_state=True,
):
    service_type = normalize_service_type(
        service_type
    )

    case_id = generate_case_id()

    current_time = now_text()

    update_sheet_range(
        "案件!AC1:AK1",
        [[
            "案件種別",
            "建物種別",
            "建物規模",
            "前回塗装時期",
            "症状・相談内容",
            "見積希望会社数",
            "既存見積資料状況",
            "既存見積業者名",
            "サービス種別",
        ]],
    )


    append_sheet_row(
        "案件!A:AK",
        [
            case_id,
            current_time,
            user_id,
            "",
            area_name,
            "",
            "",
            "",
            "",
            "",
            "",
            "受付中",
            "",
            current_time,
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",  # AC 案件種別
            "",  # AD 建物種別
            "",  # AE 建物規模
            "",  # AF 前回塗装時期
            "",  # AG 症状・相談内容
            "",  # AH 見積希望会社数
            "",  # AI 既存見積資料状況
            "",  # AJ 既存見積業者名
            service_type,  # AK サービス種別
        ],
    )

    if use_line_state:
        if not str(user_id or "").strip():
            raise ValueError(
                "LINE受付ではLINE User IDが必要です。"
            )

        upsert_line_state(
            user_id,
            case_id,
            "WAIT_REQUEST_TYPE",
        )

    return case_id


def get_company_name(
    row,
    company_code,
):
    row = row + [""] * (
        28 - len(row)
    )

    mapping = {
        "A": row[15],
        "B": row[18],
        "C": row[21],
    }

    return mapping.get(
        company_code,
        "",
    )


