def find_customer_info_row(
    case_id,
):
    rows = get_sheet_values(
        "顧客情報!A2:K"
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if row and row[0] == case_id:
            return index, row

    return None, None


def upsert_customer_selection(
    case_id,
    user_id,
    company_code,
    company_name,
):
    row_num, existing_row = (
        find_customer_info_row(
            case_id
        )
    )

    if row_num and existing_row:
        existing_row = (
            existing_row
            + [""] * (
                11 - len(existing_row)
            )
        )

        # 施工会社の選択だけ更新し、
        # 既に取得済みの顧客情報は保持する。
        values = [
            case_id,
            user_id,
            company_code,
            company_name,
            existing_row[4],
            existing_row[5],
            existing_row[6],
            existing_row[7],
            existing_row[8],
            "同意待ち",
            existing_row[10],
        ]

        update_sheet_range(
            f"顧客情報!A{row_num}:K{row_num}",
            [values],
        )

    else:
        values = [
            case_id,
            user_id,
            company_code,
            company_name,
            "",
            "",
            "",
            "",
            "",
            "同意待ち",
            "",
        ]

        append_sheet_row(
            "顧客情報!A:K",
            values,
        )


def update_customer_info_column(
    case_id,
    column_letter,
    value,
):
    row_num, _ = (
        find_customer_info_row(
            case_id
        )
    )

    if not row_num:
        raise ValueError(
            "顧客情報が見つかりません。"
        )

    update_sheet_range(
        f"顧客情報!"
        f"{column_letter}{row_num}",
        [[value]],
    )


