def get_customer_info_provision_rows():
    rows = get_sheet_values(
        "顧客情報提供履歴!A2:K"
    )

    result = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        if not row:
            continue

        row = row + [""] * (
            11 - len(row)
        )

        result.append({
            "row_number": row_number,
            "record_id": row[0],
            "case_id": row[1],
            "vendor_id": row[2],
            "company_name": row[3],
            "can_provide": row[4],
            "consent_at": row[5],
            "provided_at": row[6],
            "method": row[7],
            "registered_at": row[8],
            "updated_at": row[9],
            "note": row[10],
        })

    return result


def customer_info_is_provided(
    case_id,
    vendor_id,
):
    case_id = str(
        case_id or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    if (
        not case_id
        or not vendor_id
    ):
        return False

    for item in (
        get_customer_info_provision_rows()
    ):
        if (
            item[
                "case_id"
            ] == case_id
            and item[
                "vendor_id"
            ] == vendor_id
            and str(
                item[
                    "can_provide"
                ] or ""
            ).strip() == "提供済み"
            and item[
                "provided_at"
            ]
        ):
            return True

    return False


def get_customer_info_provided_at(
    case_id,
    vendor_id,
):
    case_id = str(
        case_id or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    if (
        not case_id
        or not vendor_id
    ):
        return ""

    for item in (
        get_customer_info_provision_rows()
    ):
        if (
            item[
                "case_id"
            ] == case_id
            and item[
                "vendor_id"
            ] == vendor_id
            and str(
                item[
                    "can_provide"
                ] or ""
            ).strip() == "提供済み"
            and item[
                "provided_at"
            ]
        ):
            return str(
                item[
                    "provided_at"
                ]
                or ""
            ).strip()

    return ""


def record_customer_info_provision(
    case_id,
    vendor_id,
    company_name,
    consent_at,
    method="管理画面",
    note="",
):
    case_id = str(
        case_id or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    company_name = str(
        company_name or ""
    ).strip()

    if (
        not case_id
        or not vendor_id
    ):
        raise ValueError(
            "案件IDまたは業者IDが空です。"
        )

    for item in (
        get_customer_info_provision_rows()
    ):
        if (
            item[
                "case_id"
            ] == case_id
            and item[
                "vendor_id"
            ] == vendor_id
            and item[
                "provided_at"
            ]
        ):
            return item[
                "provided_at"
            ]

    current_time = now_text()

    record_id = (
        "CP-"
        + now_jst().strftime(
            "%Y%m%d%H%M%S"
        )
        + "-"
        + secrets.token_hex(3)
    )

    append_sheet_row(
        "顧客情報提供履歴!A:K",
        [
            record_id,
            case_id,
            vendor_id,
            company_name,
            "提供済み",
            consent_at,
            current_time,
            method,
            current_time,
            current_time,
            note,
        ],
    )

    return current_time


