def mark_customer_info_provided(
    case_id,
    provided_at=None,
):
    customer_row_num, customer_row = (
        find_customer_info_row(
            case_id
        )
    )

    if (
        not customer_row_num
        or not customer_row
    ):
        raise ValueError(
            "顧客情報が見つかりません。"
        )

    customer_row = customer_row + [""] * (
        11 - len(customer_row)
    )

    if not customer_row[7]:
        raise ValueError(
            "個人情報提供への"
            "同意日時が記録されていません。"
        )

    if (
        not customer_row[4]
        or not customer_row[5]
        or not customer_row[6]
    ):
        raise ValueError(
            "氏名・住所・電話番号が"
            "すべて入力されていません。"
        )

    referral_row_num, referral_row = (
        find_referral_row(
            case_id
        )
    )

    if (
        not referral_row_num
        or not referral_row
    ):
        raise ValueError(
            "紹介・成約データが"
            "見つかりません。"
        )

    referral_row = referral_row + [""] * (
        16 - len(referral_row)
    )

    provided_at = (
        str(provided_at or "").strip()
        or now_text()
    )

    # 顧客情報 J列
    update_sheet_range(
        f"顧客情報!J{customer_row_num}",
        [["提供済み"]],
    )

    # 紹介・成約 O/P
    referral_row[14] = provided_at
    referral_row[15] = "提供済み"

    update_sheet_range(
        f"紹介・成約!"
        f"A{referral_row_num}:P{referral_row_num}",
        [referral_row[:16]],
    )

    # 案件ステータス
    update_case_column(
        case_id,
        "L",
        "施工会社紹介済み",
    )

    return provided_at


# =========================================================
# 現地調査・成約・紹介料管理
# =========================================================

def parse_money(value):
    value = str(value or "").replace(",", "").strip()

    if not value:
        return None

    try:
        return int(float(value))
    except Exception:
        raise ValueError(
            "金額は数字で入力してください。"
        )


def parse_fee_rate(value):
    value = str(value or "").strip()

    if not value:
        return None

    try:
        rate = float(value)
    except Exception:
        raise ValueError(
            "紹介料率は数字で入力してください。"
        )

    if rate < 0 or rate > 100:
        raise ValueError(
            "紹介料率は0〜100%の範囲で入力してください。"
        )

    return rate


def calculate_referral_fee(
    contract_amount,
    referral_rate,
    tax_rate=10,
):
    """
    税込契約金額から税抜相当額を算出し、
    その税抜相当額に紹介料率を掛ける。

    戻り値:
      contract_amount       税込契約金額
      tax_exclusive_amount  税抜相当額
      referral_rate         紹介料率
      fee_amount            紹介料本体（税抜・最低1,500円）
      tax_rate              消費税率
      tax_amount            紹介料の消費税
      billing_amount        紹介料請求総額
    """

    contract_amount_num = parse_money(
        contract_amount
    )

    referral_rate_num = parse_fee_rate(
        referral_rate
    )

    tax_rate_num = parse_fee_rate(
        tax_rate
    )

    if (
        contract_amount_num is None
        or contract_amount_num <= 0
    ):
        raise ValueError(
            "契約金額は1円以上で"
            "指定してください。"
        )

    if referral_rate_num is None:
        raise ValueError(
            "紹介料率を正しく"
            "指定してください。"
        )

    if tax_rate_num is None:
        raise ValueError(
            "消費税率を正しく"
            "指定してください。"
        )

    contract_amount_num = int(
        contract_amount_num
    )

    # 税込契約金額から税抜相当額を逆算する。
    # 1円未満は切り捨て。
    tax_exclusive_amount = int(
        contract_amount_num
        * 100
        / (100 + tax_rate_num)
    )

    # 紹介料本体も1円未満切り捨て。
    fee_amount = int(
        tax_exclusive_amount
        * referral_rate_num
        / 100
    )

    # 最低紹介料本体は1,500円。
    # 通常計算額が1,500円未満の場合は
    # 1,500円を適用する。
    fee_amount = max(
        fee_amount,
        1500,
    )

    # 紹介料に対する消費税も1円未満切り捨て。
    tax_amount = int(
        fee_amount
        * tax_rate_num
        / 100
    )

    billing_amount = (
        fee_amount
        + tax_amount
    )

    return {
        "contract_amount":
            contract_amount_num,

        "tax_exclusive_amount":
            tax_exclusive_amount,

        "referral_rate":
            referral_rate_num,

        "fee_amount":
            fee_amount,

        "tax_rate":
            tax_rate_num,

        "tax_amount":
            tax_amount,

        "billing_amount":
            billing_amount,
    }


def save_sales_management(
    case_id,
    survey_date,
    formal_estimate,
    contract_date,
    contract_amount,
    referral_rate,
    payment_status,
    note,
):
    referral_row_num, referral_row = (
        find_referral_row(case_id)
    )

    if not referral_row_num:
        raise ValueError(
            "紹介・成約データが見つかりません。"
        )

    referral_row = referral_row + [""] * (
        16 - len(referral_row)
    )

    # 入金状況は請求管理を正本とする。
    # 案件詳細画面からのPOST値では変更しない。
    payment_status = str(
        referral_row[12] or ""
    ).strip()

    survey_date = validate_date_string(
        survey_date,
        "現地調査日",
    )

    contract_date = validate_date_string(
        contract_date,
        "成約日",
    )

    formal_estimate_num = parse_money(
        formal_estimate
    )

    contract_amount_num = parse_money(
        contract_amount
    )

    referral_rate_num = parse_fee_rate(
        referral_rate
    )

    if (
        formal_estimate_num is not None
        and formal_estimate_num < 0
    ):
        raise ValueError(
            "正式見積額は0円以上で"
            "入力してください。"
        )

    has_contract_date = bool(
        contract_date
    )

    has_contract_amount = (
        contract_amount_num is not None
    )

    if (
        has_contract_date
        != has_contract_amount
    ):
        raise ValueError(
            "成約日と契約金額は"
            "両方を入力してください。"
        )

    if (
        has_contract_amount
        and contract_amount_num <= 0
    ):
        raise ValueError(
            "契約金額は1円以上で"
            "入力してください。"
        )

    if (
        has_contract_date
        and referral_rate_num is None
    ):
        raise ValueError(
            "成約時は紹介料率を"
            "入力してください。"
        )

    referral_fee = ""

    if (
        contract_amount_num is not None
        and referral_rate_num is not None
    ):
        referral_fee_result = (
            calculate_referral_fee(
                contract_amount_num,
                referral_rate_num,
                10,
            )
        )

        referral_fee = (
            referral_fee_result[
                "fee_amount"
            ]
        )

    if (
        contract_date
        and contract_amount_num is not None
        and not payment_status
    ):
        payment_status = "未請求"

    allowed_payment_status = [
        "",
        "未請求",
        "請求済み",
        "一部入金",
        "入金済み",
        "対象外",
        "取消",
    ]

    if payment_status not in allowed_payment_status:
        raise ValueError(
            "入金状況の値が不正です。"
        )

    # =====================================================
    # 決済開始後の成約条件変更を禁止
    #
    # 決済管理の着手金・残金のどちらか一方でも
    # 顧客決済が開始されている場合、
    # 成約日・契約金額・紹介料率を変更すると
    # 「紹介・成約」と「決済管理」で金額が
    # 不一致になるため、保存前に拒否する。
    # =====================================================
    if (
        contract_date
        and contract_amount_num is not None
        and referral_rate_num is not None
        and uses_new_payment_flow(
            contract_date
        )
    ):
        existing_payments = (
            get_payment_records(
                case_id=case_id
            )
        )

        payment_plan_locked = any(
            (
                str(
                    item.get(
                        "payment_status",
                        "",
                    )
                    or ""
                ).strip()
                not in (
                    "",
                    "決済待ち",
                )
                or str(
                    item.get(
                        "customer_payment_amount",
                        "",
                    )
                    or ""
                ).strip()
                or str(
                    item.get(
                        "customer_payment_date",
                        "",
                    )
                    or ""
                ).strip()
            )
            for item in existing_payments
        )

        if payment_plan_locked:
            current_contract_date = str(
                referral_row[8] or ""
            ).strip()

            current_contract_amount = (
                parse_money(
                    referral_row[9]
                )
            )

            current_referral_rate = (
                parse_fee_rate(
                    referral_row[10]
                )
            )

            changed = (
                contract_date
                != current_contract_date
                or contract_amount_num
                != current_contract_amount
                or referral_rate_num
                != current_referral_rate
            )

            if changed:
                raise ValueError(
                    "顧客決済開始後は、"
                    "成約日・契約金額・紹介料率を"
                    "変更できません。"
                    "契約変更・解除が必要な場合は、"
                    "決済管理で個別に処理してください。"
                )

    # G 現地調査日
    referral_row[6] = survey_date

    # H 正式見積額
    referral_row[7] = (
        formal_estimate_num
        if formal_estimate_num is not None
        else ""
    )

    # I 成約日
    referral_row[8] = contract_date

    # J 契約金額
    referral_row[9] = (
        contract_amount_num
        if contract_amount_num is not None
        else ""
    )

    # K 紹介料率
    referral_row[10] = (
        referral_rate_num
        if referral_rate_num is not None
        else ""
    )

    # L 紹介料
    referral_row[11] = referral_fee

    # M 入金状況
    referral_row[12] = payment_status

    # N 備考
    referral_row[13] = note

    update_sheet_range(
        f"紹介・成約!"
        f"A{referral_row_num}:P{referral_row_num}",
        [referral_row[:16]],
    )

    # 案件ステータス
    # 決済状態とは分離して管理する。
    # 入金済みであっても案件を自動で「完了」にはしない。
    #
    # また「施工会社紹介済み」は、
    # 実際に顧客情報を提供した
    # mark_customer_info_provided() のみで設定する。
    # 現地調査・成約情報が未入力の場合は、
    # 現在の案件ステータスを維持する。
    case_status_row_num, case_status_row = (
        find_case_row(
            case_id
        )
    )

    if (
        not case_status_row_num
        or not case_status_row
    ):
        raise ValueError(
            "案件データが見つかりません。"
        )

    case_status_row = (
        case_status_row
        + [""] * (
            36 - len(case_status_row)
        )
    )

    current_status = str(
        case_status_row[11]
        or ""
    ).strip()

    status = current_status

    if contract_date or contract_amount_num is not None:
        status = "成約"

        update_case_column(
            case_id,
            "L",
            status,
        )

    elif survey_date:
        status = "現地調査済み"

        update_case_column(
            case_id,
            "L",
            status,
        )


    # =====================================================
    # 決済管理
    #
    # 成約日・契約金額・紹介料率が揃った時点で、
    # 着手金50% / 完工後残額50% の
    # 2決済レコードを自動生成する。
    #
    # 既存レコードがある場合は
    # create_case_payment_records() 側で
    # 二重生成を防止する。
    # =====================================================

    payment_result = {
        "created": [],
        "skipped": [],
        "created_count": 0,
        "skipped_count": 0,
    }

    if (
        contract_date
        and contract_amount_num is not None
        and referral_rate_num is not None
        and uses_new_payment_flow(
            contract_date
        )
    ):
        case_row_num, case_row = (
            find_case_row(
                case_id
            )
        )

        if (
            not case_row_num
            or not case_row
        ):
            raise ValueError(
                "案件データが見つかりません。"
            )

        case_row = case_row + [""] * (
            36 - len(case_row)
        )

        # 案件シートF列の工事種別を
        # 精算上の案件名として使用する。
        case_name = str(
            case_row[5] or ""
        ).strip()

        customer_row_num, customer_row = (
            find_customer_info_row(
                case_id
            )
        )

        if (
            not customer_row_num
            or not customer_row
        ):
            raise ValueError(
                "顧客情報が見つかりません。"
            )

        customer_row = (
            customer_row
            + [""] * (
                11 - len(customer_row)
            )
        )

        selected_slot = str(
            customer_row[2] or ""
        ).strip()

        if selected_slot not in (
            "A",
            "B",
            "C",
        ):
            raise ValueError(
                "成約先の会社枠を"
                "特定できません。"
            )

        customer_name = str(
            customer_row[4] or ""
        ).strip()

        if not customer_name:
            raise ValueError(
                "お客様氏名が"
                "登録されていません。"
            )

        assignments = (
            get_current_vendor_assignments(
                case_id
            )
        )

        assignment = (
            assignments.get(
                selected_slot,
                {},
            )
            or {}
        )

        vendor_id = str(
            assignment.get(
                "vendor_id",
                "",
            )
            or ""
        ).strip()

        assigned_company_name = str(
            assignment.get(
                "company_name",
                "",
            )
            or ""
        ).strip()

        if not vendor_id:
            raise ValueError(
                "成約先の提携業者IDを"
                "特定できません。"
            )

        referral_company_name = str(
            referral_row[1] or ""
        ).strip()

        if (
            referral_company_name
            and assigned_company_name
            and referral_company_name
            != assigned_company_name
        ):
            raise ValueError(
                "成約先会社と案件業者割当の"
                "会社が一致しません。"
                "業者割当を確認してください。"
            )

        company_name = (
            assigned_company_name
            or referral_company_name
        )

        payment_result = (
            create_case_payment_records(
                case_id=case_id,
                case_name=case_name,
                customer_name=customer_name,
                vendor_id=vendor_id,
                company_name=company_name,
                contract_amount=
                    contract_amount_num,
                referral_rate=
                    referral_rate_num,
            )
        )


    billing_result = {
        "created": False,
        "updated": False,
        "locked": False,
    }


    # -----------------------------------------------------
    # 旧請求方式
    #
    # 新決済フロー開始日前の案件だけ、
    # 従来の紹介料請求を生成する。
    #
    # 2026-08-21以降は、
    # 顧客 → 決済会社 → 当社 → 提携業者
    # の新決済・精算方式を使用するため、
    # 提携業者への旧紹介料請求は生成しない。
    # -----------------------------------------------------
    if (
        contract_date
        and contract_amount_num is not None
        and referral_rate_num is not None
        and referral_fee != ""
        and not uses_new_payment_flow(
            contract_date
        )
    ):

        company_name = str(
            referral_row[1]
            or ""
        ).strip()

        billing_result = (
            upsert_referral_billing_record(
                case_id,
                contract_date,
                contract_amount_num,
                referral_rate_num,
                referral_fee,
                company_name,
            )
        )


    return {
        "status": status,
        "referral_fee": referral_fee,
        "billing": billing_result,
        "payment": payment_result,
    }




