# =========================================================
# 決済管理
# =========================================================

# 新決済フロー適用開始日
# この日以降の成約案件のみ、
# 「顧客 → 決済会社 → 当社 → 提携業者」
# の決済・精算方式を適用する。
NEW_PAYMENT_FLOW_START_DATE = "2026-08-21"


def uses_new_payment_flow(
    contract_date,
):
    contract_date = str(
        contract_date or ""
    ).strip()

    if not contract_date:
        return False

    try:
        contract_dt = datetime.strptime(
            contract_date,
            "%Y-%m-%d",
        ).date()

        start_dt = datetime.strptime(
            NEW_PAYMENT_FLOW_START_DATE,
            "%Y-%m-%d",
        ).date()

    except Exception:
        raise ValueError(
            "新決済フロー判定用の"
            "成約日が不正です。"
        )

    return contract_dt >= start_dt



