def build_monthly_settlement_candidates(
    target_month=None,
):
    target_month = str(
        target_month or ""
    ).strip()

    if (
        target_month
        and not re.match(
            r"^\d{4}-\d{2}$",
            target_month,
        )
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    groups = {}

    for record in get_payment_records():

        payment_status = str(
            record.get(
                "payment_status",
                "",
            )
            or ""
        ).strip()

        if (
            payment_status
            != "当社入金確認済み"
        ):
            continue

        settlement_status = str(
            record.get(
                "settlement_status",
                "",
            )
            or ""
        ).strip()

        if (
            settlement_status
            != "精算待ち"
        ):
            continue

        record_month = str(
            record.get(
                "settlement_target_month",
                "",
            )
            or ""
        ).strip()

        if not record_month:
            continue

        if (
            target_month
            and record_month
            != target_month
        ):
            continue

        vendor_id = str(
            record.get(
                "vendor_id",
                "",
            )
            or ""
        ).strip()

        if not vendor_id:
            continue

        monthly_settlement_id = str(
            record.get(
                "monthly_settlement_id",
                "",
            )
            or ""
        ).strip()

        # 既に月次精算へ紐付いているものは
        # 新しい候補へ含めない。
        if monthly_settlement_id:
            continue

        key = (
            record_month,
            vendor_id,
        )

        if key not in groups:
            groups[key] = {
                "target_month":
                    record_month,

                "vendor_id":
                    vendor_id,

                "company_name":
                    str(
                        record.get(
                            "company_name",
                            "",
                        )
                        or ""
                    ).strip(),

                "detail_count":
                    0,

                "customer_payment_amount":
                    0,

                "company_deposit_amount":
                    0,

                "payment_provider_fee":
                    0,

                "fee_amount":
                    0,

                "tax_amount":
                    0,

                "company_deduction_amount":
                    0,

                "vendor_payment_amount":
                    0,

                "details":
                    [],
            }

        group = groups[key]

        customer_payment_amount = (
            parse_money(
                record.get(
                    "customer_payment_amount",
                    "",
                )
            )
            or 0
        )

        company_deposit_amount = (
            parse_money(
                record.get(
                    "company_deposit_amount",
                    "",
                )
            )
            or 0
        )

        payment_provider_fee = (
            parse_money(
                record.get(
                    "payment_provider_fee",
                    "",
                )
            )
            or 0
        )

        fee_amount = (
            parse_money(
                record.get(
                    "fee_amount",
                    "",
                )
            )
            or 0
        )

        tax_amount = (
            parse_money(
                record.get(
                    "tax_amount",
                    "",
                )
            )
            or 0
        )

        company_deduction_amount = (
            parse_money(
                record.get(
                    "company_deduction_amount",
                    "",
                )
            )
            or 0
        )

        vendor_payment_amount = (
            parse_money(
                record.get(
                    "vendor_payment_amount",
                    "",
                )
            )
            or 0
        )

        group[
            "detail_count"
        ] += 1

        group[
            "customer_payment_amount"
        ] += customer_payment_amount

        group[
            "company_deposit_amount"
        ] += company_deposit_amount

        group[
            "payment_provider_fee"
        ] += payment_provider_fee

        group[
            "fee_amount"
        ] += fee_amount

        group[
            "tax_amount"
        ] += tax_amount

        group[
            "company_deduction_amount"
        ] += company_deduction_amount

        group[
            "vendor_payment_amount"
        ] += vendor_payment_amount

        group["details"].append({
            "payment_id":
                record.get(
                    "payment_id",
                    "",
                ),

            "case_id":
                record.get(
                    "case_id",
                    "",
                ),

            "case_name":
                record.get(
                    "case_name",
                    "",
                ),

            "customer_name":
                record.get(
                    "customer_name",
                    "",
                ),

            "vendor_id":
                vendor_id,

            "company_name":
                record.get(
                    "company_name",
                    "",
                ),

            "payment_type":
                record.get(
                    "payment_type",
                    "",
                ),

            "payment_method":
                record.get(
                    "payment_method",
                    "",
                ),

            "customer_payment_amount":
                customer_payment_amount,

            "customer_payment_date":
                record.get(
                    "customer_payment_date",
                    "",
                ),

            "company_deposit_amount":
                company_deposit_amount,

            "company_deposit_confirmed_date":
                record.get(
                    "company_deposit_confirmed_date",
                    "",
                ),

            "payment_provider_fee":
                payment_provider_fee,

            "referral_rate":
                record.get(
                    "referral_rate",
                    "",
                ),

            "fee_amount":
                fee_amount,

            "tax_rate":
                record.get(
                    "tax_rate",
                    "",
                ),

            "tax_amount":
                tax_amount,

            "company_deduction_amount":
                company_deduction_amount,

            "vendor_payment_amount":
                vendor_payment_amount,

            "settlement_target_month":
                record_month,
        })

    result = list(
        groups.values()
    )

    for group in result:
        group["details"].sort(
            key=lambda item: (
                str(
                    item.get(
                        "case_id",
                        "",
                    )
                ),
                str(
                    item.get(
                        "payment_id",
                        "",
                    )
                ),
            )
        )

    result.sort(
        key=lambda item: (
            item["target_month"],
            item["vendor_id"],
        )
    )

    return result



def make_monthly_settlement_id(
    target_month,
    vendor_id,
):
    target_month = str(
        target_month or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    if not re.match(
        r"^\d{4}-\d{2}$",
        target_month,
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    if not vendor_id:
        raise ValueError(
            "提携業者IDがありません。"
        )

    base_id = (
        "SET-"
        + target_month.replace("-", "")
        + "-"
        + vendor_id
    )

    # -----------------------------------------------------
    # 同一月・同一業者で追加精算が発生した場合、
    # 既存IDを保持したまま枝番を付与する。
    #
    # 初回:
    #   SET-202608-V001
    #
    # 2回目:
    #   SET-202608-V001-02
    #
    # 3回目:
    #   SET-202608-V001-03
    #
    # 欠番があっても過去IDを再利用しないため、
    # 既存最大番号 + 1 とする。
    # -----------------------------------------------------

    existing_records = (
        get_monthly_settlement_records()
    )

    pattern = re.compile(
        r"^"
        + re.escape(base_id)
        + r"(?:-(\d+))?$"
    )

    sequence_numbers = []

    for record in existing_records:

        existing_id = str(
            record.get(
                "monthly_settlement_id",
                ""
            )
            or ""
        ).strip()

        match = pattern.match(
            existing_id
        )

        if not match:
            continue

        suffix = match.group(1)

        if suffix is None:
            sequence_numbers.append(
                1
            )
            continue

        try:
            sequence_number = int(
                suffix
            )
        except Exception:
            continue

        if sequence_number >= 2:
            sequence_numbers.append(
                sequence_number
            )

    if not sequence_numbers:
        return base_id

    next_sequence = (
        max(sequence_numbers)
        + 1
    )

    return (
        base_id
        + "-"
        + f"{next_sequence:02d}"
    )


def get_monthly_settlement_records():
    rows = get_sheet_values(
        "月次精算!A2:V"
    )

    records = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        if not row:
            continue

        row = row + [""] * (
            22 - len(row)
        )

        if not str(
            row[0] or ""
        ).strip():
            continue

        records.append({
            "row_number":
                row_number,

            "monthly_settlement_id":
                row[0],

            "target_month":
                row[1],

            "vendor_id":
                row[2],

            "company_name":
                row[3],

            "detail_count":
                row[4],

            "customer_payment_amount":
                row[5],

            "company_deposit_amount":
                row[6],

            "payment_provider_fee":
                row[7],

            "fee_amount":
                row[8],

            "tax_amount":
                row[9],

            "company_deduction_amount":
                row[10],

            "vendor_payment_amount":
                row[11],

            "settlement_status":
                row[12],

            "settlement_confirmed_date":
                row[13],

            "vendor_payment_date":
                row[14],

            "settlement_document_number":
                row[15],

            "note":
                row[16],

            "settlement_document_path":
                row[17],

            "settlement_document_name":
                row[18],

            "settlement_document_registered_at":
                row[19],

            "registered_at":
                row[20],

            "updated_at":
                row[21],
        })

    return records


def get_monthly_settlement_by_id(
    monthly_settlement_id,
    records=None,
):
    monthly_settlement_id = str(
        monthly_settlement_id or ""
    ).strip()

    if records is None:
        records = (
            get_monthly_settlement_records()
        )

    for record in records:
        if (
            str(
                record.get(
                    "monthly_settlement_id",
                    "",
                )
                or ""
            ).strip()
            == monthly_settlement_id
        ):
            return record

    return None


