def save_monthly_billing_invoice_document(
    monthly_billing_id,
    file_storage,
):
    monthly_billing_id = str(
        monthly_billing_id or ""
    ).strip()

    if not monthly_billing_id:
        raise ValueError(
            "月次請求IDがありません。"
        )

    record = (
        get_monthly_billing_by_id(
            monthly_billing_id
        )
    )

    if not record:
        raise ValueError(
            "月次請求データが"
            "見つかりません。"
        )

    if (
        not file_storage
        or not file_storage.filename
    ):
        raise ValueError(
            "請求書PDFを選択してください。"
        )

    extension = get_extension(
        file_storage.filename
    )

    if extension != ".pdf":
        raise ValueError(
            "請求書はPDF形式のみ"
            "アップロードできます。"
        )

    content = file_storage.read()

    if not content:
        raise ValueError(
            "ファイルの内容が空です。"
        )

    max_size = 20 * 1024 * 1024

    if len(content) > max_size:
        raise ValueError(
            "ファイルサイズは"
            "20MB以内にしてください。"
        )

    if not content.startswith(
        b"%PDF-"
    ):
        raise ValueError(
            "正しいPDFファイルではありません。"
        )

    target_month = str(
        record.get(
            "target_month",
            "",
        )
        or ""
    ).strip()

    year = "unknown"
    month = "unknown"

    match = re.match(
        r"^(\d{4})-(\d{2})$",
        target_month,
    )

    if match:
        year = match.group(1)
        month = match.group(2)

    document_path = (
        f"monthly_billing_invoice/"
        f"{year}/{month}/"
        f"{monthly_billing_id}/"
        f"invoice.pdf"
    )

    client = storage.Client()

    bucket = client.bucket(
        BUCKET_NAME
    )

    blob = bucket.blob(
        document_path
    )

    blob.upload_from_string(
        content,
        content_type="application/pdf",
    )

    current_time = now_text()

    original_name = str(
        file_storage.filename
        or "invoice.pdf"
    ).strip()

    original_name = (
        original_name
        .replace("\\", "/")
        .split("/")[-1]
    )

    if not original_name:
        original_name = "invoice.pdf"

    row_num = record[
        "row_number"
    ]

    update_sheet_range(
        f"月次請求!"
        f"P{row_num}:R{row_num}",
        [[
            document_path,
            original_name,
            current_time,
        ]],
    )

    return {
        "monthly_billing_id":
            monthly_billing_id,
        "document_path":
            document_path,
        "document_name":
            original_name,
        "registered_at":
            current_time,
    }


def ensure_monthly_billing_sheet():
    service = get_sheets_service()

    metadata = (
        service.spreadsheets()
        .get(
            spreadsheetId=SPREADSHEET_ID,
            fields="sheets.properties.title",
        )
        .execute()
    )

    titles = [
        sheet["properties"]["title"]
        for sheet in metadata.get(
            "sheets",
            [],
        )
    ]

    sheet_name = "月次請求"

    if sheet_name not in titles:
        (
            service.spreadsheets()
            .batchUpdate(
                spreadsheetId=
                    SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        sheet_name
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )

    headers = [
        "月次請求ID",
        "対象月",
        "提携業者ID",
        "提携業者名",
        "明細件数",
        "紹介料本体合計",
        "消費税合計",
        "請求金額",
        "請求日",
        "支払期限",
        "入金日",
        "入金額",
        "入金状況",
        "請求書番号",
        "備考",
        "請求書ファイルパス",
        "請求書ファイル名",
        "請求書登録日時",
        "登録日時",
        "最終更新",
    ]

    update_sheet_range(
        "月次請求!A1:T1",
        [headers],
    )


def get_monthly_billing_records():
    rows = get_sheet_values(
        "月次請求!A2:T"
    )

    records = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        if not row:
            continue

        row = row + [""] * (
            20 - len(row)
        )

        if not str(
            row[0] or ""
        ).strip():
            continue

        records.append({
            "row_number":
                row_number,
            "monthly_billing_id":
                row[0],
            "target_month":
                row[1],
            "vendor_id":
                row[2],
            "company_name":
                row[3],
            "detail_count":
                row[4],
            "fee_amount":
                row[5],
            "tax_amount":
                row[6],
            "billing_amount":
                row[7],
            "invoice_date":
                row[8],
            "due_date":
                row[9],
            "payment_date":
                row[10],
            "payment_amount":
                row[11],
            "payment_status":
                row[12],
            "invoice_number":
                row[13],
            "note":
                row[14],
            "invoice_document_path":
                row[15],
            "invoice_document_name":
                row[16],
            "invoice_document_registered_at":
                row[17],
            "registered_at":
                row[18],
            "updated_at":
                row[19],
        })

    return records


def get_vendor_monthly_billing_records(
    vendor_id,
):
    vendor_id = str(
        vendor_id or ""
    ).strip()

    records = (
        get_monthly_billing_records()
    )

    result = []

    for record in records:
        if (
            str(
                record.get(
                    "vendor_id",
                    "",
                )
                or ""
            ).strip()
            != vendor_id
        ):
            continue

        item = dict(record)

        item[
            "display_status"
        ] = billing_display_status(
            item
        )

        item[
            "billing_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "billing_amount",
                    "",
                )
            )
            or 0
        )

        item[
            "payment_amount_text"
        ] = (
            format_yen(
                parse_money(
                    item.get(
                        "payment_amount",
                        "",
                    )
                )
                or 0
            )
            if item.get(
                "payment_amount"
            ) not in (
                "",
                None,
            )
            else "-"
        )

        item[
            "detail_count_text"
        ] = str(
            item.get(
                "detail_count",
                "",
            )
            or "0"
        )

        result.append(
            item
        )

    result.sort(
        key=lambda item: (
            str(
                item.get(
                    "target_month",
                    "",
                )
            ),
            str(
                item.get(
                    "monthly_billing_id",
                    "",
                )
            ),
        ),
        reverse=True,
    )

    return result


def get_monthly_billing_by_id(
    monthly_billing_id,
    records=None,
):
    if records is None:
        records = (
            get_monthly_billing_records()
        )

    monthly_billing_id = str(
        monthly_billing_id or ""
    ).strip()

    for record in records:
        if (
            str(
                record[
                    "monthly_billing_id"
                ]
                or ""
            ).strip()
            == monthly_billing_id
        ):
            return record

    return None


def build_monthly_billing_candidates(
    target_month=None,
):
    target_month = str(
        target_month or ""
    ).strip()

    if (
        target_month
        and not re.match(
            r"^\d{4}-\d{2}$",
            target_month,
        )
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    groups = {}

    for record in get_billing_records():
        billing_type = str(
            record.get(
                "billing_type",
                "",
            )
            or ""
        ).strip()

        if billing_type not in (
            "紹介料",
            "見積書作成費",
        ):
            continue

        record_month = str(
            record.get(
                "target_month",
                "",
            )
            or ""
        ).strip()

        if not record_month:
            continue

        if (
            target_month
            and record_month
            != target_month
        ):
            continue

        vendor_id = str(
            record.get(
                "vendor_id",
                "",
            )
            or ""
        ).strip()

        if not vendor_id:
            continue

        payment_status = str(
            record.get(
                "payment_status",
                "",
            )
            or ""
        ).strip()

        if payment_status in (
            "取消",
            "対象外",
        ):
            continue

        key = (
            record_month,
            vendor_id,
        )

        if key not in groups:
            groups[key] = {
                "target_month":
                    record_month,
                "vendor_id":
                    vendor_id,
                "company_name":
                    str(
                        record.get(
                            "company_name",
                            "",
                        )
                        or ""
                    ).strip(),
                "detail_count":
                    0,
                "fee_amount":
                    0,
                "tax_amount":
                    0,
                "billing_amount":
                    0,
                "details":
                    [],
            }

        group = groups[key]

        fee_amount = (
            parse_money(
                record.get(
                    "fee_amount",
                    "",
                )
            )
            or 0
        )

        tax_amount = (
            parse_money(
                record.get(
                    "tax_amount",
                    "",
                )
            )
            or 0
        )

        billing_amount = (
            parse_money(
                record.get(
                    "billing_amount",
                    "",
                )
            )
            or 0
        )

        group[
            "detail_count"
        ] += 1

        group[
            "fee_amount"
        ] += fee_amount

        group[
            "tax_amount"
        ] += tax_amount

        group[
            "billing_amount"
        ] += billing_amount

        group["details"].append({
            "billing_id":
                record.get(
                    "billing_id",
                    "",
                ),
            "case_id":
                record.get(
                    "case_id",
                    "",
                ),
            "contract_amount":
                record.get(
                    "contract_amount",
                    "",
                ),
            "referral_rate":
                record.get(
                    "referral_rate",
                    "",
                ),
            "fee_amount":
                fee_amount,
            "tax_amount":
                tax_amount,
            "billing_amount":
                billing_amount,
            "billing_type":
                str(
                    record.get(
                        "billing_type",
                        "",
                    )
                    or ""
                ).strip(),
            "detail_name":
                (
                    str(
                        record.get(
                            "case_id",
                            "",
                        )
                        or ""
                    ).strip()
                    + " "
                    + str(
                        record.get(
                            "billing_type",
                            "",
                        )
                        or ""
                    ).strip()
                ).strip(),
        })

    result = list(
        groups.values()
    )

    result.sort(
        key=lambda item: (
            item["target_month"],
            item["vendor_id"],
        )
    )

    return result


def make_next_monthly_invoice_number(
    target_month,
    records=None,
):
    target_month = str(
        target_month or ""
    ).strip()

    match = re.match(
        r"^(\d{4})-(\d{2})$",
        target_month,
    )

    if not match:
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    yyyymm = (
        match.group(1)
        + match.group(2)
    )

    if records is None:
        records = (
            get_monthly_billing_records()
        )

    max_sequence = 0

    pattern = re.compile(
        rf"^INV-{yyyymm}-(\d+)$"
    )

    for record in records:
        invoice_number = str(
            record.get(
                "invoice_number",
                "",
            )
            or ""
        ).strip()

        number_match = (
            pattern.match(
                invoice_number
            )
        )

        if not number_match:
            continue

        sequence = int(
            number_match.group(1)
        )

        if sequence > max_sequence:
            max_sequence = sequence

    return (
        f"INV-{yyyymm}-"
        f"{max_sequence + 1:03d}"
    )


def generate_monthly_billings(
    target_month,
):
    target_month = str(
        target_month or ""
    ).strip()

    if not re.match(
        r"^\d{4}-\d{2}$",
        target_month,
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    candidates = (
        build_monthly_billing_candidates(
            target_month
        )
    )

    results = []

    created_count = 0
    locked_count = 0
    updated_count = 0

    for candidate in candidates:
        vendor_id = str(
            candidate.get(
                "vendor_id",
                "",
            )
            or ""
        ).strip()

        if not vendor_id:
            continue

        result = (
            upsert_monthly_billing_record(
                target_month,
                vendor_id,
            )
        )

        results.append(
            result
        )

        if result.get(
            "created"
        ):
            created_count += 1

        elif result.get(
            "locked"
        ):
            locked_count += 1

        elif result.get(
            "updated"
        ):
            updated_count += 1

    return {
        "target_month":
            target_month,
        "candidate_count":
            len(candidates),
        "created_count":
            created_count,
        "updated_count":
            updated_count,
        "locked_count":
            locked_count,
        "results":
            results,
    }


def upsert_monthly_billing_record(
    target_month,
    vendor_id,
):
    target_month = str(
        target_month or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    candidates = (
        build_monthly_billing_candidates(
            target_month
        )
    )

    candidate = None

    for item in candidates:
        if (
            str(
                item.get(
                    "vendor_id",
                    "",
                )
                or ""
            ).strip()
            == vendor_id
        ):
            candidate = item
            break

    if not candidate:
        return {
            "created": False,
            "updated": False,
            "locked": False,
            "reason":
                "対象となる請求明細がありません。",
        }

    monthly_billing_id = (
        make_monthly_billing_id(
            target_month,
            vendor_id,
        )
    )

    ensure_monthly_billing_sheet()

    existing = (
        get_monthly_billing_by_id(
            monthly_billing_id
        )
    )

    current_time = now_text()

    if existing:
        existing_details = (
            get_monthly_billing_details(
                monthly_billing_id
            )
        )

        # 月次請求明細が確定済みなら
        # 月次金額を再集計しない。
        if existing_details:
            return {
                "created": False,
                "updated": False,
                "locked": True,
                "monthly_billing_id":
                    monthly_billing_id,
                "detail_count":
                    len(existing_details),
            }

        payment_status = str(
            existing.get(
                "payment_status",
                "",
            )
            or ""
        ).strip()

        invoice_date = str(
            existing.get(
                "invoice_date",
                "",
            )
            or ""
        ).strip()

        document_path = str(
            existing.get(
                "invoice_document_path",
                "",
            )
            or ""
        ).strip()

        # 請求済み・請求書掲載済み・入金処理済み後は
        # 月次金額を自動変更しない。
        if (
            invoice_date
            or document_path
            or payment_status not in (
                "",
                "未請求",
            )
        ):
            return {
                "created": False,
                "updated": False,
                "locked": True,
                "monthly_billing_id":
                    monthly_billing_id,
            }

        row_num = existing[
            "row_number"
        ]

        update_sheet_range(
            f"月次請求!"
            f"A{row_num}:H{row_num}",
            [[
                monthly_billing_id,
                target_month,
                vendor_id,
                candidate[
                    "company_name"
                ],
                candidate[
                    "detail_count"
                ],
                candidate[
                    "fee_amount"
                ],
                candidate[
                    "tax_amount"
                ],
                candidate[
                    "billing_amount"
                ],
            ]],
        )

        update_sheet_range(
            f"月次請求!"
            f"T{row_num}",
            [[current_time]],
        )

        return {
            "created": False,
            "updated": True,
            "locked": False,
            "monthly_billing_id":
                monthly_billing_id,
        }

    due_date = (
        monthly_billing_due_date(
            target_month
        )
    )

    invoice_number = (
        make_next_monthly_invoice_number(
            target_month
        )
    )

    append_sheet_row(
        "月次請求!A:T",
        [
            monthly_billing_id,
            target_month,
            vendor_id,
            candidate[
                "company_name"
            ],
            candidate[
                "detail_count"
            ],
            candidate[
                "fee_amount"
            ],
            candidate[
                "tax_amount"
            ],
            candidate[
                "billing_amount"
            ],
            "",             # I 請求日
            due_date,       # J 支払期限
            "",             # K 入金日
            "",             # L 入金額
            "未請求",       # M 入金状況
            invoice_number, # N 請求書番号
            "",             # O 備考
            "",             # P 請求書パス
            "",             # Q 請求書名
            "",             # R 請求書登録日時
            current_time,   # S 登録日時
            current_time,   # T 最終更新
        ],
    )

    snapshot_result = (
        save_monthly_billing_detail_snapshot(
            monthly_billing_id
        )
    )

    return {
        "created": True,
        "updated": False,
        "locked": False,
        "monthly_billing_id":
            monthly_billing_id,
        "detail_count":
            snapshot_result.get(
                "detail_count",
                0,
            ),
    }


def make_monthly_billing_id(
    target_month,
    vendor_id,
):
    target_month = str(
        target_month or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    if not re.match(
        r"^\d{4}-\d{2}$",
        target_month,
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    if not vendor_id:
        raise ValueError(
            "提携業者IDがありません。"
        )

    return (
        "MINV-"
        + target_month.replace(
            "-",
            "",
        )
        + "-"
        + vendor_id
    )


def monthly_billing_due_date(
    target_month,
):
    target_month = str(
        target_month or ""
    ).strip()

    if not re.match(
        r"^\d{4}-\d{2}$",
        target_month,
    ):
        raise ValueError(
            "対象月はYYYY-MM形式で"
            "指定してください。"
        )

    year, month = map(
        int,
        target_month.split("-"),
    )

    if month == 12:
        month_after_next = datetime(
            year + 1,
            2,
            1,
        )
    elif month == 11:
        month_after_next = datetime(
            year + 1,
            1,
            1,
        )
    else:
        month_after_next = datetime(
            year,
            month + 2,
            1,
        )

    due = (
        month_after_next
        - timedelta(days=1)
    )

    return due.strftime(
        "%Y-%m-%d"
    )


def ensure_billing_sheet():

    service = get_sheets_service()

    metadata = (
        service.spreadsheets()
        .get(
            spreadsheetId=SPREADSHEET_ID,
            fields="sheets.properties.title",
        )
        .execute()
    )

    titles = [
        sheet["properties"]["title"]
        for sheet in metadata.get("sheets", [])
    ]

    sheet_name = "請求管理"

    if sheet_name not in titles:

        (
            service.spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title": sheet_name
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )

    headers = [
        "請求ID",
        "案件ID",
        "提携業者ID",
        "提携業者名",
        "請求種別",
        "対象月",
        "税込契約金額",
        "紹介料率",
        "紹介料本体",
        "消費税",
        "請求金額",
        "請求日",
        "支払期限",
        "入金日",
        "入金額",
        "入金状況",
        "請求書番号",
        "備考",
        "登録日時",
        "最終更新",
        "請求書ファイルパス",
        "請求書ファイル名",
        "請求書登録日時",
    ]

    update_sheet_range(
        "請求管理!A1:W1",
        [headers],
    )



def get_billing_records():

    rows = get_sheet_values(
        "請求管理!A2:W"
    )

    records = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):

        if not row:
            continue

        row = row + [""] * (
            23 - len(row)
        )

        if not str(row[0]).strip():
            continue

        records.append({
            "row_number": row_number,
            "billing_id": row[0],
            "case_id": row[1],
            "vendor_id": row[2],
            "company_name": row[3],
            "billing_type": row[4],
            "target_month": row[5],
            "contract_amount": row[6],
            "referral_rate": row[7],
            "fee_amount": row[8],
            "tax_amount": row[9],
            "billing_amount": row[10],
            "invoice_date": row[11],
            "due_date": row[12],
            "payment_date": row[13],
            "payment_amount": row[14],
            "payment_status": row[15],
            "invoice_number": row[16],
            "note": row[17],
            "registered_at": row[18],
            "updated_at": row[19],
            "invoice_document_path": row[20],
            "invoice_document_name": row[21],
            "invoice_document_registered_at":
                row[22],
        })

    return records



def save_billing_invoice_document(
    billing_id,
    file_storage,
):
    billing_id = str(
        billing_id or ""
    ).strip()

    if not billing_id:
        raise ValueError(
            "請求IDがありません。"
        )

    record = get_billing_by_id(
        billing_id
    )

    if not record:
        raise ValueError(
            "請求データが見つかりません。"
        )

    if (
        not file_storage
        or not file_storage.filename
    ):
        raise ValueError(
            "請求書PDFを選択してください。"
        )

    extension = get_extension(
        file_storage.filename
    )

    if extension != ".pdf":
        raise ValueError(
            "請求書はPDF形式のみ"
            "アップロードできます。"
        )

    content = file_storage.read()

    if not content:
        raise ValueError(
            "ファイルの内容が空です。"
        )

    max_size = 20 * 1024 * 1024

    if len(content) > max_size:
        raise ValueError(
            "ファイルサイズは"
            "20MB以内にしてください。"
        )

    target_month = str(
        record.get(
            "target_month",
            "",
        )
        or ""
    ).strip()

    year = "unknown"
    month = "unknown"

    match = re.match(
        r"^(\d{4})-(\d{2})$",
        target_month,
    )

    if match:
        year = match.group(1)
        month = match.group(2)

    document_path = (
        f"billing_invoice/"
        f"{year}/{month}/"
        f"{billing_id}/"
        f"invoice.pdf"
    )

    client = storage.Client()

    bucket = client.bucket(
        BUCKET_NAME
    )

    blob = bucket.blob(
        document_path
    )

    blob.upload_from_string(
        content,
        content_type="application/pdf",
    )

    current_time = now_text()

    row_num = record[
        "row_number"
    ]

    update_sheet_range(
        f"請求管理!"
        f"U{row_num}:W{row_num}",
        [[
            document_path,
            "invoice.pdf",
            current_time,
        ]],
    )

    return {
        "billing_id":
            billing_id,
        "document_path":
            document_path,
        "file_name":
            "invoice.pdf",
        "registered_at":
            current_time,
    }


def get_vendor_billing_records(
    vendor_id,
):
    vendor_id = str(
        vendor_id or ""
    ).strip()

    if not vendor_id:
        return []

    records = []

    for record in get_billing_records():
        if (
            str(
                record.get(
                    "vendor_id",
                    "",
                )
            ).strip()
            != vendor_id
        ):
            continue

        item = dict(record)

        item[
            "display_status"
        ] = billing_display_status(
            record
        )

        records.append(
            item
        )

    records.sort(
        key=lambda item: (
            str(
                item.get(
                    "invoice_date",
                    "",
                )
            ),
            str(
                item.get(
                    "billing_id",
                    "",
                )
            ),
        ),
        reverse=True,
    )

    return records


def get_billing_by_id(
    billing_id,
    records=None,
):

    if records is None:
        records = get_billing_records()

    for record in records:

        if (
            str(record["billing_id"])
            == str(billing_id)
        ):
            return record

    return None



def find_case_billing(
    case_id,
    billing_type="紹介料",
    records=None,
):

    if records is None:
        records = get_billing_records()

    for record in records:

        if (
            record["case_id"] == case_id
            and record["billing_type"] == billing_type
        ):
            return record

    return None



def make_billing_id():

    return (
        "INV-"
        + now_jst().strftime(
            "%Y%m%d%H%M%S"
        )
        + "-"
        + secrets.token_hex(2).upper()
    )



def billing_target_month(
    contract_date,
):

    value = str(
        contract_date or ""
    ).strip()

    match = re.match(
        r"^(\d{4})-(\d{2})",
        value,
    )

    if not match:
        return ""

    return (
        f"{match.group(1)}-"
        f"{match.group(2)}"
    )



def validate_date_string(
    value,
    field_name="日付",
):
    value = str(
        value or ""
    ).strip()

    if not value:
        return ""

    try:
        datetime.strptime(
            value,
            "%Y-%m-%d",
        )
    except Exception:
        raise ValueError(
            f"{field_name}はYYYY-MM-DD形式で"
            "入力してください。"
        )

    return value


def validate_datetime_string(
    value,
    field_name="日時",
):
    value = str(
        value or ""
    ).strip()

    if not value:
        return ""

    try:
        datetime.strptime(
            value,
            "%Y-%m-%d %H:%M:%S",
        )
    except Exception:
        raise ValueError(
            f"{field_name}は"
            "YYYY-MM-DD HH:MM:SS形式で"
            "入力してください。"
        )

    return value


def calculate_next_month_end(
    invoice_date,
):

    value = str(
        invoice_date or ""
    ).strip()

    try:
        dt = datetime.strptime(
            value,
            "%Y-%m-%d",
        )
    except Exception:
        return ""

    if dt.month == 12:
        month_after_next = datetime(
            dt.year + 1,
            2,
            1,
        )

    elif dt.month == 11:
        month_after_next = datetime(
            dt.year + 1,
            1,
            1,
        )

    else:
        month_after_next = datetime(
            dt.year,
            dt.month + 2,
            1,
        )

    due = (
        month_after_next
        - timedelta(days=1)
    )

    return due.strftime(
        "%Y-%m-%d"
    )



def billing_display_status(
    record,
):

    status = str(
        record.get(
            "payment_status",
            "",
        )
    ).strip()

    if status in (
        "入金済み",
        "取消",
    ):
        return status

    due_date = str(
        record.get(
            "due_date",
            "",
        )
    ).strip()

    if due_date:

        try:
            due = datetime.strptime(
                due_date,
                "%Y-%m-%d",
            ).date()

            if due < now_jst().date():
                return "期限超過"

        except Exception:
            pass

    return (
        status
        or "未請求"
    )



def upsert_referral_billing_record(
    case_id,
    contract_date,
    contract_amount,
    referral_rate,
    referral_fee,
    company_name,
):

    if (
        not contract_date
        or contract_amount is None
        or referral_rate is None
        or referral_fee == ""
    ):
        return {
            "created": False,
            "updated": False,
            "locked": False,
        }

    ensure_billing_sheet()

    records = get_billing_records()

    existing = find_case_billing(
        case_id,
        "紹介料",
        records,
    )

    vendor_id = ""

    if company_name:
        vendor_id = (
            find_vendor_id_by_company_name(
                company_name
            )
        )

    fee_amount = int(
        referral_fee
    )

    tax_amount = int(
        fee_amount * 0.10
    )

    billing_amount = (
        fee_amount
        + tax_amount
    )

    target_month = (
        billing_target_month(
            contract_date
        )
    )

    current_time = now_text()


    if existing:

        status = str(
            existing.get(
                "payment_status",
                "",
            )
        ).strip()

        if status not in (
            "",
            "未請求",
        ):

            return {
                "created": False,
                "updated": False,
                "locked": True,
                "billing_id":
                    existing[
                        "billing_id"
                    ],
            }

        row_num = (
            existing[
                "row_number"
            ]
        )

        update_sheet_range(
            f"請求管理!"
            f"A{row_num}:T{row_num}",
            [[
                existing["billing_id"],
                case_id,
                vendor_id,
                company_name,
                "紹介料",
                target_month,
                contract_amount,
                referral_rate,
                fee_amount,
                tax_amount,
                billing_amount,
                existing.get(
                    "invoice_date",
                    "",
                ),
                existing.get(
                    "due_date",
                    "",
                ),
                existing.get(
                    "payment_date",
                    "",
                ),
                existing.get(
                    "payment_amount",
                    "",
                ),
                (
                    existing.get(
                        "payment_status",
                        "",
                    )
                    or "未請求"
                ),
                existing.get(
                    "invoice_number",
                    "",
                ),
                existing.get(
                    "note",
                    "",
                ),
                existing.get(
                    "registered_at",
                    "",
                )
                or current_time,
                current_time,
            ]],
        )

        return {
            "created": False,
            "updated": True,
            "locked": False,
            "billing_id":
                existing[
                    "billing_id"
                ],
        }


    billing_id = (
        make_billing_id()
    )

    append_sheet_row(
        "請求管理!A:T",
        [
            billing_id,
            case_id,
            vendor_id,
            company_name,
            "紹介料",
            target_month,
            contract_amount,
            referral_rate,
            fee_amount,
            tax_amount,
            billing_amount,
            "",
            "",
            "",
            "",
            "未請求",
            "",
            "",
            current_time,
            current_time,
        ],
    )

    return {
        "created": True,
        "updated": False,
        "locked": False,
        "billing_id": billing_id,
    }



def create_estimate_document_fee_billing(
    case_id,
    vendor_id,
    company_name,
    completed_at,
):
    case_id = str(
        case_id or ""
    ).strip()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    company_name = str(
        company_name or ""
    ).strip()

    completed_at = str(
        completed_at or ""
    ).strip()

    if not case_id:
        raise ValueError(
            "案件IDがありません。"
        )

    if not vendor_id:
        raise ValueError(
            "提携業者IDがありません。"
        )

    if not company_name:
        raise ValueError(
            "提携業者名がありません。"
        )

    if not completed_at:
        raise ValueError(
            "見積書作成完了日時がありません。"
        )

    match = re.match(
        r"^(\d{4})-(\d{2})",
        completed_at,
    )

    if not match:
        raise ValueError(
            "見積書作成完了日時の形式が"
            "正しくありません。"
        )

    target_month = (
        f"{match.group(1)}-"
        f"{match.group(2)}"
    )

    billing_id = (
        "ESTFEE-"
        + case_id
        + "-"
        + vendor_id
    )

    ensure_billing_sheet()

    existing = get_billing_by_id(
        billing_id
    )

    if existing:
        return {
            "created": False,
            "duplicate": True,
            "billing_id":
                billing_id,
        }

    fee_amount = 3000
    tax_amount = 300
    billing_amount = 3300

    current_time = now_text()

    append_sheet_row(
        "請求管理!A:T",
        [
            billing_id,         # A 請求ID
            case_id,            # B 案件ID
            vendor_id,          # C 提携業者ID
            company_name,       # D 提携業者名
            "見積書作成費",      # E 請求種別
            target_month,       # F 対象月
            "",                 # G 税込契約金額
            "",                 # H 紹介料率
            fee_amount,         # I 税抜請求額
            tax_amount,         # J 消費税
            billing_amount,     # K 請求金額
            "",                 # L 請求日
            "",                 # M 支払期限
            "",                 # N 入金日
            "",                 # O 入金額
            "未請求",            # P 入金状況
            "",                 # Q 請求書番号
            "",                 # R 備考
            current_time,       # S 登録日時
            current_time,       # T 最終更新
        ],
    )

    return {
        "created": True,
        "duplicate": False,
        "billing_id":
            billing_id,
        "target_month":
            target_month,
        "fee_amount":
            fee_amount,
        "tax_amount":
            tax_amount,
        "billing_amount":
            billing_amount,
    }


