def split_master_values(value):
    if not value:
        return []

    value = str(value)

    for separator in [
        "、",
        "\n",
        "／",
        "/",
        "・",
        ";",
        "；",
    ]:
        value = value.replace(
            separator,
            ",",
        )

    return [
        item.strip()
        for item in value.split(",")
        if item.strip()
    ]


def normalize_work_type(value):
    value = str(
        value or ""
    ).strip()

    aliases = {
        "屋根": "屋根塗装",
        "屋根一般塗装": "屋根塗装",

        "外壁": "外壁塗装",
        "外壁一般塗装": "外壁塗装",

        "外壁＋屋根": "屋根＋外壁塗装",
        "屋根＋外壁": "屋根＋外壁塗装",
        "外壁+屋根": "屋根＋外壁塗装",
        "屋根+外壁": "屋根＋外壁塗装",
        "外壁・屋根": "屋根＋外壁塗装",
        "屋根・外壁": "屋根＋外壁塗装",

        "屋根外壁塗装": "屋根＋外壁塗装",
        "外壁屋根塗装": "屋根＋外壁塗装",
    }

    return aliases.get(
        value,
        value,
    )


