def unique_values(values):
    result = []

    for value in values:
        value = str(
            value or ""
        ).strip()

        if (
            value
            and value not in result
        ):
            result.append(value)

    return result


def get_vendor_checkbox_context(
    areas_raw,
    works_raw,
):
    raw_areas = (
        split_master_values(
            areas_raw
        )
    )

    raw_works = (
        split_master_values(
            works_raw
        )
    )

    known_areas = {
        area
        for _group_name, areas
        in VENDOR_AREA_GROUPS
        for area in areas
    }

    known_works = set(
        VENDOR_WORK_OPTIONS
    )

    selected_areas = [
        area
        for area in raw_areas
        if area in known_areas
    ]

    selected_works = (
        unique_values([
            normalize_work_type(
                work
            )
            for work in raw_works
            if normalize_work_type(
                work
            ) in known_works
        ])
    )

    legacy_areas = [
        area
        for area in raw_areas
        if area not in known_areas
    ]

    legacy_works = [
        work
        for work in raw_works
        if normalize_work_type(
            work
        ) not in known_works
    ]

    return {
        "area_groups":
            VENDOR_AREA_GROUPS,
        "work_options":
            VENDOR_WORK_OPTIONS,
        "selected_areas":
            selected_areas,
        "selected_works":
            selected_works,
        "legacy_areas":
            legacy_areas,
        "legacy_works":
            legacy_works,
    }


def get_vendor_master():
    rows = get_sheet_values(
        "提携業者!A2:U"
    )

    vendors = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        if not row:
            continue

        row = row + [""] * (
            21 - len(row)
        )

        vendor_id = str(
            row[0]
        ).strip()

        company_name = str(
            row[1]
        ).strip()

        if (
            not vendor_id
            or not company_name
        ):
            continue

        vendors.append({
            "row_number": row_number,
            "vendor_id": vendor_id,
            "company_name": company_name,
            "contact_name": row[2],
            "phone": row[3],
            "email": row[4],
            "address": row[5],
            "areas_raw": row[6],
            "works_raw": row[7],
            "default_fee_rate": row[8],
            "status": row[9],
            "registered_at": row[10],
            "updated_at": row[11],
            "participation_count": row[12],
            "note": row[13],

            "meeting_date": row[14],
            "terms_version": row[15],
            "online_consent_at": row[16],
            "signed_at": row[17],
            "partnership_started_at": row[18],
            "consent_name": row[19],

            # U 対応サービス
            # 既存業者の空欄は塗装専用として扱う。
            "service_type_raw": (
                str(
                    row[20] or ""
                ).strip()
                or SERVICE_TYPE_TOSOU
            ),
        })

    return vendors



def get_vendor_login_accounts():
    rows = get_sheet_values(
        "業者ログイン!A2:H"
    )

    accounts = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        if not row:
            continue

        row = row + [""] * (
            8 - len(row)
        )

        vendor_id = str(
            row[0]
        ).strip()

        login_id = str(
            row[1]
        ).strip()

        if (
            not vendor_id
            or not login_id
        ):
            continue

        enabled_raw = str(
            row[3] or ""
        ).strip().lower()

        enabled = enabled_raw in {
            "true",
            "1",
            "yes",
            "on",
            "有効",
        }

        accounts.append({
            "row_number": row_number,
            "vendor_id": vendor_id,
            "login_id": login_id,
            "password_hash": str(
                row[2] or ""
            ).strip(),
            "enabled": enabled,
            "registered_at": row[4],
            "updated_at": row[5],
            "last_login_at": row[6],
            "password_changed_at": row[7],
        })

    return accounts


def get_vendor_login_by_username(
    login_id,
):
    login_id = str(
        login_id or ""
    ).strip()

    if not login_id:
        return None

    for account in (
        get_vendor_login_accounts()
    ):
        if account[
            "login_id"
        ] == login_id:
            return account

    return None


def vendor_logged_in():
    if not (
        session.get(
            "vendor_logged_in"
        )
        is True
        and session.get(
            "vendor_id"
        )
    ):
        return False

    if has_request_context():
        cached = getattr(
            g,
            "_vendor_auth_valid",
            None,
        )

        if cached is not None:
            return cached

    vendor_id = str(
        session.get(
            "vendor_id",
            "",
        )
        or ""
    ).strip()

    try:
        account = get_vendor_login_account(
            vendor_id
        )
        vendor = get_vendor_by_id(
            vendor_id,
            get_vendor_master(),
        )

        valid = bool(
            account
            and account.get("enabled")
            and vendor
            and str(
                vendor.get("status", "")
                or ""
            ).strip()
            not in {
                "停止",
                "無効",
                "無効化",
            }
            and session.get(
                "vendor_account_updated_at",
                "",
            )
            == str(
                account.get("updated_at", "")
                or ""
            )
            and session.get(
                "vendor_password_changed_at",
                "",
            )
            == str(
                account.get(
                    "password_changed_at",
                    "",
                )
                or ""
            )
        )

    except Exception:
        valid = False

    if not valid:
        session.pop("vendor_logged_in", None)
        session.pop("vendor_id", None)
        session.pop(
            "vendor_account_updated_at",
            None,
        )
        session.pop(
            "vendor_password_changed_at",
            None,
        )

    if has_request_context():
        g._vendor_auth_valid = valid

    return valid


def current_vendor_id():
    if not vendor_logged_in():
        return ""

    return str(
        session.get(
            "vendor_id",
            ""
        )
    ).strip()


def create_vendor_login_account(
    vendor_id,
    login_id,
    password,
):
    vendor_id = str(
        vendor_id or ""
    ).strip()

    login_id = str(
        login_id or ""
    ).strip()

    password = str(
        password or ""
    )

    if not vendor_id:
        raise ValueError(
            "業者IDが空です。"
        )

    if not login_id:
        raise ValueError(
            "ログインIDが空です。"
        )

    if len(password) < 12:
        raise ValueError(
            "パスワードは12文字以上にしてください。"
        )

    vendor = get_vendor_by_id(
        vendor_id,
        get_vendor_master(),
    )

    if not vendor:
        raise ValueError(
            "提携業者マスターに"
            "該当業者がありません。"
        )

    for account in (
        get_vendor_login_accounts()
    ):
        if account[
            "vendor_id"
        ] == vendor_id:
            raise ValueError(
                "この業者には既に"
                "ログインアカウントがあります。"
            )

        if account[
            "login_id"
        ] == login_id:
            raise ValueError(
                "このログインIDは"
                "既に使用されています。"
            )

    current_time = now_text()

    append_sheet_row(
        "業者ログイン!A:H",
        [
            vendor_id,
            login_id,
            generate_password_hash(
                password
            ),
            "TRUE",
            current_time,
            current_time,
            "",
            current_time,
        ],
    )

    return True


def save_vendor_login_account(
    vendor_id,
    login_id,
    password="",
    enabled=True,
):
    vendor_id = str(
        vendor_id or ""
    ).strip()

    login_id = str(
        login_id or ""
    ).strip()

    password = str(
        password or ""
    )

    if not vendor_id:
        raise ValueError(
            "業者IDが空です。"
        )

    if not login_id:
        raise ValueError(
            "ログインIDが空です。"
        )

    vendor = get_vendor_by_id(
        vendor_id,
        get_vendor_master(),
    )

    if not vendor:
        raise ValueError(
            "提携業者マスターに"
            "該当業者がありません。"
        )

    accounts = get_vendor_login_accounts()

    current_account = None

    for account in accounts:
        if (
            account["vendor_id"]
            == vendor_id
        ):
            current_account = account
            break

    # 他社とのログインID重複を禁止
    for account in accounts:
        if (
            account["login_id"]
            == login_id
            and account["vendor_id"]
            != vendor_id
        ):
            raise ValueError(
                "このログインIDは"
                "既に使用されています。"
            )

    current_time = now_text()

    # -----------------------------------------
    # 新規作成
    # -----------------------------------------
    if not current_account:
        if len(password) < 12:
            raise ValueError(
                "新規設定時のパスワードは"
                "12文字以上にしてください。"
            )

        append_sheet_row(
            "業者ログイン!A:H",
            [
                vendor_id,
                login_id,
                generate_password_hash(
                    password
                ),
                (
                    "TRUE"
                    if enabled
                    else "FALSE"
                ),
                current_time,
                current_time,
                "",
                current_time,
            ],
        )

        return {
            "created": True,
            "password_changed": True,
        }

    # -----------------------------------------
    # 既存アカウント更新
    # -----------------------------------------
    password_hash = (
        current_account[
            "password_hash"
        ]
    )

    password_changed_at = (
        current_account[
            "password_changed_at"
        ]
    )

    password_changed = False

    if password:
        if len(password) < 12:
            raise ValueError(
                "パスワードは"
                "12文字以上にしてください。"
            )

        password_hash = (
            generate_password_hash(
                password
            )
        )

        password_changed_at = (
            current_time
        )

        password_changed = True

    row_num = current_account[
        "row_number"
    ]

    update_sheet_range(
        f"業者ログイン!"
        f"A{row_num}:H{row_num}",
        [[
            vendor_id,
            login_id,
            password_hash,
            (
                "TRUE"
                if enabled
                else "FALSE"
            ),
            current_account[
                "registered_at"
            ],
            current_time,
            current_account[
                "last_login_at"
            ],
            password_changed_at,
        ]],
    )

    return {
        "created": False,
        "password_changed":
            password_changed,
    }


def get_vendor_login_account(
    vendor_id,
):
    vendor_id = str(
        vendor_id or ""
    ).strip()

    if not vendor_id:
        return None

    for account in (
        get_vendor_login_accounts()
    ):
        if (
            account["vendor_id"]
            == vendor_id
        ):
            return account

    return None


