def ensure_vendor_quote_answer_sheet():
    service = get_sheets_service()

    metadata = (
        service.spreadsheets()
        .get(
            spreadsheetId=SPREADSHEET_ID,
            fields="sheets.properties.title",
        )
        .execute()
    )

    titles = [
        sheet["properties"]["title"]
        for sheet in metadata.get(
            "sheets",
            [],
        )
    ]

    sheet_name = "業者見積回答"

    if sheet_name not in titles:
        (
            service.spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        sheet_name
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )

    headers = [
        "回答ID",
        "案件ID",
        "枠",
        "業者ID",
        "会社名",
        "見積金額",
        "見積メモ",
        "見積書パス",
        "初回回答日時",
        "最終更新日時",
    ]

    update_sheet_range(
        "業者見積回答!A1:J1",
        [headers],
    )



