def get_line_content(message_id):
    url = (
        "https://api-data.line.me/"
        "v2/bot/message/"
        f"{message_id}/content"
    )

    req = urllib.request.Request(
        url,
        method="GET",
        headers={
            "Authorization":
                f"Bearer {CHANNEL_ACCESS_TOKEN}"
        },
    )

    with urllib.request.urlopen(
        req,
        timeout=15,
    ) as response:
        return response.read()


# =========================================================
# Cloud Storage
# =========================================================

def upload_to_cloud_storage(
    content,
    object_name,
    content_type,
):
    client = storage.Client()

    bucket = client.bucket(
        BUCKET_NAME
    )

    blob = bucket.blob(
        object_name
    )

    blob.upload_from_string(
        content,
        content_type=content_type,
    )


def delete_cloud_storage_object(
    object_name,
):
    if not object_name:
        return

    try:
        client = storage.Client()

        bucket = client.bucket(
            BUCKET_NAME
        )

        blob = bucket.blob(
            object_name
        )

        if blob.exists():
            blob.delete()

    except Exception as e:
        print(
            "DELETE OLD DOCUMENT ERROR:",
            type(e).__name__,
            flush=True,
        )


def save_line_file(
    message,
    case_id,
):
    message_id = message["id"]
    message_type = message["type"]

    content = get_line_content(
        message_id
    )

    now = now_jst()

    year = now.strftime("%Y")
    month = now.strftime("%m")

    timestamp = now.strftime(
        "%Y%m%d_%H%M%S"
    )

    if message_type == "image":
        filename = (
            f"estimate_{timestamp}_"
            f"{message_id}.jpg"
        )

        content_type = "image/jpeg"

    elif message_type == "file":
        original_name = message.get(
            "fileName",
            f"estimate_{message_id}",
        )

        filename = (
            f"{timestamp}_"
            f"{original_name}"
        )

        if original_name.lower().endswith(
            ".pdf"
        ):
            content_type = (
                "application/pdf"
            )
        else:
            content_type = (
                "application/octet-stream"
            )

    else:
        raise ValueError(
            "Unsupported message type"
        )

    object_name = (
        f"{year}/{month}/"
        f"{case_id}/"
        f"{filename}"
    )

    upload_to_cloud_storage(
        content,
        object_name,
        content_type,
    )

    append_sheet_row(
        "見積書!A:H",
        [
            case_id,
            message_id,
            message_type,
            filename,
            (
                f"gs://"
                f"{BUCKET_NAME}/"
                f"{object_name}"
            ),
            now_text(),
            "原本",
            "",
        ],
    )


def get_case_year_month(
    case_id,
):
    try:
        date_part = (
            case_id.split("-")[1]
        )

        year = date_part[0:4]
        month = date_part[4:6]

        if (
            len(year) == 4
            and len(month) == 2
        ):
            return year, month

    except Exception:
        pass

    return (
        now_jst().strftime("%Y"),
        now_jst().strftime("%m"),
    )


def save_admin_comparison_file(
    case_id,
    company_code,
    file_storage,
    old_path="",
):
    if (
        not file_storage
        or not file_storage.filename
    ):
        return old_path

    extension = get_extension(
        file_storage.filename
    )

    if (
        not extension
        or extension
        not in ALLOWED_UPLOAD_EXTENSIONS
    ):
        raise ValueError(
            "アップロードできるファイルは "
            "PDF・JPG・JPEG・PNG のみです。"
        )

    content = file_storage.read()

    if not content:
        raise ValueError(
            "ファイルの内容が空です。"
        )

    content_type = (
        ALLOWED_UPLOAD_EXTENSIONS[
            extension
        ]
    )

    year, month = get_case_year_month(
        case_id
    )

    new_path = (
        f"{year}/{month}/"
        f"{case_id}/"
        f"company_{company_code}/"
        f"estimate_{company_code}"
        f"{extension}"
    )

    upload_to_cloud_storage(
        content,
        new_path,
        content_type,
    )

    if (
        old_path
        and old_path != new_path
    ):
        delete_cloud_storage_object(
            old_path
        )

    append_sheet_row(
        "見積書!A:H",
        [
            case_id,
            "",
            "admin_upload",
            (
                f"estimate_"
                f"{company_code}"
                f"{extension}"
            ),
            (
                f"gs://"
                f"{BUCKET_NAME}/"
                f"{new_path}"
            ),
            now_text(),
            (
                f"{company_code}社"
                "比較見積"
            ),
            "管理画面からアップロード",
        ],
    )

    mark_quote_answered(
        case_id,
        company_code,
    )

    return new_path


# =========================================================
# 見積書閲覧URL
# =========================================================

def create_document_token(
    object_name,
    valid_seconds=
        DOCUMENT_VALID_SECONDS,
):
    if not ADMIN_API_KEY:
        return None

    expires = (
        int(now_jst().timestamp())
        + valid_seconds
    )

    message = (
        f"{object_name}|{expires}"
    )

    signature = hmac.new(
        ADMIN_API_KEY.encode("utf-8"),
        message.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()

    return expires, signature


def build_document_url(
    object_name,
):
    if not object_name:
        return ""

    token = (
        create_document_token(
            object_name
        )
    )

    if not token:
        return ""

    expires, signature = token

    encoded_path = quote(
        object_name,
        safe="",
    )

    return (
        f"{SERVICE_BASE_URL}/document"
        f"?path={encoded_path}"
        f"&expires={expires}"
        f"&sig={signature}"
    )


@app.route(
    "/document",
    methods=["GET"],
)
def serve_document():
    if not ADMIN_API_KEY:
        return "Document service unavailable", 503

    object_name = request.args.get(
        "path",
        "",
    )

    expires_text = request.args.get(
        "expires",
        "",
    )

    supplied_sig = request.args.get(
        "sig",
        "",
    )

    if (
        not object_name
        or not expires_text
        or not supplied_sig
    ):
        return "Invalid link", 400

    try:
        expires = int(
            expires_text
        )
    except ValueError:
        return "Invalid link", 400

    if (
        int(now_jst().timestamp())
        > expires
    ):
        return (
            "この見積書リンクの"
            "有効期限が切れています。"
            "LINEの「見積書を再表示」"
            "から再発行してください。",
            403,
        )

    message = (
        f"{object_name}|{expires}"
    )

    expected_sig = hmac.new(
        ADMIN_API_KEY.encode("utf-8"),
        message.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()

    if not hmac.compare_digest(
        supplied_sig,
        expected_sig,
    ):
        return "Invalid link", 403

    try:
        client = storage.Client()

        bucket = client.bucket(
            BUCKET_NAME
        )

        blob = bucket.blob(
            object_name
        )

        if not blob.exists():
            return "File not found", 404

        blob.reload()

        return Response(
            blob.download_as_bytes(),
            status=200,
            content_type=(
                blob.content_type
                or
                "application/octet-stream"
            ),
            headers={
                "Cache-Control":
                    "private, no-store"
            },
        )

    except Exception as e:
        print(
            "DOCUMENT ERROR:",
            type(e).__name__,
            flush=True,
        )

        return (
            "Unable to open document",
            500,
        )


