def make_text(
    text,
    size="sm",
    weight=None,
    wrap=True,
    margin=None,
):
    item = {
        "type": "text",
        "text": text,
        "size": size,
        "wrap": wrap,
    }

    if weight:
        item["weight"] = weight

    if margin:
        item["margin"] = margin

    return item


def make_button(
    label,
    action,
    style="secondary",
    margin="sm",
):
    return {
        "type": "button",
        "style": style,
        "margin": margin,
        "height": "sm",
        "action": action,
    }


