def get_companies_from_row(row):
    row = row + [""] * (
        28 - len(row)
    )

    source = [
        (
            "A",
            row[15],
            row[16],
            row[17],
            row[25],
        ),
        (
            "B",
            row[18],
            row[19],
            row[20],
            row[26],
        ),
        (
            "C",
            row[21],
            row[22],
            row[23],
            row[27],
        ),
    ]

    return [
        {
            "code": code,
            "name": name,
            "min": min_price,
            "max": max_price,
            "document": document,
        }
        for (
            code,
            name,
            min_price,
            max_price,
            document,
        )
        in source
        if name
    ]


def comparison_price_text(
    min_price,
    max_price,
):
    if min_price and max_price:

        if (
            parse_money(min_price)
            == parse_money(max_price)
        ):
            return format_yen(
                min_price
            )

        return (
            f"{format_yen(min_price)} ～ "
            f"{format_yen(max_price)}程度"
        )

    if min_price:
        return (
            f"{format_yen(min_price)}程度"
        )

    if max_price:
        return (
            f"{format_yen(max_price)}程度"
        )

    return "金額は現地確認後"


def build_comparison_flex(
    case_id,
    row,
):
    row = row + [""] * (
        28 - len(row)
    )

    body = [
        make_text(
            "比較結果",
            "xl",
            "bold",
        ),
        make_text(
            f"受付番号：{case_id}",
            "xs",
            margin="sm",
        ),
    ]

    if row[10]:
        body.extend([
            {
                "type": "separator",
                "margin": "lg",
            },
            make_text(
                "現在のお見積もり",
                "sm",
                "bold",
                margin="lg",
            ),
            make_text(
                format_yen(row[10]),
                "xl",
                "bold",
                margin="sm",
            ),
        ])

    companies = get_companies_from_row(
        row
    )

    for company in companies:
        code = company["code"]
        name = company["name"]

        body.append({
            "type": "separator",
            "margin": "xl",
        })

        body.append(
            make_text(
                f"{code}社",
                "xs",
                "bold",
                margin="lg",
            )
        )

        body.append(
            make_text(
                name,
                "lg",
                "bold",
                margin="sm",
            )
        )

        body.append(
            make_text(
                comparison_price_text(
                    company["min"],
                    company["max"],
                ),
                "md",
                "bold",
                margin="sm",
            )
        )

        document_url = (
            build_document_url(
                company[
                    "document"
                ]
            )
            if company["document"]
            else ""
        )

        if document_url:
            body.append(
                make_uri_button(
                    "見積書を見る",
                    document_url,
                    "primary",
                )
            )

        body.append(
            make_postback_button(
                f"{code}社に相談する",
                (
                    "action=select_company"
                    f"&case_id={case_id}"
                    f"&company={code}"
                ),
                f"{name}に相談する",
            )
        )

    body.extend([
        {
            "type": "separator",
            "margin": "xl",
        },
        make_text(
            "※正式な金額は建物の状態や"
            "現地調査により変更となる"
            "場合があります。",
            "xs",
            margin="lg",
        ),
        make_text(
            "※見積書の閲覧リンクは"
            "3日間有効です。",
            "xs",
            margin="sm",
        ),
    ])

    return {
        "type": "flex",
        "altText":
            "塗装見積もりの比較結果が届きました。",
        "contents": {
            "type": "bubble",
            "body": {
                "type": "box",
                "layout": "vertical",
                "contents": body,
            },
            "footer": {
                "type": "box",
                "layout": "vertical",
                "spacing": "sm",
                "contents": [
                    make_postback_button(
                        "見積書を再表示",
                        (
                            "action="
                            "refresh_documents"
                            f"&case_id={case_id}"
                        ),
                        "見積書を再表示",
                    ),
                    make_postback_button(
                        "今回は見送る",
                        (
                            "action="
                            "decline_comparison"
                            f"&case_id={case_id}"
                        ),
                        "今回は見送る",
                    ),
                ],
            },
        },
    }


def build_refresh_documents_flex(
    case_id,
    row,
):
    companies = get_companies_from_row(
        row
    )

    body = [
        make_text(
            "見積書を再発行しました",
            "lg",
            "bold",
        ),
        make_text(
            "新しいリンクは、この時点から"
            "3日間有効です。",
            "xs",
            margin="sm",
        ),
    ]

    found = False

    for company in companies:
        if not company["document"]:
            continue

        document_url = build_document_url(
            company[
                "document"
            ]
        )

        if not document_url:
            continue

        found = True

        body.append({
            "type": "separator",
            "margin": "lg",
        })

        body.append(
            make_text(
                f"{company['code']}社　"
                f"{company['name']}",
                "md",
                "bold",
                margin="lg",
            )
        )

        body.append(
            make_uri_button(
                f"{company['code']}社の"
                "見積書を見る",
                document_url,
                "primary",
            )
        )

    if not found:
        return None

    return {
        "type": "flex",
        "altText":
            "見積書の閲覧リンクを再発行しました。",
        "contents": {
            "type": "bubble",
            "body": {
                "type": "box",
                "layout": "vertical",
                "contents": body,
            },
            "footer": {
                "type": "box",
                "layout": "vertical",
                "contents": [
                    make_postback_button(
                        "もう一度再表示",
                        (
                            "action="
                            "refresh_documents"
                            f"&case_id={case_id}"
                        ),
                        "見積書を再表示",
                    )
                ],
            },
        },
    }


# =========================================================
# 比較結果送信
# =========================================================

def send_comparison_to_line(
    case_id,
):
    row_num, row = find_case_row(
        case_id
    )

    if not row_num or not row:
        raise ValueError(
            "案件が見つかりません。"
        )

    row = row + [""] * (
        28 - len(row)
    )

    user_id = row[2]

    if not user_id:
        raise ValueError(
            "LINE User IDが"
            "登録されていません。"
        )

    sent_at_existing = str(
        row[24] or ""
    ).strip()

    if sent_at_existing:
        raise ValueError(
            "この案件の比較結果は"
            "すでにLINE送信済みです。"
            f"（{sent_at_existing}）"
        )

    if not get_companies_from_row(
        row
    ):
        raise ValueError(
            "比較会社が1社も"
            "入力されていません。"
        )

    push_message(
        user_id,
        [
            build_comparison_flex(
                case_id,
                row,
            )
        ],
    )

    sent_at = now_text()

    update_sheet_range(
        f"案件!Y{row_num}",
        [[sent_at]],
    )

    update_sheet_range(
        f"案件!L{row_num}",
        [["顧客提示済"]],
    )

    update_sheet_range(
        f"案件!N{row_num}",
        [[sent_at]],
    )

    return sent_at


