# =========================================================
# 提携業者ログイン
# =========================================================

@app.route(
    "/vendor/login",
    methods=["GET", "POST"],
)
def vendor_login():
    error = ""

    if request.method == "POST":
        validate_csrf()

        login_id = request.form.get(
            "login_id",
            "",
        ).strip()

        password = request.form.get(
            "password",
            "",
        )

        account = (
            get_vendor_login_by_username(
                login_id
            )
        )

        if (
            account
            and account[
                "enabled"
            ]
            and account[
                "password_hash"
            ]
            and check_password_hash(
                account[
                    "password_hash"
                ],
                password,
            )
        ):
            vendor = get_vendor_by_id(
                account[
                    "vendor_id"
                ],
                get_vendor_master(),
            )

            if vendor:
                session.clear()

                session[
                    "vendor_logged_in"
                ] = True

                session[
                    "vendor_id"
                ] = account[
                    "vendor_id"
                ]

                session[
                    "vendor_account_updated_at"
                ] = str(
                    account.get(
                        "updated_at",
                        "",
                    )
                    or ""
                )

                session[
                    "vendor_password_changed_at"
                ] = str(
                    account.get(
                        "password_changed_at",
                        "",
                    )
                    or ""
                )

                session[
                    "csrf_token"
                ] = secrets.token_urlsafe(
                    32
                )

                update_sheet_range(
                    "業者ログイン!G"
                    + str(
                        account[
                            "row_number"
                        ]
                    ),
                    [[now_text()]],
                )

                return redirect(
                    url_for(
                        "vendor_dashboard"
                    )
                )

        error = (
            "ログインIDまたは"
            "パスワードが違います。"
        )

    return render_template_string(
        VENDOR_LOGIN_HTML,
        error=error,
        csrf_token=
            get_csrf_token(),
    )


@app.route(
    "/vendor/logout"
)
def vendor_logout():
    session.clear()

    return redirect(
        url_for(
            "vendor_login"
        )
    )


@app.route(
    "/vendor/monthly-billing/<monthly_billing_id>",
    methods=["GET"],
)
def vendor_monthly_billing_detail(
    monthly_billing_id,
):
    if not vendor_logged_in():
        return redirect(
            url_for(
                "vendor_login"
            )
        )

    vendor_id = (
        current_vendor_id()
    )

    record = (
        get_monthly_billing_by_id(
            monthly_billing_id
        )
    )

    if not record:
        abort(404)

    if (
        str(
            record.get(
                "vendor_id",
                "",
            )
            or ""
        ).strip()
        != str(
            vendor_id or ""
        ).strip()
    ):
        abort(404)

    record = dict(record)

    record[
        "billing_amount_text"
    ] = format_yen(
        parse_money(
            record.get(
                "billing_amount",
                "",
            )
        )
        or 0
    )

    record[
        "display_status"
    ] = billing_display_status(
        record
    )

    details = (
        get_monthly_billing_details(
            monthly_billing_id
        )
    )

    # 月次請求の親レコードだけでなく、
    # 各明細についてもログイン中の業者IDを照合する。
    # 他社明細が紐づいている場合は表示しない。
    for item in details:

        if (
            str(
                item.get(
                    "vendor_id",
                    "",
                )
                or ""
            ).strip()
            != str(
                vendor_id or ""
            ).strip()
        ):
            abort(404)

        item[
            "contract_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "contract_amount",
                    "",
                )
            )
            or 0
        )

        item[
            "fee_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "fee_amount",
                    "",
                )
            )
            or 0
        )

        item[
            "tax_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "tax_amount",
                    "",
                )
            )
            or 0
        )

        item[
            "billing_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "billing_amount",
                    "",
                )
            )
            or 0
        )

    return render_template_string(
        VENDOR_MONTHLY_BILLING_DETAIL_HTML,
        record=record,
        details=details,
    )


