    if not vendor:
        session.clear()

        return redirect(
            url_for(
                "vendor_login"
            )
        )

    records = []

    for item in (
        get_monthly_settlement_records()
    ):

        if (
            str(
                item.get(
                    "vendor_id",
                    "",
                )
                or ""
            ).strip()
            != str(
                vendor_id or ""
            ).strip()
        ):
            continue

        row = dict(item)

        row[
            "vendor_payment_amount_text"
        ] = format_yen(
            parse_money(
                row.get(
                    "vendor_payment_amount",
                    "",
                )
            )
            or 0
        )

        records.append(
            row
        )

    records.sort(
        key=lambda item: (
            str(
                item.get(
                    "target_month",
                    "",
                )
                or ""
            ),
            str(
                item.get(
                    "monthly_settlement_id",
                    "",
                )
                or ""
            ),
        ),
        reverse=True,
    )

    return render_template_string(
        VENDOR_MONTHLY_SETTLEMENTS_HTML,
        vendor=vendor,
        records=records,
    )


