@app.route(
    "/vendor/case/<case_id>/reference-document",
    methods=["GET"],
)
def vendor_reference_document(
    case_id,
):
    if not vendor_logged_in():
        return redirect(
            url_for(
                "vendor_login"
            )
        )

    vendor_id = current_vendor_id()

    # 現在この案件へ割り当てられている
    # 業者であることを必ず確認する
    item = get_vendor_portal_case_detail(
        vendor_id,
        case_id,
    )

    if not item:
        abort(404)

    reference = (
        get_vendor_reference_document(
            case_id
        )
    )

    if (
        not reference
        or str(
            reference.get(
                "status",
                "",
            )
            or ""
        ).strip()
        != "公開中"
    ):
        abort(404)

    document_path = str(
        reference.get(
            "document_path",
            "",
        )
        or ""
    ).strip()

    if not document_path:
        abort(404)

    try:
        client = storage.Client()

        bucket = client.bucket(
            BUCKET_NAME
        )

        blob = bucket.blob(
            document_path
        )

        if not blob.exists():
            return (
                "資料が見つかりません。",
                404,
            )

        blob.reload()

        return Response(
            blob.download_as_bytes(),
            status=200,
            content_type=(
                blob.content_type
                or reference.get(
                    "content_type",
                    "",
                )
                or "application/octet-stream"
            ),
            headers={
                "Cache-Control":
                    "private, no-store, no-cache, max-age=0",
                "Pragma":
                    "no-cache",
                "Expires":
                    "0",
            },
        )

    except Exception as e:
        print(
            "VENDOR REFERENCE DOCUMENT ERROR:",
            type(e).__name__,
            flush=True,
        )

        return (
            "資料を開けませんでした。",
            500,
        )


