# 管理画面 請求管理
# =========================================================

@app.route(
    "/admin/billing",
    methods=[
        "GET",
        "POST",
    ],
)
def admin_billing():

    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    ensure_monthly_billing_sheet()
    ensure_monthly_billing_detail_sheet()

    error = ""
    success = ""
    preview_candidates = []
    preview_target_month = ""

    if request.method == "POST":
        try:
            validate_csrf()

            target_month = str(
                request.form.get(
                    "target_month",
                    "",
                )
                or ""
            ).strip()

            if not re.match(
                r"^\d{4}-\d{2}$",
                target_month,
            ):
                raise ValueError(
                    "対象月を正しく"
                    "指定してください。"
                )

            action = str(
                request.form.get(
                    "action",
                    "generate",
                )
                or "generate"
            ).strip()

            if action == "preview":
                preview_target_month = (
                    target_month
                )

                preview_candidates = (
                    build_monthly_billing_candidates(
                        target_month
                    )
                )

                for item in preview_candidates:
                    item["fee_amount_text"] = (
                        format_yen(
                            parse_money(
                                item.get(
                                    "fee_amount",
                                    "",
                                )
                            )
                            or 0
                        )
                    )

                    item["tax_amount_text"] = (
                        format_yen(
                            parse_money(
                                item.get(
                                    "tax_amount",
                                    "",
                                )
                            )
                            or 0
                        )
                    )

                    item["billing_amount_text"] = (
                        format_yen(
                            parse_money(
                                item.get(
                                    "billing_amount",
                                    "",
                                )
                            )
                            or 0
                        )
                    )

                    for detail in item.get(
                        "details",
                        [],
                    ):
                        detail[
                            "fee_amount_text"
                        ] = format_yen(
                            parse_money(
                                detail.get(
                                    "fee_amount",
                                    "",
                                )
                            )
                            or 0
                        )

                        detail[
                            "tax_amount_text"
                        ] = format_yen(
                            parse_money(
                                detail.get(
                                    "tax_amount",
                                    "",
                                )
                            )
                            or 0
                        )

                        detail[
                            "billing_amount_text"
                        ] = format_yen(
                            parse_money(
                                detail.get(
                                    "billing_amount",
                                    "",
                                )
                            )
                            or 0
                        )

            elif action == "generate":
                current_month = (
                    now_text()[:7]
                )

                if (
                    target_month
                    >= current_month
                ):
                    raise ValueError(
                        "当月・未来月は"
                        "締め処理できません。"
                    )

                result = (
                    generate_monthly_billings(
                        target_month
                    )
                )

                candidate_count = int(
                    result.get(
                        "candidate_count",
                        0,
                    )
                    or 0
                )

                created_count = int(
                    result.get(
                        "created_count",
                        0,
                    )
                    or 0
                )

                locked_count = int(
                    result.get(
                        "locked_count",
                        0,
                    )
                    or 0
                )

                updated_count = int(
                    result.get(
                        "updated_count",
                        0,
                    )
                    or 0
                )

                if candidate_count == 0:
                    success = (
                        f"{target_month} は"
                        "月次請求の対象データが"
                        "ありませんでした。"
                    )
                else:
                    success = (
                        f"{target_month} の"
                        "月次請求処理が完了しました。"
                        f" 新規 {created_count}件、"
                        f"確定済み {locked_count}件、"
                        f"更新 {updated_count}件。"
                    )

            else:
                raise ValueError(
                    "不正な操作が指定されました。"
                )

        except ValueError as e:
            error = str(e)

    records = (
        get_monthly_billing_records()
    )

    for item in records:

        item[
            "display_status"
        ] = billing_display_status(
            item
        )

        billing_amount = (
            parse_money(
                item.get(
                    "billing_amount",
                    "",
                )
            )
            or 0
        )

        item[
            "billing_amount_text"
        ] = format_yen(
            billing_amount
        )

        item[
            "detail_count_text"
        ] = str(
            item.get(
                "detail_count",
                "",
            )
            or "0"
        )

    records.sort(
        key=lambda item: (
            str(
                item.get(
                    "target_month",
                    "",
                )
            ),
            str(
                item.get(
                    "vendor_id",
                    "",
                )
            ),
        ),
        reverse=True,
    )

    return render_template_string(
        ADMIN_BILLING_LIST_HTML,
        records=records,
        error=error,
        success=success,
        preview_candidates=
            preview_candidates,
        preview_target_month=
            preview_target_month,
        csrf_token=get_csrf_token(),
    )




@app.route(
    "/admin/monthly-settlements",
    methods=[
        "GET",
        "POST",
    ],
)
def admin_monthly_settlements():
    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    ensure_monthly_settlement_sheet()
    ensure_monthly_settlement_detail_sheet()

    error = ""

    success = (
        "月次精算を確定しました。"
        if request.args.get(
            "confirmed"
        ) == "1"
        else ""
    )

    # =====================================================
    # POST：月次精算確定
    # =====================================================

    if request.method == "POST":
        try:
            validate_csrf()

            action = str(
                request.form.get(
                    "action",
                    "",
                )
                or ""
            ).strip()

            if (
                action
                != "confirm_monthly_settlement"
            ):
                raise ValueError(
                    "操作内容が不正です。"
                )

            target_month = str(
                request.form.get(
                    "target_month",
                    "",
                )
                or ""
            ).strip()

            vendor_id = str(
                request.form.get(
                    "vendor_id",
                    "",
                )
                or ""
            ).strip()

            confirmed_date = str(
                request.form.get(
                    "confirmed_date",
                    "",
                )
                or ""
            ).strip()

            result = (
                confirm_monthly_settlement(
                    target_month=
                        target_month,
                    vendor_id=
                        vendor_id,
                    confirmed_date=
                        confirmed_date,
                )
            )

            return redirect(
                url_for(
                    "admin_monthly_settlements",
                    target_month=
                        target_month,
                    confirmed="1",
                    settlement_id=
                        result[
                            "monthly_settlement_id"
                        ],
                )
            )

        except Exception as exc:
            error = str(exc)

            target_month = str(
                request.form.get(
                    "target_month",
                    "",
                )
                or ""
            ).strip()

    else:
        target_month = str(
            request.args.get(
                "target_month",
                "",
            )
            or ""
        ).strip()

    # =====================================================
    # GET / POSTエラー時：候補を再表示
    # =====================================================

    candidates = []

    if target_month:
        try:
            candidates = (
                build_monthly_settlement_candidates(
                    target_month
                )
            )

        except Exception as exc:
            if not error:
                error = str(exc)

    for group in candidates:

        group[
            "customer_payment_amount_text"
        ] = format_yen(
            parse_money(
                group.get(
                    "customer_payment_amount",
                    "",
                )
            )
            or 0
        )

        group[
            "company_deposit_amount_text"
        ] = format_yen(
            parse_money(
                group.get(
                    "company_deposit_amount",
                    "",
                )
            )
            or 0
        )

        group[
            "payment_provider_fee_text"
        ] = format_yen(
            parse_money(
                group.get(
                    "payment_provider_fee",
                    "",
                )
            )
            or 0
        )

        group[
            "company_deduction_amount_text"
        ] = format_yen(
            parse_money(
                group.get(
                    "company_deduction_amount",
                    "",
                )
            )
            or 0
        )

        group[
            "vendor_payment_amount_text"
        ] = format_yen(
            parse_money(
                group.get(
                    "vendor_payment_amount",
                    "",
                )
            )
            or 0
        )

        for item in group.get(
            "details",
            [],
        ):

            item[
                "customer_payment_amount_text"
            ] = format_yen(
                parse_money(
                    item.get(
                        "customer_payment_amount",
                        "",
                    )
                )
                or 0
            )

            item[
                "company_deposit_amount_text"
            ] = format_yen(
                parse_money(
                    item.get(
                        "company_deposit_amount",
                        "",
                    )
                )
                or 0
            )

            item[
                "company_deduction_amount_text"
            ] = format_yen(
                parse_money(
                    item.get(
                        "company_deduction_amount",
                        "",
                    )
                )
                or 0
            )

            item[
                "vendor_payment_amount_text"
            ] = format_yen(
                parse_money(
                    item.get(
                        "vendor_payment_amount",
                        "",
                    )
                )
                or 0
            )

    settlement_records = (
        get_monthly_settlement_records()
    )

    settlement_records.sort(
        key=lambda item: (
            str(
                item.get(
                    "target_month",
                    "",
                )
                or ""
            ),
            str(
                item.get(
                    "monthly_settlement_id",
                    "",
                )
                or ""
            ),
        ),
        reverse=True,
    )

    for item in settlement_records:
        item[
            "vendor_payment_amount_text"
        ] = format_yen(
            parse_money(
                item.get(
                    "vendor_payment_amount",
                    "",
                )
            )
            or 0
        )

    return render_template_string(
        ADMIN_MONTHLY_SETTLEMENT_HTML,
        target_month=
            target_month,
        candidates=
            candidates,
        error=
            error,
        success=
            success,
        csrf_token=
            get_csrf_token(),
        settlement_records=
            settlement_records,
    )




@app.route(
    "/admin/monthly-settlement/<monthly_settlement_id>",
    methods=[
        "GET",
        "POST",
    ],
)
def admin_monthly_settlement_detail(
    monthly_settlement_id,
):
    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    ensure_monthly_settlement_sheet()
    ensure_monthly_settlement_detail_sheet()

    record = (
        get_monthly_settlement_by_id(
            monthly_settlement_id
        )
    )

    if not record:
        abort(404)

    error = ""

    success = (
        "提携業者支払済みとして登録しました。"
        if request.args.get("paid") == "1"
        else ""
    )

    if request.args.get("generated") == "1":
        success = (
            "月次精算書PDFを生成して"
            "登録しました。"
        )

    if request.method == "POST":
        try:
            validate_csrf()

            action = str(
                request.form.get(
                    "action",
                    "",
                )
                or ""
            ).strip()

            if action == "generate_settlement_pdf":
                save_generated_monthly_settlement_pdf(
                    monthly_settlement_id
                )

                return redirect(
                    url_for(
                        "admin_monthly_settlement_detail",
                        monthly_settlement_id=
                            monthly_settlement_id,
                        generated="1",
                    )
                )

            if action == "mark_vendor_paid":
                vendor_payment_date = str(
                    request.form.get(
                        "vendor_payment_date",
                        "",
                    )
                    or ""
                ).strip()

                mark_monthly_settlement_paid(
                    monthly_settlement_id,
                    vendor_payment_date,
                )

                return redirect(
                    url_for(
                        "admin_monthly_settlement_detail",
                        monthly_settlement_id=
                            monthly_settlement_id,
                        paid="1",
                    )
                )

            raise ValueError(
                "操作内容が不正です。"
            )

        except Exception as exc:
            error = str(exc)

            record = (
                get_monthly_settlement_by_id(
                    monthly_settlement_id
                )
            )

            if not record:
                abort(404)

    details = (
        get_monthly_settlement_details(
            monthly_settlement_id
        )
    )

    amount_fields = [
        "customer_payment_amount",
        "company_deposit_amount",
        "payment_provider_fee",
        "fee_amount",
        "tax_amount",
        "company_deduction_amount",
        "vendor_payment_amount",
    ]

    for field in amount_fields:
        record[
            field + "_text"
        ] = format_yen(
            parse_money(
                record.get(
                    field,
                    "",
                )
            )
            or 0
        )

    for item in details:
        for field in amount_fields:
            item[
                field + "_text"
            ] = format_yen(
                parse_money(
                    item.get(
                        field,
                        "",
                    )
                )
                or 0
            )

    return render_template_string(
        ADMIN_MONTHLY_SETTLEMENT_DETAIL_HTML,
        record=record,
        details=details,
        error=error,
        success=success,
        csrf_token=get_csrf_token(),
    )






@app.route(
    "/admin/monthly-billing/<monthly_billing_id>",
    methods=[
        "GET",
        "POST",
    ],
)
def admin_monthly_billing_detail(
    monthly_billing_id,
):
    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    ensure_monthly_billing_sheet()
    ensure_monthly_billing_detail_sheet()

    record = (
        get_monthly_billing_by_id(
            monthly_billing_id
        )
    )

    if not record:
        abort(404)

    statuses = [
        "未請求",
        "請求済み",
        "一部入金",
        "入金済み",
        "取消",
    ]

    error = ""

    success = (
        "請求書PDFを自動生成して登録しました。"
        if request.args.get("generated") == "1"
        else ""
    )

    if request.method == "POST":
        try:
            validate_csrf()

            action = str(
                request.form.get(
                    "action",
                    "save",
                )
                or "save"
            ).strip()

            if action == "generate_invoice_pdf":
                save_generated_monthly_billing_invoice(
                    monthly_billing_id
                )

                return redirect(
                    url_for(
                        "admin_monthly_billing_detail",
                        monthly_billing_id=
                            monthly_billing_id,
                        generated="1",
                    )
                )

            invoice_date = (
                request.form.get(
                    "invoice_date",
                    "",
                ).strip()
            )

            due_date = (
                request.form.get(
                    "due_date",
                    "",
                ).strip()
            )

            payment_date = (
                request.form.get(
                    "payment_date",
                    "",
                ).strip()
            )

            payment_amount_raw = (
                request.form.get(
                    "payment_amount",
                    "",
                ).strip()
            )

            payment_status = (
                request.form.get(
                    "payment_status",
                    "未請求",
                ).strip()
            )

            invoice_number = (
                request.form.get(
                    "invoice_number",
                    "",
                ).strip()
            )

            note = (
                request.form.get(
                    "note",
                    "",
                ).strip()
            )

            invoice_file = (
                request.files.get(
                    "invoice_document"
                )
            )

            invoice_date = (
                validate_date_string(
                    invoice_date,
                    "請求日",
                )
            )

            due_date = (
                validate_date_string(
                    due_date,
                    "支払期限",
                )
            )

            payment_date = (
                validate_date_string(
                    payment_date,
                    "入金日",
                )
            )

            if not due_date:
                due_date = (
                    monthly_billing_due_date(
                        record[
                            "target_month"
                        ]
                    )
                )

            if (
                invoice_date
                and due_date
                and due_date < invoice_date
            ):
                raise ValueError(
                    "支払期限は請求日以降の日付を"
                    "入力してください。"
                )

            if (
                invoice_date
                and payment_date
                and payment_date < invoice_date
            ):
                raise ValueError(
                    "入金日は請求日以降の日付を"
                    "入力してください。"
                )

            if payment_status not in statuses:
                raise ValueError(
                    "入金状況の値が不正です。"
                )

            payment_amount = ""

            if payment_amount_raw:
                payment_amount = (
                    parse_money(
                        payment_amount_raw
                    )
                )

                if payment_amount < 0:
                    raise ValueError(
                        "入金額にマイナス値は"
                        "入力できません。"
                    )

            billing_amount = (
                parse_money(
                    record.get(
                        "billing_amount",
                        "",
                    )
                )
                or 0
            )

            if payment_status == "取消":
                if (
                    payment_date
                    or (
                        payment_amount != ""
                        and payment_amount is not None
                        and payment_amount > 0
                    )
                ):
                    raise ValueError(
                        "取消にする場合は"
                        "入金日・入金額を"
                        "登録できません。"
                    )

                payment_date = ""
                payment_amount = ""

            elif (
                payment_amount != ""
                and payment_amount is not None
            ):
                if (
                    payment_amount
                    > billing_amount
                ):
                    raise ValueError(
                        "入金額は請求額を"
                        "超えて登録できません。"
                    )

                if (
                    payment_amount > 0
                    and not payment_date
                ):
                    raise ValueError(
                        "入金額を登録する場合は"
                        "入金日を入力してください。"
                    )

                if (
                    payment_amount
                    >= billing_amount
                    and billing_amount > 0
                ):
                    payment_status = (
                        "入金済み"
                    )

                elif payment_amount > 0:
                    payment_status = (
                        "一部入金"
                    )

                elif invoice_date:
                    payment_status = (
                        "請求済み"
                    )

            elif (
                invoice_date
                and payment_status
                == "未請求"
            ):
                payment_status = (
                    "請求済み"
                )

            if (
                payment_date
                and (
                    payment_amount == ""
                    or payment_amount is None
                    or payment_amount <= 0
                )
            ):
                raise ValueError(
                    "入金日を登録する場合は"
                    "入金額も入力してください。"
                )

            if (
                payment_status
                in (
                    "請求済み",
                    "一部入金",
                    "入金済み",
                )
                and not invoice_date
            ):
                raise ValueError(
                    "請求済み以降の状態にする場合は"
                    "請求日を入力してください。"
                )

            row_num = record[
                "row_number"
            ]

            # ---------------------------------------------
            # 月次請求を入金済みにする前に、
            # 子明細へ正常に同期できることを事前検証する。
            # ここではSheetを書き換えない。
            # ---------------------------------------------
            if (
                payment_status
                == "入金済み"
            ):
                sync_monthly_paid_to_case_records(
                    monthly_billing_id,
                    payment_date,
                    validate_only=True,
                )

            update_sheet_range(
                f"月次請求!"
                f"I{row_num}:O{row_num}",
                [[
                    invoice_date,
                    due_date,
                    payment_date,
                    payment_amount,
                    payment_status,
                    invoice_number,
                    note,
                ]],
            )

            update_sheet_range(
                f"月次請求!"
                f"T{row_num}",
                [[now_text()]],
            )

            if (
                payment_status
                == "入金済み"
            ):
                sync_monthly_paid_to_case_records(
                    monthly_billing_id,
                    payment_date,
                )

            if (
                invoice_file
                and invoice_file.filename
            ):
                save_monthly_billing_invoice_document(
                    monthly_billing_id,
                    invoice_file,
                )

            record = (
                get_monthly_billing_by_id(
                    monthly_billing_id
                )
            )

        except ValueError as e:
            error = str(e)

            record = dict(record)

            record["invoice_date"] = (
                request.form.get(
                    "invoice_date",
                    "",
                ).strip()
            )

            record["due_date"] = (
                request.form.get(
                    "due_date",
                    "",
                ).strip()
            )

            record["payment_date"] = (
                request.form.get(
                    "payment_date",
                    "",
                ).strip()
            )

            record["payment_amount"] = (
                request.form.get(
                    "payment_amount",
                    "",
                ).strip()
            )

            record["payment_status"] = (
                request.form.get(
                    "payment_status",
                    "未請求",
                ).strip()
            )

            record["invoice_number"] = (
                request.form.get(
                    "invoice_number",
                    "",
                ).strip()
            )

            record["note"] = (
                request.form.get(
                    "note",
                    "",
                ).strip()
            )

    record = dict(record)

    billing_amount = (
        parse_money(
            record.get(
                "billing_amount",
                "",
            )
        )
        or 0
    )

    payment_amount = (
        parse_money(
            record.get(
                "payment_amount",
                "",
            )
        )
        or 0
    )

    record[
        "billing_amount_text"
    ] = format_yen(
        billing_amount
    )

    record[
        "payment_amount_text"
    ] = (
        format_yen(
            payment_amount
        )
        if payment_amount
        else "-"
    )

    record[
        "display_status"
    ] = billing_display_status(
        record
    )

    details = (
        get_monthly_billing_details(
            monthly_billing_id
        )
    )

    for item in details:
        item["contract_amount_text"] = (
            format_yen(
                parse_money(
                    item.get(
                        "contract_amount",
                        "",
                    )
                )
                or 0
            )
        )

        item["fee_amount_text"] = (
            format_yen(
                parse_money(
                    item.get(
                        "fee_amount",
                        "",
                    )
                )
                or 0
            )
        )

        item["tax_amount_text"] = (
            format_yen(
                parse_money(
                    item.get(
                        "tax_amount",
                        "",
                    )
                )
                or 0
            )
        )

        item["billing_amount_text"] = (
            format_yen(
                parse_money(
                    item.get(
                        "billing_amount",
                        "",
                    )
                )
                or 0
            )
        )

    return render_template_string(
        ADMIN_MONTHLY_BILLING_DETAIL_HTML,
        record=record,
        details=details,
        statuses=statuses,
        error=error,
        success=success,
        csrf_token=get_csrf_token(),
    )


@app.route(
    "/admin/monthly-settlement/<monthly_settlement_id>/pdf",
    methods=["GET"],
)
def admin_monthly_settlement_pdf(
    monthly_settlement_id,
):
    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    record = (
        get_monthly_settlement_by_id(
            monthly_settlement_id
        )
    )

    if not record:
        abort(404)

    document_path = str(
        record.get(
            "settlement_document_path",
            "",
        )
        or ""
    ).strip()

    if not document_path:
        abort(404)

    try:
        client = storage.Client()

        bucket = client.bucket(
            BUCKET_NAME
        )

        blob = bucket.blob(
            document_path
        )

        if not blob.exists():
            return (
                "精算書が見つかりません。",
                404,
            )

        content = (
            blob.download_as_bytes()
        )

        if not content.startswith(
            b"%PDF-"
        ):
            return (
                "精算書PDFが不正です。",
                500,
            )

        return Response(
            content,
            status=200,
            content_type="application/pdf",
            headers={
                "Cache-Control":
                    "private, no-store, no-cache, max-age=0",
                "Pragma":
                    "no-cache",
                "Expires":
                    "0",
                "Content-Disposition":
                    'inline; filename="settlement.pdf"',
            },
        )

    except Exception as e:
        print(
            "ADMIN MONTHLY SETTLEMENT "
            "PDF ERROR:",
            type(e).__name__,
            flush=True,
        )

        return (
            "精算書を開けませんでした。",
            500,
        )


