@app.route(
    "/admin/billing/<billing_id>",
    methods=[
        "GET",
        "POST",
    ],
)
def admin_billing_detail(
    billing_id,
):

    if not admin_logged_in():
        return redirect(
            url_for(
                "admin_login"
            )
        )

    ensure_billing_sheet()

    records = get_billing_records()

    record = get_billing_by_id(
        billing_id,
        records,
    )

    if not record:
        abort(404)

    statuses = [
        "未請求",
        "請求済み",
        "一部入金",
        "入金済み",
        "取消",
    ]

    error = ""

    if request.method == "POST":
        try:

            validate_csrf()

            invoice_date = request.form.get(
                "invoice_date",
                "",
            ).strip()

            due_date = request.form.get(
                "due_date",
                "",
            ).strip()

            payment_date = request.form.get(
                "payment_date",
                "",
            ).strip()

            payment_amount_raw = request.form.get(
                "payment_amount",
                "",
            ).strip()

            payment_status = request.form.get(
                "payment_status",
                "未請求",
            ).strip()

            invoice_number = request.form.get(
                "invoice_number",
                "",
            ).strip()

            note = request.form.get(
                "note",
                "",
            ).strip()

            invoice_file = request.files.get(
                "invoice_document"
            )

            invoice_date = validate_date_string(
                invoice_date,
                "請求日",
            )

            due_date = validate_date_string(
                due_date,
                "支払期限",
            )

            payment_date = validate_date_string(
                payment_date,
                "入金日",
            )

            if (
                invoice_date
                and due_date
                and due_date < invoice_date
            ):
                raise ValueError(
                    "支払期限は請求日以降の日付を"
                    "入力してください。"
                )

            if (
                invoice_date
                and payment_date
                and payment_date < invoice_date
            ):
                raise ValueError(
                    "入金日は請求日以降の日付を"
                    "入力してください。"
                )

            payment_amount = ""

            if payment_status not in statuses:
                raise ValueError(
                    "入金状況の値が不正です。"
                )

            if payment_amount_raw:
                payment_amount = parse_money(
                    payment_amount_raw
                )

                if payment_amount < 0:
                    raise ValueError(
                        "入金額にマイナス値は入力できません。"
                    )

            if (
                invoice_date
                and not due_date
            ):
                due_date = (
                    calculate_next_month_end(
                        invoice_date
                    )
                )

            billing_amount = (
                parse_money(
                    record[
                        "billing_amount"
                    ]
                )
                or 0
            )

            if payment_status == "取消":

                if (
                    payment_date
                    or (
                        payment_amount != ""
                        and payment_amount is not None
                        and payment_amount > 0
                    )
                ):
                    raise ValueError(
                        "取消にする場合は"
                        "入金日・入金額を登録できません。"
                    )

                payment_date = ""
                payment_amount = ""

            elif (
                payment_amount != ""
                and payment_amount is not None
            ):
                if payment_amount > billing_amount:
                    raise ValueError(
                        "入金額は請求額を超えて登録できません。"
                    )

                if (
                    payment_amount > 0
                    and not payment_date
                ):
                    raise ValueError(
                        "入金額を登録する場合は"
                        "入金日を入力してください。"
                    )

                if payment_amount >= billing_amount:
                    payment_status = "入金済み"

                elif payment_amount > 0:
                    payment_status = "一部入金"

                elif invoice_date:
                    payment_status = "請求済み"

            elif (
                invoice_date
                and payment_status == "未請求"
            ):
                payment_status = "請求済み"

            if (
                payment_date
                and (
                    payment_amount == ""
                    or payment_amount is None
                    or payment_amount <= 0
                )
            ):
                raise ValueError(
                    "入金日を登録する場合は"
                    "入金額も入力してください。"
                )

            if (
                payment_status
                in (
                    "請求済み",
                    "一部入金",
                    "入金済み",
                )
                and not invoice_date
            ):
                raise ValueError(
                    "請求済み以降の状態にする場合は"
                    "請求日を入力してください。"
                )

            row_num = record[
                "row_number"
            ]

            update_sheet_range(
                f"請求管理!"
                f"L{row_num}:T{row_num}",
                [[
                    invoice_date,
                    due_date,
                    payment_date,
                    payment_amount,
                    payment_status,
                    invoice_number,
                    note,
                    record[
                        "registered_at"
                    ],
                    now_text(),
                ]],
            )

            referral_row_num, referral_row = (
                find_referral_row(
                    record["case_id"]
                )
            )

            if (
                referral_row_num
                and referral_row
            ):
                referral_row = (
                    referral_row
                    + [""] * (
                        16 - len(referral_row)
                    )
                )

                referral_row[12] = (
                    payment_status
                )

                update_sheet_range(
                    f"紹介・成約!"
                    f"A{referral_row_num}:"
                    f"P{referral_row_num}",
                    [referral_row[:16]],
                )

            if (
                invoice_file
                and invoice_file.filename
            ):
                save_billing_invoice_document(
                    billing_id,
                    invoice_file,
                )

            records = get_billing_records()

            record = get_billing_by_id(
                billing_id,
                records,
            )


        except ValueError as e:
            error = str(e)

            record = dict(record)

            record["invoice_date"] = (
                request.form.get(
                    "invoice_date",
                    "",
                ).strip()
            )

            record["due_date"] = (
                request.form.get(
                    "due_date",
                    "",
                ).strip()
            )

            record["payment_date"] = (
                request.form.get(
                    "payment_date",
                    "",
                ).strip()
            )

            record["payment_amount"] = (
                request.form.get(
                    "payment_amount",
                    "",
                ).strip()
            )

            submitted_status = (
                request.form.get(
                    "payment_status",
                    "",
                ).strip()
            )

            if submitted_status in statuses:
                record["payment_status"] = (
                    submitted_status
                )

            record["invoice_number"] = (
                request.form.get(
                    "invoice_number",
                    "",
                ).strip()
            )

            record["note"] = (
                request.form.get(
                    "note",
                    "",
                ).strip()
            )

    billing_amount_num = (
        parse_money(
            record[
                "billing_amount"
            ]
        )
        or 0
    )

    record[
        "billing_amount_text"
    ] = format_yen(
        billing_amount_num
    )

    return render_template_string(
        ADMIN_BILLING_DETAIL_HTML,
        record=record,
        statuses=statuses,
        error=error,
        csrf_token=
            get_csrf_token(),
    )



