def get_solar_detail_record(case_id):
    rows = get_sheet_values(
        f"{SOLAR_DETAIL_SHEET_NAME}!A2:M"
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if (
            row
            and str(row[0] or "").strip()
            == str(case_id or "").strip()
        ):
            row = row + [""] * max(
                0,
                13 - len(row),
            )

            return {
                "row_number": index,
                "case_id": row[0],
                "received_at": row[1],
                "postal_code": row[2],
                "municipality": row[3],
                "name": row[4],
                "phone": row[5],
                "email": row[6],
                "consultation": row[7],
                "estimate_amount": row[8],
                "filename": row[9],
                "storage_path": row[10],
                "consent_at": row[11],
                "diagnosis_status": row[12],
            }

    return None


def get_solar_ai_extraction(case_id):
    ensure_solar_ai_sheet()

    rows = get_sheet_values(
        f"{SOLAR_AI_SHEET_NAME}!A2:AR"
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if (
            row
            and str(row[0] or "").strip()
            == str(case_id or "").strip()
        ):
            row = row + [""] * max(
                0,
                44 - len(row),
            )

            result = {
                "row_number": index,
                "case_id": row[0],
                "analyzed_at": row[1],
                "analysis_status": row[2],
                "model": row[3],
                "response_id": row[4],
            }

            for offset, key in enumerate(
                SOLAR_AI_KEYS,
                start=5,
            ):
                result[key] = row[offset]

            result["important_notes_json"] = row[40]
            result["raw_json"] = row[41]
            result["confirm_status"] = row[42]
            result["confirmed_at"] = row[43]

            try:
                result["important_notes"] = (
                    json.loads(row[40])
                    if row[40]
                    else []
                )
            except Exception:
                result["important_notes"] = []

            return result

    return None


def save_solar_ai_extraction(
    case_id,
    data,
    response_id,
):
    ensure_solar_ai_sheet()

    existing = get_solar_ai_extraction(
        case_id
    )

    notes = data.get(
        "important_notes",
        [],
    )

    if not isinstance(
        notes,
        list,
    ):
        notes = []

    row = [
        case_id,
        now_text(),
        "解析済み",
        SOLAR_AI_MODEL,
        response_id,
    ]

    for key in SOLAR_AI_KEYS:
        value = data.get(key)

        if value is None:
            value = ""

        row.append(value)

    row.extend([
        json.dumps(
            notes,
            ensure_ascii=False,
        ),
        json.dumps(
            data,
            ensure_ascii=False,
        ),
        "要確認",
        "",
    ])

    if existing:
        update_sheet_range(
            (
                f"{SOLAR_AI_SHEET_NAME}!"
                f"A{existing['row_number']}:"
                f"AR{existing['row_number']}"
            ),
            [row],
        )

    else:
        append_sheet_row(
            f"{SOLAR_AI_SHEET_NAME}!A:AR",
            row,
        )

    clear_sheet_request_cache()



