def parse_optional_admin_number(
    value,
    field_name,
):
    value = str(
        value or ""
    ).replace(
        ",",
        "",
    ).strip()

    if not value:
        return ""

    try:
        if field_name in SOLAR_AI_INT_FIELDS:
            return int(
                float(value)
            )

        if field_name in SOLAR_AI_FLOAT_FIELDS:
            return float(
                value
            )

        return value

    except Exception:
        raise ValueError(
            f"{field_name} の数値形式が不正です。"
        )


def update_solar_ai_extraction_from_admin(
    case_id,
    form,
):
    record = get_solar_ai_extraction(
        case_id
    )

    if not record:
        raise ValueError(
            "AI解析結果がありません。"
        )

    values = []

    for key in SOLAR_AI_KEYS:
        raw = form.get(
            f"ai_{key}",
            "",
        )

        if (
            key in SOLAR_AI_INT_FIELDS
            or key in SOLAR_AI_FLOAT_FIELDS
        ):
            value = parse_optional_admin_number(
                raw,
                key,
            )
        else:
            value = str(
                raw or ""
            ).strip()

        values.append(
            value
        )

    notes_text = str(
        form.get(
            "ai_important_notes",
            "",
        )
        or ""
    )

    notes = [
        line.strip()
        for line in notes_text.splitlines()
        if line.strip()
    ]

    notes_json = json.dumps(
        notes,
        ensure_ascii=False,
    )

    row_number = record[
        "row_number"
    ]

    # F:AN = SOLAR_AI_KEYS 35項目
    update_sheet_range(
        (
            f"{SOLAR_AI_SHEET_NAME}!"
            f"F{row_number}:AN{row_number}"
        ),
        [values],
    )

    # AO = 重要事項JSON
    update_sheet_range(
        (
            f"{SOLAR_AI_SHEET_NAME}!"
            f"AO{row_number}"
        ),
        [[notes_json]],
    )

    # AP = AI原文JSON は変更しない

    # 修正が入ったため再確認が必要
    update_sheet_range(
        (
            f"{SOLAR_AI_SHEET_NAME}!"
            f"AQ{row_number}:AR{row_number}"
        ),
        [[
            "要確認",
            "",
        ]],
    )

    clear_sheet_request_cache()

    # 抽出値を修正した場合、
    # 既存診断は古いデータになるため無効化
    try:
        invalidate_solar_diagnosis(
            case_id
        )
    except Exception:
        pass


