def download_gcs_uri(
    storage_path,
):
    storage_path = str(
        storage_path or ""
    ).strip()

    if not storage_path.startswith(
        "gs://"
    ):
        raise ValueError(
            "見積書の保存先が不正です。"
        )

    raw = storage_path[5:]

    if "/" not in raw:
        raise ValueError(
            "見積書の保存先が不正です。"
        )

    bucket_name, object_name = (
        raw.split(
            "/",
            1,
        )
    )

    client = storage.Client()

    bucket = client.bucket(
        bucket_name
    )

    blob = bucket.blob(
        object_name
    )

    if not blob.exists():
        raise ValueError(
            "見積書ファイルが見つかりません。"
        )

    blob.reload()

    return (
        blob.download_as_bytes(),
        blob.content_type
        or "application/octet-stream",
    )


def parse_openai_json_text(
    output_text,
):
    value = str(
        output_text or ""
    ).strip()

    if value.startswith("```"):
        lines = value.splitlines()

        if lines:
            lines = lines[1:]

        if (
            lines
            and lines[-1].strip()
            == "```"
        ):
            lines = lines[:-1]

        value = "\n".join(
            lines
        ).strip()

    try:
        result = json.loads(
            value
        )
    except Exception:
        raise ValueError(
            "AI解析結果をJSONとして"
            "読み取れませんでした。"
        )

    if not isinstance(
        result,
        dict,
    ):
        raise ValueError(
            "AI解析結果の形式が不正です。"
        )

    return result



