def normalize_solar_diagnosis_grade(
    value,
):
    grade = str(
        value or ""
    ).strip().upper()

    if (
        grade
        not in SOLAR_DIAGNOSIS_ALLOWED_GRADES
    ):
        return "UNKNOWN"

    return grade


def normalize_solar_diagnosis_item(
    value,
):
    if not isinstance(
        value,
        dict,
    ):
        value = {}

    grade = (
        normalize_solar_diagnosis_grade(
            value.get(
                "grade"
            )
        )
    )

    summary = str(
        value.get(
            "summary",
            "",
        )
        or ""
    ).strip()

    reasons = value.get(
        "reasons",
        [],
    )

    if not isinstance(
        reasons,
        list,
    ):
        reasons = []

    reasons = [
        str(item or "").strip()
        for item in reasons
        if str(item or "").strip()
    ]

    return {
        "grade": grade,
        "summary": summary,
        "reasons": reasons,
    }


def get_solar_diagnosis(
    case_id,
):
    ensure_solar_diagnosis_sheet()

    rows = get_sheet_values(
        (
            f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
            "A2:AH"
        )
    )

    for index, row in enumerate(
        rows,
        start=2,
    ):
        if (
            row
            and str(
                row[0] or ""
            ).strip()
            == str(
                case_id or ""
            ).strip()
        ):
            row = row + [""] * max(
                0,
                34 - len(row),
            )

            result = {
                "row_number": index,
                "case_id": row[0],
                "diagnosed_at": row[1],
                "diagnosis_status": row[2],
                "model": row[3],
                "response_id": row[4],
            }

            offset = 5

            for (
                key,
                label,
            ) in SOLAR_DIAGNOSIS_CATEGORIES:

                grade = row[
                    offset
                ]

                summary = row[
                    offset + 1
                ]

                reasons_json = row[
                    offset + 2
                ]

                try:
                    reasons = (
                        json.loads(
                            reasons_json
                        )
                        if reasons_json
                        else []
                    )
                except Exception:
                    reasons = []

                result[key] = {
                    "label": label,
                    "grade":
                        normalize_solar_diagnosis_grade(
                            grade
                        ),
                    "summary": summary,
                    "reasons": reasons,
                }

                offset += 3

            try:
                result["flags"] = (
                    json.loads(
                        row[29]
                    )
                    if row[29]
                    else []
                )
            except Exception:
                result["flags"] = []

            try:
                result[
                    "missing_information"
                ] = (
                    json.loads(
                        row[30]
                    )
                    if row[30]
                    else []
                )
            except Exception:
                result[
                    "missing_information"
                ] = []

            result[
                "raw_json"
            ] = row[31]

            result[
                "confirm_status"
            ] = row[32]

            result[
                "confirmed_at"
            ] = row[33]

            return result

    return None


def save_solar_diagnosis(
    case_id,
    data,
    response_id,
):
    ensure_solar_diagnosis_sheet()

    existing = get_solar_diagnosis(
        case_id
    )

    row = [
        case_id,
        now_text(),
        "診断済み",
        SOLAR_DIAGNOSIS_MODEL,
        response_id,
    ]

    normalized_data = {}

    for (
        key,
        label,
    ) in SOLAR_DIAGNOSIS_CATEGORIES:

        item = (
            normalize_solar_diagnosis_item(
                data.get(
                    key,
                    {},
                )
            )
        )

        normalized_data[
            key
        ] = item

        row.extend([
            item["grade"],
            item["summary"],
            json.dumps(
                item["reasons"],
                ensure_ascii=False,
            ),
        ])

    flags = data.get(
        "flags",
        [],
    )

    if not isinstance(
        flags,
        list,
    ):
        flags = []

    flags = list(
        dict.fromkeys(
            str(item or "").strip()
            for item in flags
            if str(item or "").strip()
        )
    )

    missing_information = data.get(
        "missing_information",
        [],
    )

    if not isinstance(
        missing_information,
        list,
    ):
        missing_information = []

    missing_information = [
        str(item or "").strip()
        for item in missing_information
        if str(item or "").strip()
    ]

    raw_save = dict(
        data
    )

    raw_save[
        "_normalized"
    ] = normalized_data

    row.extend([
        json.dumps(
            flags,
            ensure_ascii=False,
        ),
        json.dumps(
            missing_information,
            ensure_ascii=False,
        ),
        json.dumps(
            raw_save,
            ensure_ascii=False,
        ),
        "要確認",
        "",
    ])

    if existing:
        update_sheet_range(
            (
                f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
                f"A{existing['row_number']}:"
                f"AH{existing['row_number']}"
            ),
            [row],
        )

    else:
        append_sheet_row(
            (
                f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
                "A:AH"
            ),
            row,
        )

    detail = get_solar_detail_record(
        case_id
    )

    if detail:
        update_sheet_range(
            (
                f"{SOLAR_DETAIL_SHEET_NAME}!"
                f"M{detail['row_number']}"
            ),
            [[
                "診断済み"
            ]],
        )

    clear_sheet_request_cache()


def invalidate_solar_diagnosis(
    case_id,
):
    existing = get_solar_diagnosis(
        case_id
    )

    if not existing:
        return

    update_sheet_range(
        (
            f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
            f"C{existing['row_number']}:"
            f"C{existing['row_number']}"
        ),
        [[
            "要再診断"
        ]],
    )

    update_sheet_range(
        (
            f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
            f"AG{existing['row_number']}:"
            f"AH{existing['row_number']}"
        ),
        [[
            "要確認",
            "",
        ]],
    )

    detail = get_solar_detail_record(
        case_id
    )

    if detail:
        update_sheet_range(
            (
                f"{SOLAR_DETAIL_SHEET_NAME}!"
                f"M{detail['row_number']}"
            ),
            [[
                "要再診断"
            ]],
        )

    clear_sheet_request_cache()


def confirm_solar_diagnosis(
    case_id,
):
    record = get_solar_diagnosis(
        case_id
    )

    if not record:
        raise ValueError(
            "診断結果がありません。"
        )

    if (
        record.get(
            "diagnosis_status"
        )
        != "診断済み"
    ):
        raise ValueError(
            "再診断が必要なため確認済みにできません。"
        )

    update_sheet_range(
        (
            f"{SOLAR_DIAGNOSIS_SHEET_NAME}!"
            f"AG{record['row_number']}:"
            f"AH{record['row_number']}"
        ),
        [[
            "確認済み",
            now_text(),
        ]],
    )

    clear_sheet_request_cache()



def ensure_solar_result_sheet():
    SHEETS_PERF_ENSURE_CALLS['ensure_solar_result_sheet'] = (
        SHEETS_PERF_ENSURE_CALLS.get('ensure_solar_result_sheet', 0)
        + 1
    )
    service = get_sheets_service()

    titles = get_sheet_titles_cached()

    if (
        SOLAR_RESULT_SHEET_NAME
        not in titles
    ):
        (
            service
            .spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        SOLAR_RESULT_SHEET_NAME
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )
        clear_sheet_titles_request_cache()

    update_solar_header_range(
        (
            f"{SOLAR_RESULT_SHEET_NAME}!"
            "A1:F1"
        ),
        [
            SOLAR_RESULT_HEADERS
        ],
    )


def get_solar_result_publication(
    case_id=None,
    token=None,
):
    ensure_solar_result_sheet()

    case_id = str(
        case_id or ""
    ).strip()

    token = str(
        token or ""
    ).strip()

    rows = get_sheet_values(
        (
            f"{SOLAR_RESULT_SHEET_NAME}!"
            "A2:F"
        )
    )

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * max(
            0,
            6 - len(row),
        )

        row_case_id = str(
            row[0] or ""
        ).strip()

        row_token = str(
            row[1] or ""
        ).strip()

        if (
            case_id
            and row_case_id != case_id
        ):
            continue

        if (
            token
            and row_token != token
        ):
            continue

        return {
            "row_number": row_number,
            "case_id": row_case_id,
            "token": row_token,
            "issued_at": row[2],
            "publish_status": row[3],
            "updated_at": row[4],
            "revoked_at": row[5],
        }

    return None


def validate_solar_result_publishable(
    case_id,
):
    if (
        get_case_service_type(
            case_id
        )
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    extraction = get_solar_ai_extraction(
        case_id
    )

    if not extraction:
        raise ValueError(
            "AI抽出結果がありません。"
        )

    if (
        extraction.get(
            "confirm_status"
        )
        != "確認済み"
    ):
        raise ValueError(
            "AI抽出内容が確認済みではありません。"
        )

    diagnosis = get_solar_diagnosis(
        case_id
    )

    if not diagnosis:
        raise ValueError(
            "8項目診断結果がありません。"
        )

    if (
        diagnosis.get(
            "diagnosis_status"
        )
        != "診断済み"
    ):
        raise ValueError(
            "再診断が必要です。"
        )

    if (
        diagnosis.get(
            "confirm_status"
        )
        != "確認済み"
    ):
        raise ValueError(
            "診断結果が確認済みではありません。"
        )

    return (
        extraction,
        diagnosis,
    )


def issue_solar_result_publication(
    case_id,
):
    validate_solar_result_publishable(
        case_id
    )

    ensure_solar_result_sheet()

    existing = (
        get_solar_result_publication(
            case_id=case_id
        )
    )

    # すでに公開中なら同じURLを返す
    if (
        existing
        and existing.get(
            "publish_status"
        )
        == "公開中"
        and existing.get(
            "token"
        )
    ):
        return existing

    token = secrets.token_urlsafe(
        32
    )

    timestamp = now_text()

    if existing:
        update_sheet_range(
            (
                f"{SOLAR_RESULT_SHEET_NAME}!"
                f"B{existing['row_number']}:"
                f"F{existing['row_number']}"
            ),
            [[
                token,
                timestamp,
                "公開中",
                timestamp,
                "",
            ]],
        )

    else:
        (
            get_sheets_service()
            .spreadsheets()
            .values()
            .append(
                spreadsheetId=SPREADSHEET_ID,
                range=(
                    f"{SOLAR_RESULT_SHEET_NAME}!"
                    "A:F"
                ),
                valueInputOption="USER_ENTERED",
                insertDataOption="INSERT_ROWS",
                body={
                    "values": [[
                        case_id,
                        token,
                        timestamp,
                        "公開中",
                        timestamp,
                        "",
                    ]]
                },
            )
            .execute()
        )

    clear_sheet_request_cache()

    return get_solar_result_publication(
        case_id=case_id
    )


def revoke_solar_result_publication(
    case_id,
):
    record = (
        get_solar_result_publication(
            case_id=case_id
        )
    )

    if not record:
        raise ValueError(
            "公開結果ページが発行されていません。"
        )

    timestamp = now_text()

    update_sheet_range(
        (
            f"{SOLAR_RESULT_SHEET_NAME}!"
            f"D{record['row_number']}:"
            f"F{record['row_number']}"
        ),
        [[
            "公開停止",
            timestamp,
            timestamp,
        ]],
    )

    clear_sheet_request_cache()




# =========================================================
# MITENOA 太陽光
# 比較見積もり業者 割当・打診履歴
#
# 塗装用「案件業者割当」とは完全分離する。
#
# 太陽光業者打診
# A 案件ID
# B 枠
# C 業者ID
# D 会社名
# E 記録日時
# F 操作
# G 打診状態
# H 同意バージョン
# I 共有情報JSON
# J 見積書原本共有
# K 備考
# =========================================================

SOLAR_VENDOR_CONTACT_SHEET_NAME = (
    "太陽光業者打診"
)

SOLAR_VENDOR_CONTACT_HEADERS = [
    "案件ID",
    "枠",
    "業者ID",
    "会社名",
    "記録日時",
    "操作",
    "打診状態",
    "同意バージョン",
    "共有情報JSON",
    "見積書原本共有",
    "備考",
]


def ensure_solar_vendor_contact_sheet():
    SHEETS_PERF_ENSURE_CALLS['ensure_solar_vendor_contact_sheet'] = (
        SHEETS_PERF_ENSURE_CALLS.get('ensure_solar_vendor_contact_sheet', 0)
        + 1
    )
    service = get_sheets_service()

    titles = get_sheet_titles_cached()

    if (
        SOLAR_VENDOR_CONTACT_SHEET_NAME
        not in titles
    ):
        (
            service
            .spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        SOLAR_VENDOR_CONTACT_SHEET_NAME
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )
        clear_sheet_titles_request_cache()

    update_solar_header_range(
        (
            f"{SOLAR_VENDOR_CONTACT_SHEET_NAME}!"
            "A1:K1"
        ),
        [
            SOLAR_VENDOR_CONTACT_HEADERS
        ],
    )


def get_solar_vendor_contact_events(
    case_id=None,
):
    ensure_solar_vendor_contact_sheet()

    rows = get_sheet_values(
        (
            f"{SOLAR_VENDOR_CONTACT_SHEET_NAME}!"
            "A2:K"
        )
    )

    case_id = str(
        case_id or ""
    ).strip()

    events = []

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * max(
            0,
            11 - len(row),
        )

        row_case_id = str(
            row[0] or ""
        ).strip()

        if (
            case_id
            and row_case_id != case_id
        ):
            continue

        try:
            shared_snapshot = (
                json.loads(
                    row[8]
                )
                if row[8]
                else {}
            )
        except Exception:
            shared_snapshot = {}

        events.append({
            "row_number": row_number,
            "case_id": row_case_id,
            "slot": str(
                row[1] or ""
            ).strip(),
            "vendor_id": str(
                row[2] or ""
            ).strip(),
            "company_name": str(
                row[3] or ""
            ).strip(),
            "recorded_at": str(
                row[4] or ""
            ).strip(),
            "operation": str(
                row[5] or ""
            ).strip(),
            "contact_status": str(
                row[6] or ""
            ).strip(),
            "consent_version": str(
                row[7] or ""
            ).strip(),
            "shared_snapshot":
                shared_snapshot,
            "estimate_document_shared":
                str(
                    row[9] or ""
                ).strip(),
            "note": str(
                row[10] or ""
            ).strip(),
        })

    return events


def get_solar_vendor_assignments(
    case_id,
):
    assignments = {
        slot: {
            "slot": slot,
            "vendor_id": "",
            "company_name": "",
            "assigned_at": "",
            "contact_status": "未割当",
            "contacted_at": "",
            "consent_version": "",
            "shared_snapshot": {},
            "estimate_document_shared":
                "いいえ",
        }
        for slot in (
            "A",
            "B",
            "C",
        )
    }

    for event in (
        get_solar_vendor_contact_events(
            case_id
        )
    ):
        slot = event.get(
            "slot",
            "",
        )

        if slot not in assignments:
            continue

        operation = event.get(
            "operation",
            "",
        )

        if operation == "割当":
            assignments[slot] = {
                "slot": slot,
                "vendor_id":
                    event.get(
                        "vendor_id",
                        "",
                    ),
                "company_name":
                    event.get(
                        "company_name",
                        "",
                    ),
                "assigned_at":
                    event.get(
                        "recorded_at",
                        "",
                    ),
                "contact_status":
                    "未打診",
                "contacted_at": "",
                "consent_version": "",
                "shared_snapshot": {},
                "estimate_document_shared":
                    "いいえ",
            }

        elif operation == "解除":
            assignments[slot] = {
                "slot": slot,
                "vendor_id": "",
                "company_name": "",
                "assigned_at": "",
                "contact_status": "未割当",
                "contacted_at": "",
                "consent_version": "",
                "shared_snapshot": {},
                "estimate_document_shared":
                    "いいえ",
            }

        elif (
            operation == "打診"
            and assignments[slot][
                "vendor_id"
            ]
            == event.get(
                "vendor_id",
                "",
            )
        ):
            assignments[slot][
                "contact_status"
            ] = "打診済み"

            assignments[slot][
                "contacted_at"
            ] = event.get(
                "recorded_at",
                "",
            )

            assignments[slot][
                "consent_version"
            ] = event.get(
                "consent_version",
                "",
            )

            assignments[slot][
                "shared_snapshot"
            ] = event.get(
                "shared_snapshot",
                {},
            )

            assignments[slot][
                "estimate_document_shared"
            ] = (
                event.get(
                    "estimate_document_shared",
                    "",
                )
                or "いいえ"
            )

    compare_request = (
        get_solar_compare_request(
            case_id
        )
    )

    if (
        compare_request
        and compare_request.get(
            "request_status"
        )
        == "希望あり"
        and compare_request.get(
            "consent_status"
        )
        == "同意済み"
    ):
        current_consented_at = (
            parse_solar_jst_datetime(
                compare_request.get(
                    "consented_at",
                    "",
                )
            )
        )

        if current_consented_at:
            for item in assignments.values():

                if (
                    item.get(
                        "contact_status"
                    )
                    != "打診済み"
                ):
                    continue

                contacted_at = (
                    parse_solar_jst_datetime(
                        item.get(
                            "contacted_at",
                            "",
                        )
                    )
                )

                if (
                    contacted_at
                    and contacted_at
                    < current_consented_at
                ):
                    item[
                        "contact_status"
                    ] = (
                        "再打診が必要"
                    )

    return assignments


def get_solar_case_area(
    case_id,
):
    detail = (
        get_solar_detail_record(
            case_id
        )
        or {}
    )

    area = str(
        detail.get(
            "municipality",
            "",
        )
        or ""
    ).strip()

    if area:
        return area

    _, row = find_case_row(
        case_id
    )

    if row:
        row = row + [""] * max(
            0,
            5 - len(row),
        )

        return str(
            row[4] or ""
        ).strip()

    return ""


def validate_solar_vendor_candidate(
    case_id,
    vendor_id,
):
    if (
        get_case_service_type(case_id)
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    vendors = get_vendor_master()

    vendor = get_vendor_by_id(
        vendor_id,
        vendors,
    )

    if not vendor:
        raise ValueError(
            "指定された提携業者が"
            "見つかりません。"
        )

    if (
        vendor.get(
            "status",
            "",
        )
        not in (
            "提携中",
            "稼働中",
        )
    ):
        raise ValueError(
            f"{vendor['company_name']} は"
            "現在提携中ではありません。"
        )

    if not vendor_service_matches(
        vendor,
        SERVICE_TYPE_SOLAR,
    ):
        raise ValueError(
            f"{vendor['company_name']} は"
            "太陽光・蓄電池対応業者として"
            "登録されていません。"
        )

    area = get_solar_case_area(
        case_id
    )

    if not vendor_area_matches(
        vendor,
        area,
    ):
        raise ValueError(
            f"{vendor['company_name']} は"
            f"案件地域「{area or '-'}」の"
            "対応業者ではありません。"
        )

    return vendor


def record_solar_vendor_assignment(
    case_id,
    slot,
    vendor_id,
):
    slot = str(
        slot or ""
    ).strip().upper()

    vendor_id = str(
        vendor_id or ""
    ).strip()

    if slot not in (
        "A",
        "B",
        "C",
    ):
        raise ValueError(
            "業者枠が不正です。"
        )

    if not vendor_id:
        raise ValueError(
            "提携業者を選択してください。"
        )

    compare_request = (
        get_solar_compare_request(
            case_id
        )
    )

    if not compare_request:
        raise ValueError(
            "比較見積もり受付情報がありません。"
        )

    if (
        compare_request.get(
            "request_status"
        )
        != "希望あり"
    ):
        raise ValueError(
            "比較見積もり希望が"
            "有効ではありません。"
        )

    if (
        compare_request.get(
            "consent_status"
        )
        != "同意済み"
    ):
        raise ValueError(
            "業者への情報共有同意が"
            "有効ではありません。"
        )

    vendor = (
        validate_solar_vendor_candidate(
            case_id,
            vendor_id,
        )
    )

    assignments = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    for other_slot, item in (
        assignments.items()
    ):
        if (
            other_slot != slot
            and item.get(
                "vendor_id"
            )
            == vendor_id
        ):
            raise ValueError(
                f"{vendor['company_name']} は"
                f"既に{other_slot}社へ"
                "割り当てられています。"
            )

    current = assignments[slot]

    if (
        current.get(
            "vendor_id"
        )
        == vendor_id
    ):
        return current

    append_sheet_row(
        (
            f"{SOLAR_VENDOR_CONTACT_SHEET_NAME}!"
            "A:K"
        ),
        [
            case_id,
            slot,
            vendor_id,
            vendor.get(
                "company_name",
                "",
            ),
            now_text(),
            "割当",
            "未打診",
            "",
            "",
            "いいえ",
            "",
        ],
    )

    clear_sheet_request_cache()

    return (
        get_solar_vendor_assignments(
            case_id
        )[slot]
    )


def record_solar_vendor_unassignment(
    case_id,
    slot,
):
    if (
        get_case_service_type(case_id)
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    slot = str(
        slot or ""
    ).strip().upper()

    if slot not in (
        "A",
        "B",
        "C",
    ):
        raise ValueError(
            "業者枠が不正です。"
        )

    assignments = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    current = assignments[slot]

    if not current.get(
        "vendor_id"
    ):
        return current

    append_sheet_row(
        (
            f"{SOLAR_VENDOR_CONTACT_SHEET_NAME}!"
            "A:K"
        ),
        [
            case_id,
            slot,
            current.get(
                "vendor_id",
                "",
            ),
            current.get(
                "company_name",
                "",
            ),
            now_text(),
            "解除",
            "",
            "",
            "",
            "いいえ",
            "",
        ],
    )

    clear_sheet_request_cache()

    return (
        get_solar_vendor_assignments(
            case_id
        )[slot]
    )


def record_solar_vendor_contact(
    case_id,
    slot,
):
    if (
        get_case_service_type(case_id)
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    slot = str(
        slot or ""
    ).strip().upper()

    if slot not in (
        "A",
        "B",
        "C",
    ):
        raise ValueError(
            "業者枠が不正です。"
        )

    compare_request = (
        get_solar_compare_request(
            case_id
        )
    )

    if not compare_request:
        raise ValueError(
            "比較見積もり受付情報がありません。"
        )

    if (
        compare_request.get(
            "request_status"
        )
        != "希望あり"
    ):
        raise ValueError(
            "比較見積もり希望が"
            "有効ではありません。"
        )

    if (
        compare_request.get(
            "consent_status"
        )
        != "同意済み"
    ):
        raise ValueError(
            "情報共有同意が有効ではないため、"
            "業者へ打診できません。"
        )

    assignments = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    current = assignments[slot]

    vendor_id = current.get(
        "vendor_id",
        "",
    )

    if not vendor_id:
        raise ValueError(
            f"{slot}社に業者が"
            "割り当てられていません。"
        )

    if (
        current.get(
            "contact_status"
        )
        == "打診済み"
    ):
        raise ValueError(
            f"{slot}社は既に"
            "打診記録済みです。"
        )

    vendor = (
        validate_solar_vendor_candidate(
            case_id,
            vendor_id,
        )
    )

    snapshot = compare_request.get(
        "shared_snapshot",
        {},
    )

    if not isinstance(
        snapshot,
        dict,
    ) or not snapshot:
        raise ValueError(
            "共有予定情報を確認できません。"
        )

    # 現行の同意では、
    # 顧客アップロード見積書原本は
    # 明示的に共有対象外。
    if snapshot.get(
        "estimate_document_shared"
    ) not in (
        False,
        None,
        "",
    ):
        raise ValueError(
            "現在の同意内容では"
            "見積書原本を共有できません。"
        )

    consent_version = str(
        compare_request.get(
            "consent_version",
            "",
        )
        or ""
    ).strip()

    if not consent_version:
        raise ValueError(
            "同意バージョンを"
            "確認できません。"
        )

    snapshot_json = json.dumps(
        snapshot,
        ensure_ascii=False,
        separators=(
            ",",
            ":",
        ),
    )

    timestamp = now_text()

    append_sheet_row(
        (
            f"{SOLAR_VENDOR_CONTACT_SHEET_NAME}!"
            "A:K"
        ),
        [
            case_id,
            slot,
            vendor_id,
            vendor.get(
                "company_name",
                "",
            ),
            timestamp,
            "打診",
            "打診済み",
            consent_version,
            snapshot_json,
            "いいえ",
            (
                "V1内部打診記録。"
                "外部送信は未実装。"
            ),
        ],
    )

    clear_sheet_request_cache()

    refreshed = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    contacted_companies = [
        item.get(
            "company_name",
            "",
        )
        for item in refreshed.values()
        if (
            item.get(
                "vendor_id"
            )
            and item.get(
                "contact_status"
            )
            == "打診済み"
        )
    ]

    update_solar_compare_operation(
        case_id,
        "打診中",
        " / ".join(
            contacted_companies
        ),
        "いいえ",
        compare_request.get(
            "admin_memo",
            "",
        ),
    )

    return refreshed[slot]



# =========================================================
# MITENOA 太陽光
# 業者向け期限付き閲覧URL
#
# 既存の塗装業者ポータルとは完全分離。
#
# 太陽光業者閲覧
# A 案件ID
# B 枠
# C 業者ID
# D 会社名
# E 閲覧トークン
# F 発行日時
# G 有効期限
# H 公開状態
# I 更新日時
# J 公開停止日時
# K 最終アクセス日時
# L アクセス回数
# M 打診記録日時
# N 同意バージョン
# =========================================================

SOLAR_VENDOR_VIEW_SHEET_NAME = (
    "太陽光業者閲覧"
)

SOLAR_VENDOR_VIEW_HEADERS = [
    "案件ID",
    "枠",
    "業者ID",
    "会社名",
    "閲覧トークン",
    "発行日時",
    "有効期限",
    "公開状態",
    "更新日時",
    "公開停止日時",
    "最終アクセス日時",
    "アクセス回数",
    "打診記録日時",
    "同意バージョン",
]

SOLAR_VENDOR_VIEW_VALID_DAYS = 7


def ensure_solar_vendor_view_sheet():
    SHEETS_PERF_ENSURE_CALLS['ensure_solar_vendor_view_sheet'] = (
        SHEETS_PERF_ENSURE_CALLS.get('ensure_solar_vendor_view_sheet', 0)
        + 1
    )
    service = get_sheets_service()

    titles = get_sheet_titles_cached()

    if (
        SOLAR_VENDOR_VIEW_SHEET_NAME
        not in titles
    ):
        (
            service
            .spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        SOLAR_VENDOR_VIEW_SHEET_NAME
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )
        clear_sheet_titles_request_cache()

    update_solar_header_range(
        (
            f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
            "A1:N1"
        ),
        [
            SOLAR_VENDOR_VIEW_HEADERS
        ],
    )


def get_solar_vendor_view_publication(
    case_id=None,
    slot=None,
    token=None,
    ensure=True,
):
    token_was_supplied = token is not None

    if (
        token_was_supplied
        and not str(token or "").strip()
    ):
        return None

    if ensure:
        ensure_solar_vendor_view_sheet()

    case_id = str(
        case_id or ""
    ).strip()

    slot = str(
        slot or ""
    ).strip().upper()

    token = str(
        token or ""
    ).strip()

    rows = get_sheet_values(
        (
            f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
            "A2:N"
        )
    )

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * max(
            0,
            14 - len(row),
        )

        row_case_id = str(
            row[0] or ""
        ).strip()

        row_slot = str(
            row[1] or ""
        ).strip().upper()

        row_token = str(
            row[4] or ""
        ).strip()

        if (
            case_id
            and row_case_id != case_id
        ):
            continue

        if (
            slot
            and row_slot != slot
        ):
            continue

        if (
            token
            and row_token != token
        ):
            continue

        try:
            access_count = int(
                str(row[11] or "0").strip()
                or "0"
            )
        except Exception:
            access_count = 0

        return {
            "row_number": row_number,
            "case_id": row_case_id,
            "slot": row_slot,
            "vendor_id": str(
                row[2] or ""
            ).strip(),
            "company_name": str(
                row[3] or ""
            ).strip(),
            "token": row_token,
            "issued_at": str(
                row[5] or ""
            ).strip(),
            "expires_at": str(
                row[6] or ""
            ).strip(),
            "publish_status": str(
                row[7] or ""
            ).strip(),
            "updated_at": str(
                row[8] or ""
            ).strip(),
            "revoked_at": str(
                row[9] or ""
            ).strip(),
            "last_accessed_at": str(
                row[10] or ""
            ).strip(),
            "access_count": access_count,
            "contact_recorded_at": str(
                row[12] or ""
            ).strip(),
            "consent_version": str(
                row[13] or ""
            ).strip(),
        }

    return None


def get_solar_vendor_view_publications(
    case_id,
):
    ensure_solar_vendor_view_sheet()

    case_id = str(
        case_id or ""
    ).strip()

    result = {
        "A": None,
        "B": None,
        "C": None,
    }

    rows = get_sheet_values(
        (
            f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
            "A2:N"
        )
    )

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * max(
            0,
            14 - len(row),
        )

        row_case_id = str(
            row[0] or ""
        ).strip()

        if row_case_id != case_id:
            continue

        slot = str(
            row[1] or ""
        ).strip().upper()

        if slot not in result:
            continue

        try:
            access_count = int(
                str(
                    row[11] or "0"
                ).strip()
                or "0"
            )
        except Exception:
            access_count = 0

        result[slot] = {
            "row_number":
                row_number,
            "case_id":
                row_case_id,
            "slot":
                slot,
            "vendor_id":
                str(
                    row[2] or ""
                ).strip(),
            "company_name":
                str(
                    row[3] or ""
                ).strip(),
            "token":
                str(
                    row[4] or ""
                ).strip(),
            "issued_at":
                str(
                    row[5] or ""
                ).strip(),
            "expires_at":
                str(
                    row[6] or ""
                ).strip(),
            "is_expired":
                solar_vendor_view_is_expired(
                    str(
                        row[6] or ""
                    ).strip()
                ),
            "publish_status":
                str(
                    row[7] or ""
                ).strip(),
            "updated_at":
                str(
                    row[8] or ""
                ).strip(),
            "revoked_at":
                str(
                    row[9] or ""
                ).strip(),
            "last_accessed_at":
                str(
                    row[10] or ""
                ).strip(),
            "access_count":
                access_count,
            "contact_recorded_at":
                str(
                    row[12] or ""
                ).strip(),
            "consent_version":
                str(
                    row[13] or ""
                ).strip(),
        }

    return result


def get_solar_contact_event_for_publication(
    publication,
):
    if not publication:
        return None

    case_id = publication.get(
        "case_id",
        "",
    )

    slot = publication.get(
        "slot",
        "",
    )

    vendor_id = publication.get(
        "vendor_id",
        "",
    )

    contact_recorded_at = (
        publication.get(
            "contact_recorded_at",
            "",
        )
    )

    events = (
        get_solar_vendor_contact_events(
            case_id
        )
    )

    matches = [
        event
        for event in events
        if (
            event.get("slot") == slot
            and event.get(
                "vendor_id"
            ) == vendor_id
            and event.get(
                "operation"
            ) == "打診"
            and event.get(
                "recorded_at"
            ) == contact_recorded_at
        )
    ]

    if not matches:
        return None

    return matches[-1]


def parse_solar_jst_datetime(
    value,
):
    value = str(
        value or ""
    ).strip()

    if not value:
        return None

    try:
        return datetime.strptime(
            value,
            "%Y-%m-%d %H:%M:%S",
        ).replace(
            tzinfo=timezone(
                timedelta(hours=9)
            )
        )
    except Exception:
        return None


def validate_solar_contact_current_consent(
    compare_request,
    contact_event,
):
    if not compare_request:
        raise ValueError(
            "比較見積もり受付情報がありません。"
        )

    if not contact_event:
        raise ValueError(
            "打診時の共有記録を確認できません。"
        )

    current_consented_at = (
        parse_solar_jst_datetime(
            compare_request.get(
                "consented_at",
                "",
            )
        )
    )

    contact_recorded_at = (
        parse_solar_jst_datetime(
            contact_event.get(
                "recorded_at",
                "",
            )
        )
    )

    if not current_consented_at:
        raise ValueError(
            "現在の情報共有同意日時を"
            "確認できません。"
        )

    if not contact_recorded_at:
        raise ValueError(
            "打診記録日時を確認できません。"
        )

    # 現在有効な同意より前の打診記録は
    # 再利用しない。
    #
    # 同意撤回 → 再同意となった場合は、
    # 必ず再打診して新しい共有記録を作る。
    if (
        contact_recorded_at
        < current_consented_at
    ):
        raise ValueError(
            "この打診記録は現在の情報共有同意より"
            "前に作成されています。"
            "再同意後に改めて打診してください。"
        )

    return True


def issue_solar_vendor_view_publication(
    case_id,
    slot,
):
    if (
        get_case_service_type(case_id)
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    slot = str(
        slot or ""
    ).strip().upper()

    if slot not in (
        "A",
        "B",
        "C",
    ):
        raise ValueError(
            "業者枠が不正です。"
        )

    compare_request = (
        get_solar_compare_request(
            case_id
        )
    )

    if not compare_request:
        raise ValueError(
            "比較見積もり受付情報がありません。"
        )

    if (
        compare_request.get(
            "request_status"
        )
        != "希望あり"
        or compare_request.get(
            "consent_status"
        )
        != "同意済み"
    ):
        raise ValueError(
            "有効な情報共有同意がありません。"
        )

    assignments = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    assignment = assignments[slot]

    if not assignment.get(
        "vendor_id"
    ):
        raise ValueError(
            f"{slot}社に業者が"
            "割り当てられていません。"
        )

    if (
        assignment.get(
            "contact_status"
        )
        != "打診済み"
    ):
        raise ValueError(
            "打診記録済みの業者だけ"
            "閲覧URLを発行できます。"
        )

    vendor = (
        validate_solar_vendor_candidate(
            case_id,
            assignment.get(
                "vendor_id",
                "",
            ),
        )
    )

    contact_events = [
        event
        for event in (
            get_solar_vendor_contact_events(
                case_id
            )
        )
        if (
            event.get(
                "slot"
            ) == slot
            and event.get(
                "vendor_id"
            ) == assignment.get(
                "vendor_id"
            )
            and event.get(
                "operation"
            ) == "打診"
        )
    ]

    if not contact_events:
        raise ValueError(
            "打診時の共有記録を"
            "確認できません。"
        )

    contact_event = contact_events[-1]

    snapshot = contact_event.get(
        "shared_snapshot",
        {},
    )

    if (
        not isinstance(snapshot, dict)
        or not snapshot
    ):
        raise ValueError(
            "打診時の共有情報を"
            "確認できません。"
        )

    if (
        contact_event.get(
            "estimate_document_shared"
        )
        != "いいえ"
    ):
        raise ValueError(
            "見積書原本共有が無効化されていません。"
        )

    contact_consent_version = str(
        contact_event.get(
            "consent_version",
            "",
        )
        or ""
    ).strip()

    if not contact_consent_version:
        raise ValueError(
            "打診時の同意バージョンを"
            "確認できません。"
        )

    if (
        contact_consent_version
        != str(
            compare_request.get(
                "consent_version",
                "",
            )
            or ""
        ).strip()
    ):
        raise ValueError(
            "現在の同意と打診時の同意が"
            "一致しません。"
            "再打診してください。"
        )

    validate_solar_contact_current_consent(
        compare_request,
        contact_event,
    )

    ensure_solar_vendor_view_sheet()

    existing = (
        get_solar_vendor_view_publication(
            case_id=case_id,
            slot=slot,
        )
    )

    if (
        existing
        and existing.get(
            "publish_status"
        ) == "公開中"
        and existing.get("token")
        and existing.get(
            "vendor_id"
        ) == assignment.get(
            "vendor_id"
        )
        and existing.get(
            "contact_recorded_at"
        ) == contact_event.get(
            "recorded_at"
        )
    ):
        return existing

    token = secrets.token_urlsafe(32)

    now_jst = datetime.now(
        timezone(
            timedelta(hours=9)
        )
    )

    issued_at = now_jst.strftime(
        "%Y-%m-%d %H:%M:%S"
    )

    expires_at = (
        now_jst
        + timedelta(
            days=SOLAR_VENDOR_VIEW_VALID_DAYS
        )
    ).strftime(
        "%Y-%m-%d %H:%M:%S"
    )

    values = [
        assignment.get(
            "vendor_id",
            "",
        ),
        vendor.get(
            "company_name",
            "",
        ),
        token,
        issued_at,
        expires_at,
        "公開中",
        issued_at,
        "",
        "",
        0,
        contact_event.get(
            "recorded_at",
            "",
        ),
        contact_consent_version,
    ]

    if existing:
        update_sheet_range(
            (
                f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
                f"C{existing['row_number']}:"
                f"N{existing['row_number']}"
            ),
            [
                values
            ],
        )

    else:
        append_sheet_row(
            (
                f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
                "A:N"
            ),
            [
                case_id,
                slot,
                *values,
            ],
        )

    clear_sheet_request_cache()

    return (
        get_solar_vendor_view_publication(
            case_id=case_id,
            slot=slot,
        )
    )


def revoke_solar_vendor_view_publication(
    case_id,
    slot,
):
    if (
        get_case_service_type(case_id)
        != SERVICE_TYPE_SOLAR
    ):
        raise ValueError(
            "太陽光・蓄電池案件ではありません。"
        )

    slot = str(
        slot or ""
    ).strip().upper()

    publication = (
        get_solar_vendor_view_publication(
            case_id=case_id,
            slot=slot,
        )
    )

    if not publication:
        raise ValueError(
            "業者向け閲覧URLがありません。"
        )

    timestamp = now_text()

    update_sheet_range(
        (
            f"{SOLAR_VENDOR_VIEW_SHEET_NAME}!"
            f"H{publication['row_number']}:"
            f"J{publication['row_number']}"
        ),
        [[
            "公開停止",
            timestamp,
            timestamp,
        ]],
    )

    clear_sheet_request_cache()

    return (
        get_solar_vendor_view_publication(
            case_id=case_id,
            slot=slot,
        )
    )


def solar_vendor_view_is_expired(
    expires_at,
):
    expires_at = str(
        expires_at or ""
    ).strip()

    if not expires_at:
        return True

    try:
        expires_dt = datetime.strptime(
            expires_at,
            "%Y-%m-%d %H:%M:%S",
        ).replace(
            tzinfo=timezone(
                timedelta(hours=9)
            )
        )
    except Exception:
        return True

    now_jst = datetime.now(
        timezone(
            timedelta(hours=9)
        )
    )

    return now_jst > expires_dt



def format_solar_vendor_money(
    value,
):
    if value in (
        None,
        "",
    ):
        return "-"

    try:
        number = float(value)

        if number.is_integer():
            number = int(number)

        return (
            f"{number:,}円"
        )

    except Exception:
        return str(value)


def format_solar_vendor_number(
    value,
    unit="",
):
    if value in (
        None,
        "",
    ):
        return "-"

    try:
        number = float(value)

        if number.is_integer():
            text_value = str(
                int(number)
            )
        else:
            text_value = (
                f"{number:.2f}"
                .rstrip("0")
                .rstrip(".")
            )

        return (
            text_value + unit
        )

    except Exception:
        return (
            str(value)
            + unit
        )


def build_solar_vendor_estimate_items(
    share,
):
    summary = (
        share.get(
            "estimate_summary",
            {},
        )
        if isinstance(
            share,
            dict,
        )
        else {}
    )

    if not isinstance(
        summary,
        dict,
    ):
        summary = {}

    return [
        {
            "label":
                "見積総額",
            "value":
                format_solar_vendor_money(
                    summary.get(
                        "total_price_yen"
                    )
                ),
        },
        {
            "label":
                "太陽光容量",
            "value":
                format_solar_vendor_number(
                    summary.get(
                        "solar_capacity_kw"
                    ),
                    "kW",
                ),
        },
        {
            "label":
                "蓄電池容量",
            "value":
                format_solar_vendor_number(
                    summary.get(
                        "battery_capacity_kwh"
                    ),
                    "kWh",
                ),
        },
        {
            "label":
                "PCS容量",
            "value":
                format_solar_vendor_number(
                    summary.get(
                        "pcs_capacity_kw"
                    ),
                    "kW",
                ),
        },
        {
            "label":
                "ローン金利",
            "value":
                format_solar_vendor_number(
                    summary.get(
                        "loan_interest_rate_percent"
                    ),
                    "%",
                ),
        },
        {
            "label":
                "返済期間",
            "value":
                format_solar_vendor_number(
                    summary.get(
                        "loan_term_years"
                    ),
                    "年",
                ),
        },
        {
            "label":
                "月々返済額",
            "value":
                format_solar_vendor_money(
                    summary.get(
                        "monthly_payment_yen"
                    )
                ),
        },
    ]


def get_solar_vendor_grade_display(
    grade,
):
    grade = str(
        grade or ""
    ).strip().upper()

    mapping = {
        "A": "A",
        "B": "B",
        "C": "C",
        "D": "D",
        "UNKNOWN":
            "判定保留",
    }

    return mapping.get(
        grade,
        grade or "判定保留",
    )


def build_solar_vendor_diagnosis_items(
    share,
):
    raw_items = (
        share.get(
            "diagnosis_summary",
            [],
        )
        if isinstance(
            share,
            dict,
        )
        else []
    )

    if not isinstance(
        raw_items,
        list,
    ):
        return []

    result = []

    for item in raw_items:
        if not isinstance(
            item,
            dict,
        ):
            continue

        result.append({
            "key":
                str(
                    item.get(
                        "key",
                        "",
                    )
                    or ""
                ),
            "label":
                str(
                    item.get(
                        "label",
                        "",
                    )
                    or ""
                ),
            "grade":
                str(
                    item.get(
                        "grade",
                        "",
                    )
                    or ""
                ),
            "grade_display":
                get_solar_vendor_grade_display(
                    item.get(
                        "grade",
                        "",
                    )
                ),
            "summary":
                str(
                    item.get(
                        "summary",
                        "",
                    )
                    or ""
                ),
        })

    return result


SOLAR_VENDOR_PUBLIC_HTML = """
<!doctype html>
<html lang="ja">
<head>
<meta charset="utf-8">

<meta
name="viewport"
content="width=device-width,initial-scale=1">

<title>
MITENOA 比較見積もりのご相談
</title>

<style>
body {
    margin:0;
    background:#f5f7f8;
    color:#1f2937;
    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        "Noto Sans JP",
        sans-serif;
}

.wrap {
    max-width:860px;
    margin:0 auto;
    padding:28px 16px 60px;
}

.brand {
    font-size:22px;
    font-weight:800;
    letter-spacing:.08em;
}

.copy {
    margin-top:3px;
    color:#64748b;
    font-size:13px;
}

.card {
    margin-top:18px;
    padding:22px;
    background:#fff;
    border:1px solid #e2e8f0;
    border-radius:12px;
}

h1 {
    margin:0 0 10px;
    font-size:24px;
}

h2 {
    margin:0 0 14px;
    font-size:18px;
}

.note {
    line-height:1.8;
    font-size:14px;
}

.alert {
    margin-top:14px;
    padding:12px 14px;
    background:#fff8e8;
    border:1px solid #e5c77a;
    border-radius:8px;
    color:#92400e;
    font-size:13px;
    line-height:1.7;
}

.meta-grid {
    display:grid;
    grid-template-columns:
        repeat(
            auto-fit,
            minmax(220px,1fr)
        );
    gap:10px;
}

.meta-item {
    padding:12px;
    background:#f8fafc;
    border-radius:8px;
}

.meta-label {
    display:block;
    margin-bottom:4px;
    color:#64748b;
    font-size:12px;
}

.meta-value {
    font-weight:600;
    word-break:break-word;
}

.estimate-grid {
    display:grid;
    grid-template-columns:
        repeat(
            auto-fit,
            minmax(210px,1fr)
        );
    gap:10px;
}

.estimate-item {
    padding:14px;
    background:#f8fafc;
    border:1px solid #e2e8f0;
    border-radius:8px;
}

.estimate-label {
    display:block;
    margin-bottom:5px;
    color:#64748b;
    font-size:12px;
}

.estimate-value {
    font-size:17px;
    font-weight:700;
}

.diagnosis-list {
    display:grid;
    gap:10px;
}

.diagnosis-item {
    padding:15px;
    border:1px solid #e2e8f0;
    border-radius:9px;
    background:#fff;
}

.diagnosis-head {
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
    margin-bottom:8px;
}

.diagnosis-label {
    font-weight:700;
}

.grade {
    display:inline-block;
    padding:4px 9px;
    background:#f1f5f9;
    border-radius:999px;
    font-size:12px;
    font-weight:700;
    white-space:nowrap;
}

.grade-unknown {
    background:#fff7ed;
    color:#9a3412;
}

.diagnosis-summary {
    color:#475569;
    font-size:14px;
    line-height:1.75;
}

.footer-note {
    color:#64748b;
    font-size:12px;
    line-height:1.7;
}
</style>

</head>

<body>

<div class="wrap">

<div class="brand">
MITENOA
</div>

<div class="copy">
決めるのは、見てから。
</div>


<div class="card">

<h1>
比較見積もりのご相談
</h1>

<p class="note">
MITENOAを通じて比較見積もりを
希望されているお客様の情報です。
以下は、お客様が施工会社への共有に
同意した範囲の情報です。
</p>

<div class="alert">
アップロードされた見積書原本は
共有対象ではありません。
このページにも表示されません。
</div>

</div>


<div class="card">

<h2>
お客様情報
</h2>

<div class="meta-grid">

<div class="meta-item">
<span class="meta-label">
氏名
</span>
<div class="meta-value">
{{ share.name or "-" }}
</div>
</div>

<div class="meta-item">
<span class="meta-label">
電話番号
</span>
<div class="meta-value">
{{ share.phone or "-" }}
</div>
</div>

<div class="meta-item">
<span class="meta-label">
メールアドレス
</span>
<div class="meta-value">
{{ share.email or "-" }}
</div>
</div>

<div class="meta-item">
<span class="meta-label">
設置地域
</span>
<div class="meta-value">
{{ share.municipality or "-" }}
</div>
</div>

</div>

</div>


<div class="card">

<h2>
相談内容
</h2>

<p class="note">
{{ share.consultation or "-" }}
</p>

</div>


<div class="card">

<h2>
現在の見積概要
</h2>

<div class="estimate-grid">

{% for item in estimate_items %}

<div class="estimate-item">

<span class="estimate-label">
{{ item.label }}
</span>

<div class="estimate-value">
{{ item.value }}
</div>

</div>

{% endfor %}

</div>

</div>


<div class="card">

<h2>
MITENOA診断概要
</h2>

{% if diagnosis_items %}

<div class="diagnosis-list">

{% for item in diagnosis_items %}

<div class="diagnosis-item">

<div class="diagnosis-head">

<div class="diagnosis-label">
{{ item.label or "-" }}
</div>

<span
class="grade
{% if item.grade == 'UNKNOWN' %}
grade-unknown
{% endif %}
">
{{ item.grade_display }}
</span>

</div>

<div class="diagnosis-summary">
{{ item.summary or "-" }}
</div>

</div>

{% endfor %}

</div>

{% else %}

<p class="note">
診断概要はありません。
</p>

{% endif %}

</div>


<div class="card">

<h2>
閲覧情報
</h2>

<div class="meta-grid">

<div class="meta-item">

<span class="meta-label">
閲覧先
</span>

<div class="meta-value">
{{ publication.company_name }}
</div>

</div>


<div class="meta-item">

<span class="meta-label">
有効期限
</span>

<div class="meta-value">
{{ publication.expires_at }}
</div>

</div>

</div>


<p class="footer-note">
このURLは指定された提携候補業者向けに
発行された期限付きURLです。
第三者への転送は行わないでください。
</p>

</div>

</div>

</body>
</html>
"""


@app.route(
    "/solar/vendor/<token>",
    methods=["GET"],
)
def solar_vendor_public_view(token):
    g._solar_public_read_only = True

    if not str(token or "").strip():
        return (
            "この閲覧URLは無効です。",
            404,
        )

    publication = (
        get_solar_vendor_view_publication(
            token=token,
            ensure=False,
        )
    )

    if not publication:
        return (
            "この閲覧URLは無効です。",
            404,
        )

    if (
        publication.get(
            "publish_status"
        )
        != "公開中"
    ):
        return (
            "この閲覧URLは公開停止されています。",
            410,
        )

    if solar_vendor_view_is_expired(
        publication.get(
            "expires_at"
        )
    ):
        return (
            "この閲覧URLの有効期限は終了しています。",
            410,
        )

    case_id = publication.get(
        "case_id",
        "",
    )

    compare_request = (
        get_solar_compare_request(
            case_id
        )
    )

    # 顧客が比較見積希望または
    # 情報共有同意を撤回した場合は、
    # 発行済みURLも即時閲覧不可。
    if (
        not compare_request
        or compare_request.get(
            "request_status"
        )
        != "希望あり"
        or compare_request.get(
            "consent_status"
        )
        != "同意済み"
    ):
        return (
            "お客様の情報共有同意が"
            "現在有効ではないため閲覧できません。",
            410,
        )

    assignments = (
        get_solar_vendor_assignments(
            case_id
        )
    )

    slot = publication.get(
        "slot",
        "",
    )

    assignment = assignments.get(
        slot,
        {},
    )

    if (
        assignment.get(
            "vendor_id"
        )
        != publication.get(
            "vendor_id"
        )
        or assignment.get(
            "contact_status"
        )
        != "打診済み"
    ):
        return (
            "現在の業者割当と一致しないため"
            "閲覧できません。",
            410,
        )

    contact_event = (
        get_solar_contact_event_for_publication(
            publication
        )
    )

    if not contact_event:
        return (
            "共有情報を確認できません。",
            410,
        )

    if (
        contact_event.get(
            "estimate_document_shared"
        )
        != "いいえ"
    ):
        return (
            "共有範囲を確認できません。",
            410,
        )

    if (
        contact_event.get(
            "consent_version"
        )
        != publication.get(
            "consent_version"
        )
    ):
        return (
            "同意記録を確認できません。",
            410,
        )

    try:
        validate_solar_contact_current_consent(
            compare_request,
            contact_event,
        )
    except ValueError:
        return (
            "現在の情報共有同意と"
            "打診記録が一致しないため"
            "閲覧できません。",
            410,
        )

    share = contact_event.get(
        "shared_snapshot",
        {},
    )

    if (
        not isinstance(share, dict)
        or not share
    ):
        return (
            "共有情報を確認できません。",
            410,
        )

    track_solar_event(
        "solar_vendor_view",
        page_type="vendor",
    )

    estimate_items = (
        build_solar_vendor_estimate_items(
            share
        )
    )

    diagnosis_items = (
        build_solar_vendor_diagnosis_items(
            share
        )
    )

    return render_template_string(
        SOLAR_VENDOR_PUBLIC_HTML,
        publication=publication,
        share=share,
        estimate_items=
            estimate_items,
        diagnosis_items=
            diagnosis_items,
    )


def ensure_solar_compare_sheet():
    SHEETS_PERF_ENSURE_CALLS['ensure_solar_compare_sheet'] = (
        SHEETS_PERF_ENSURE_CALLS.get('ensure_solar_compare_sheet', 0)
        + 1
    )
    service = get_sheets_service()

    titles = get_sheet_titles_cached()

    if SOLAR_COMPARE_SHEET_NAME not in titles:
        (
            service
            .spreadsheets()
            .batchUpdate(
                spreadsheetId=SPREADSHEET_ID,
                body={
                    "requests": [
                        {
                            "addSheet": {
                                "properties": {
                                    "title":
                                        SOLAR_COMPARE_SHEET_NAME
                                }
                            }
                        }
                    ]
                },
            )
            .execute()
        )
        clear_sheet_titles_request_cache()

    update_solar_header_range(
        (
            f"{SOLAR_COMPARE_SHEET_NAME}!"
            "A1:M1"
        ),
        [
            SOLAR_COMPARE_HEADERS
        ],
    )

# =========================================================
# solarシート構造確認 TTLキャッシュ
#
# 管理画面表示ごとの
# spreadsheets.get + header updateを抑制する。
# 5分経過後は再確認する。
# =========================================================

import time as _solar_ensure_time


def _wrap_solar_ensure_with_ttl(
    func,
    ttl_seconds=300,
):
    state = {
        "last_ok": 0.0,
    }

    def wrapped(*args, **kwargs):
        if (
            has_request_context()
            and getattr(
                g,
                "_solar_public_read_only",
                False,
            )
        ):
            return None

        now = (
            _solar_ensure_time.monotonic()
        )

        if (
            state["last_ok"]
            and (
                now
                - state["last_ok"]
            )
            < ttl_seconds
        ):
            return None

        result = func(
            *args,
            **kwargs,
        )

        state["last_ok"] = (
            _solar_ensure_time.monotonic()
        )

        return result

    wrapped.__name__ = (
        getattr(
            func,
            "__name__",
            "wrapped_solar_ensure",
        )
    )

    return wrapped


ensure_solar_ai_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_ai_sheet
    )
)

ensure_solar_diagnosis_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_diagnosis_sheet
    )
)

ensure_solar_result_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_result_sheet
    )
)

ensure_solar_compare_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_compare_sheet
    )
)

ensure_solar_vendor_contact_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_vendor_contact_sheet
    )
)

ensure_solar_vendor_view_sheet = (
    _wrap_solar_ensure_with_ttl(
        ensure_solar_vendor_view_sheet
    )
)




def get_solar_compare_request(
    case_id,
):
    ensure_solar_compare_sheet()

    case_id = str(
        case_id or ""
    ).strip()

    if not case_id:
        return None

    rows = get_sheet_values(
        (
            f"{SOLAR_COMPARE_SHEET_NAME}!"
            "A2:M"
        )
    )

    for row_number, row in enumerate(
        rows,
        start=2,
    ):
        row = row + [""] * max(
            0,
            13 - len(row),
        )

        if (
            str(row[0] or "").strip()
            != case_id
        ):
            continue

        try:
            shared_snapshot = (
                json.loads(
                    row[7]
                )
                if row[7]
                else {}
            )
        except Exception:
            shared_snapshot = {}

        return {
            "row_number": row_number,
            "case_id": row[0],
            "requested_at": row[1],
            "request_status": row[2],
            "consent_status": row[3],
            "consented_at": row[4],
            "withdrawn_at": row[5],
            "consent_version": row[6],
            "shared_snapshot":
                shared_snapshot,
            "updated_at": row[8],
            "operation_status":
                row[9] or "未対応",
            "shared_contractor":
                row[10],
            "estimate_document_shared":
                row[11],
            "admin_memo":
                row[12],
        }

    return None


def build_solar_compare_share_snapshot(
    case_id,
):
    # 公開可能な確認済み診断であることを先に保証
    extraction, diagnosis = (
        validate_solar_result_publishable(
            case_id
        )
    )

    detail = get_solar_detail_record(
        case_id
    ) or {}

    diagnosis_summary = []

    for (
        key,
        label,
    ) in SOLAR_DIAGNOSIS_CATEGORIES:

        item = diagnosis.get(
            key,
            {},
        )

        diagnosis_summary.append({
            "key": key,
            "label": label,
            "grade":
                item.get(
                    "grade",
                    "UNKNOWN",
                ),
            "summary":
                item.get(
                    "summary",
                    "",
                ),
        })

    estimate_summary = {
        "total_price_yen":
            extraction.get(
                "total_price_yen"
            ),
        "solar_capacity_kw":
            extraction.get(
                "solar_capacity_kw"
            ),
        "battery_capacity_kwh":
            extraction.get(
                "battery_capacity_kwh"
            ),
        "pcs_capacity_kw":
            extraction.get(
                "pcs_capacity_kw"
            ),
        "loan_interest_rate_percent":
            extraction.get(
                "loan_interest_rate_percent"
            ),
        "loan_term_years":
            extraction.get(
                "loan_term_years"
            ),
        "monthly_payment_yen":
            extraction.get(
                "monthly_payment_yen"
            ),
    }

    return {
        "name":
            detail.get(
                "name",
                "",
            ),
        "phone":
            detail.get(
                "phone",
                "",
            ),
        "email":
            detail.get(
                "email",
                "",
            ),
        "municipality":
            detail.get(
                "municipality",
                "",
            ),
        "consultation":
            detail.get(
                "consultation",
                "",
            ),
        "estimate_summary":
            estimate_summary,
        "diagnosis_summary":
            diagnosis_summary,

        # 原本ファイルはこの同意対象には含めない
        "estimate_document_shared":
            False,
    }


def save_solar_compare_consent(
    case_id,
    shared_snapshot,
):
    ensure_solar_compare_sheet()

    timestamp = now_text()

    existing = get_solar_compare_request(
        case_id
    )

    shared_json = json.dumps(
        shared_snapshot,
        ensure_ascii=False,
        separators=(
            ",",
            ":",
        ),
    )

    if existing:
        update_sheet_range(
            (
                f"{SOLAR_COMPARE_SHEET_NAME}!"
                f"B{existing['row_number']}:"
                f"I{existing['row_number']}"
            ),
            [[
                existing.get(
                    "requested_at"
                )
                or timestamp,
                "希望あり",
                "同意済み",
                timestamp,
                "",
                SOLAR_COMPARE_CONSENT_VERSION,
                shared_json,
                timestamp,
            ]],
        )

    else:
        (
            get_sheets_service()
            .spreadsheets()
            .values()
            .append(
                spreadsheetId=SPREADSHEET_ID,
                range=(
                    f"{SOLAR_COMPARE_SHEET_NAME}!"
                    "A:M"
                ),
                valueInputOption="USER_ENTERED",
                insertDataOption="INSERT_ROWS",
                body={
                    "values": [[
                        case_id,
                        timestamp,
                        "希望あり",
                        "同意済み",
                        timestamp,
                        "",
                        SOLAR_COMPARE_CONSENT_VERSION,
                        shared_json,
                        timestamp,
                        "未対応",
                        "",
                        "いいえ",
                        "",
                    ]]
                },
            )
            .execute()
        )

    clear_sheet_request_cache()

    return get_solar_compare_request(
        case_id
    )



def update_solar_compare_operation(
    case_id,
    operation_status,
    shared_contractor="",
    estimate_document_shared="いいえ",
    admin_memo="",
):
    record = get_solar_compare_request(
        case_id
    )

    if not record:
        raise ValueError(
            "比較見積もり受付情報がありません。"
        )

    operation_status = str(
        operation_status or ""
    ).strip()

    if (
        operation_status
        not in SOLAR_COMPARE_STATUSES
    ):
        raise ValueError(
            "対応ステータスが不正です。"
        )

    if (
        record.get(
            "consent_status"
        )
        != "同意済み"
        and operation_status
        in {
            "打診中",
            "紹介済み",
            "見積取得済み",
            "成約",
        }
    ):
        raise ValueError(
            "情報共有同意が有効ではないため、"
            "このステータスには変更できません。"
        )

    requested_estimate_document_shared = str(
        estimate_document_shared or ""
    ).strip()

    # 現在の比較見積もり同意では、
    # 顧客がアップロードした見積書原本は
    # 業者への共有対象に含まれていない。
    #
    # 原本共有は別途明示同意機能を実装するまで禁止する。
    if (
        requested_estimate_document_shared
        == "はい"
    ):
        raise ValueError(
            "現在の顧客同意では"
            "見積書原本は共有対象外です。"
            "原本共有には別途明示同意が必要です。"
        )

    estimate_document_shared = "いいえ"

    timestamp = now_text()

    update_sheet_range(
        (
            f"{SOLAR_COMPARE_SHEET_NAME}!"
            f"J{record['row_number']}:"
            f"M{record['row_number']}"
        ),
        [[
            operation_status,
            str(
                shared_contractor or ""
            ).strip(),
            estimate_document_shared,
            str(
                admin_memo or ""
            ).strip(),
        ]],
    )

    update_sheet_range(
        (
            f"{SOLAR_COMPARE_SHEET_NAME}!"
            f"I{record['row_number']}"
        ),
        [[timestamp]],
    )

    clear_sheet_request_cache()

    return get_solar_compare_request(
        case_id
    )


def withdraw_solar_compare_consent(
    case_id,
):
    record = get_solar_compare_request(
        case_id
    )

    if not record:
        raise ValueError(
            "比較見積もりの受付情報がありません。"
        )

    timestamp = now_text()

    update_sheet_range(
        (
            f"{SOLAR_COMPARE_SHEET_NAME}!"
            f"C{record['row_number']}:"
            f"I{record['row_number']}"
        ),
        [[
            "希望撤回",
            "同意撤回",
            record.get(
                "consented_at",
                "",
            ),
            timestamp,
            record.get(
                "consent_version",
                SOLAR_COMPARE_CONSENT_VERSION,
            ),
            json.dumps(
                record.get(
                    "shared_snapshot",
                    {},
                ),
                ensure_ascii=False,
                separators=(
                    ",",
                    ":",
                ),
            ),
            timestamp,
        ]],
    )

    clear_sheet_request_cache()

    # -----------------------------------------
    # 情報共有同意の撤回と同時に、
    # 現在公開中の業者向け閲覧URLも停止する。
    #
    # 公開URL側でも現在の同意状態を再確認しているため、
    # ここで公開停止処理だけが一時的に失敗しても、
    # 顧客の同意撤回そのものは成立させる。
    # -----------------------------------------
    try:
        publications = (
            get_solar_vendor_view_publications(
                case_id
            )
        )

        for slot in (
            "A",
            "B",
            "C",
        ):
            publication = (
                publications.get(slot)
                if publications
                else None
            )

            if not publication:
                continue

            if (
                str(
                    publication.get(
                        "publish_status",
                        "",
                    )
                    or ""
                ).strip()
                != "公開中"
            ):
                continue

            revoke_solar_vendor_view_publication(
                case_id,
                slot,
            )

    except Exception:
        app.logger.exception(
            "solar vendor view auto revoke failed "
            "after consent withdrawal: case_id=%s",
            case_id,
        )

    return get_solar_compare_request(
        case_id
    )


