@app.route(
    "/solar",
    methods=["GET"],
)
def solar_public_top():

    track_solar_event(
        "solar_lp_view",
        page_type="solar_lp",
        referrer_category=solar_referrer_category(),
    )

    return render_template_string(
        SOLAR_LP_HTML,
        line_url=
            SOLAR_LINE_ADD_URL,
        hero_image_url=
            SOLAR_HERO_IMAGE_URL,
        solar_mobile_image_url=
            "/static/assets/solar/mobile_top.png",
        mitenoa_logo_url=
            MITENOA_LOGO_URL,
    )


@app.route(
    "/solar/diagnosis",
    methods=["GET", "POST"],
)
def solar_diagnosis():
    form = {
        "postal_code": "",
        "municipality": "",
        "estimate_amount": "",
        "consultation": "",
        "name": "",
        "phone": "",
        "email": "",
        "privacy_consent": False,
    }

    error = ""
    field_errors = {}
    csrf_error = False

    if request.method == "GET":
        track_solar_event(
            "solar_diagnosis_view",
            page_type="diagnosis",
            referrer_category=solar_referrer_category(),
        )

    if request.method == "POST":
        try:
            validate_csrf()

            track_solar_event(
                "solar_diagnosis_submit_attempt"
            )

            form = {
                "postal_code":
                    request.form.get(
                        "postal_code",
                        "",
                    ).strip(),

                "municipality":
                    request.form.get(
                        "municipality",
                        "",
                    ).strip(),

                "estimate_amount":
                    request.form.get(
                        "estimate_amount",
                        "",
                    ).strip(),

                "consultation":
                    request.form.get(
                        "consultation",
                        "",
                    ).strip(),

                "name":
                    request.form.get(
                        "name",
                        "",
                    ).strip(),

                "phone":
                    request.form.get(
                        "phone",
                        "",
                    ).strip(),

                "email":
                    request.form.get(
                        "email",
                        "",
                    ).strip(),

                "privacy_consent":
                    (
                        request.form.get(
                            "privacy_consent",
                            "",
                        )
                        == "1"
                    ),
            }

            if not form["municipality"]:
                raise ValueError(
                    "市区町村を入力してください。"
                )

            if not form["consultation"]:
                raise ValueError(
                    "相談内容を入力してください。"
                )

            if len(form["consultation"]) > 3000:
                raise ValueError(
                    "相談内容は3000文字以内で入力してください。"
                )

            if not form["name"]:
                raise ValueError(
                    "お名前を入力してください。"
                )

            if (
                not form["phone"]
                and not form["email"]
            ):
                raise ValueError(
                    "電話番号またはメールアドレスを"
                    "入力してください。"
                )

            if form["email"] and not re.fullmatch(
                r"[^@\s]+@[^@\s]+\.[^@\s]+",
                form["email"],
            ):
                raise ValueError(
                    "メールアドレスを正しく入力してください。"
                )

            if form["phone"] and not re.fullmatch(
                r"[0-9０-９+()（）\-\s]{8,20}",
                form["phone"],
            ):
                raise ValueError(
                    "電話番号を正しく入力してください。"
                )

            if not form["privacy_consent"]:
                raise ValueError(
                    "個人情報の取扱いへの同意が必要です。"
                )

            estimate_amount = ""

            if form["estimate_amount"]:
                parsed_amount = parse_money(
                    form["estimate_amount"]
                )

                if (
                    parsed_amount is None
                    or parsed_amount <= 0
                ):
                    raise ValueError(
                        "現在の見積金額を正しく"
                        "入力してください。"
                    )

                estimate_amount = int(
                    parsed_amount
                )

            estimate_file = request.files.get(
                "estimate_file"
            )

            has_estimate_file = (
                validate_solar_estimate_file(
                    estimate_file
                )
            )

            # 入力・ファイル検証がすべて通った後に
            # 初めて案件を作成する。
            case_id = create_case(
                "",
                form["municipality"],
                service_type=
                    SERVICE_TYPE_SOLAR,
                use_line_state=False,
            )

            try:
                update_case_column(
                    case_id,
                    "AC",
                    "セカンドオピニオン",
                )

                update_case_column(
                    case_id,
                    "AG",
                    form["consultation"],
                )

                if has_estimate_file:
                    update_case_column(
                        case_id,
                        "AI",
                        "書面見積あり",
                    )
                else:
                    update_case_column(
                        case_id,
                        "AI",
                        "見積書なし",
                    )

                save_solar_customer_info(
                    case_id,
                    form["name"],
                    form["municipality"],
                    form["phone"],
                )

                upload_result = (
                    save_solar_estimate_file(
                        estimate_file,
                        case_id,
                    )
                )

                consent_at = now_text()

                save_solar_case_detail(
                    case_id,
                    form["postal_code"],
                    form["municipality"],
                    form["name"],
                    form["phone"],
                    form["email"],
                    form["consultation"],
                    estimate_amount,
                    upload_result[
                        "filename"
                    ],
                    upload_result[
                        "storage_path"
                    ],
                    consent_at,
                )

                clear_sheet_request_cache()

            except Exception:
                # 受付途中で失敗した場合、
                # 作成済み案件を残して原因追跡できるようにする。
                # 自動削除は行わない。
                raise

            track_solar_event(
                "solar_diagnosis_success",
                page_type="diagnosis",
            )

            return render_template_string(
                SOLAR_DIAGNOSIS_COMPLETE_HTML,
                case_id=case_id,
            )

        except ValueError as e:
            error = str(e)
            track_solar_event(
                "solar_diagnosis_validation_error",
                error_category=solar_validation_error_category(
                    error
                ),
            )
            error_field_map = {
                "市区町村": ["municipality"],
                "相談内容": ["consultation"],
                "お名前": ["name"],
                "電話番号またはメールアドレス": ["phone", "email"],
                "メールアドレス": ["email"],
                "電話番号": ["phone"],
                "個人情報の取扱い": ["privacy_consent"],
                "現在の見積金額": ["estimate_amount"],
                "金額は": ["estimate_amount"],
                "見積書": ["estimate_file"],
                "アップロードされた見積書": ["estimate_file"],
            }
            for prefix, fields in error_field_map.items():
                if error.startswith(prefix):
                    field_errors.update(
                        {field: error for field in fields}
                    )
                    break

        except Forbidden:
            csrf_error = True
            track_solar_event(
                "solar_diagnosis_validation_error",
                error_category="csrf",
            )
            error = (
                "セキュリティ確認に失敗しました。"
                "ページを再読み込みして再度お試しください。"
            )

        except Exception as e:
            track_solar_event(
                "solar_diagnosis_validation_error",
                error_category="other",
            )
            print(
                "SOLAR DIAGNOSIS ERROR:",
                type(e).__name__,
                flush=True,
            )

            error = (
                "受付処理中にエラーが発生しました。"
                "時間をおいて再度お試しください。"
            )

    response = render_template_string(
        SOLAR_DIAGNOSIS_HTML,
        form=form,
        error=error,
        field_errors=field_errors,
        csrf_token=get_csrf_token(),
    )

    if csrf_error:
        return response, 403

    return response


